WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[47652] = { title = "The Light Mother", description = "We must know for sure whether the Light Mother survived, {name}.\n\nXe'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade.\n\nLet's head into the Xenedar and look for her. Light willing, she will return to guide us once more.", objectives = "" }
WordHunterWoW_QuestEN[47653] = { title = "Light's Return", description = "Xe'ra has been saved! We have won an important victory here.\n\nThe Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain...\n\nRomuul should be able to teleport us back to the ship now. Let me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[47654] = { title = "Seat of the Triumvirate: The Crest of Knowledge", description = "We have all that we need now, {name}.\n\nAlleria Windrunner awaits your arrival at the Seat of the Triumvirate.\n\nDo not go alone, my friend. You will need allies to recover the Crest of Knowledge... and endure what L'ura has become.\n\nI will prepare the Vindicaar and await your return. Light be with you in that dark place.", objectives = "" }
WordHunterWoW_QuestEN[47659] = { title = "Hunt the Hunter", description = "Please, help us. De Frogmarsh is under siege! My master, de great loa, Krag'wa, is not willing to bend to de will of de blood trolls and their dark god. So now, dey are taking his power by force! Dey are slaying his children and taking his totems of power. Dey will even take Krag'wa and sacrifice him if we are not able to end dis madness!\n\nStop dem! Slay their leader. Perhaps dat will slow dem down for a while. It will give me time to find a more permanent solution.", objectives = "" }
WordHunterWoW_QuestEN[47660] = { title = "Fallen Idols", description = "De blood trolls seek to weaken Krag'wa and take his power. Dey steal his idols of power to crack open and feed their magic.\n\nSalvage what idols you can. Dey will be needed to make Krag'wa strong. Strong enough to fight dem off once and for all.", objectives = "" }
WordHunterWoW_QuestEN[47663] = { title = "A Timely Summons from Shattrath", description = "The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City, and lend her your aid.", objectives = "" }
WordHunterWoW_QuestEN[47685] = { title = "Gatekeeper's Challenge: Cunning", description = "Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic.\n\nI doubt you can relate.\n\nThe path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning.\n\nTo preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.", objectives = "" }
WordHunterWoW_QuestEN[47686] = { title = "Not-So-Humble Beginnings", description = "Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening.\n\nTo the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures.\n\nIt will be guarded, no doubt. We will leverage the expertise of Fareeya's forces here to follow this trail.", objectives = "" }
WordHunterWoW_QuestEN[47687] = { title = "Gatekeeper's Challenge: Mastery", description = "Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage.\n\nYou will fight what remains of Archimonde's greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now.\n\nTheir echoes will try to kill you.\n\nBest all three with all your limbs intact and I will recognize your strength.", objectives = "" }
WordHunterWoW_QuestEN[47688] = { title = "Invasive Species", description = "We should seek out an alternate source of energy just in case I am wrong about the conduits.\n\nLuckily enough, I think I know where we can find one.\n\nThe panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers.\n\nThis is no time to be gentle with the environment--panthara devour energy to survive.\n\nSlay them and see if you cannot reclaim some of the power they have consumed.", objectives = "" }
WordHunterWoW_QuestEN[47689] = { title = "Gatekeeper's Challenge: Tenacity", description = "My master Archimonde was not known for his willingness to suffer indecision.\n\nHe preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him.\n\nAt the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you.\n\n Emerge unscathed and I will be forced to consider your will strong enough to proceed.", objectives = "" }
WordHunterWoW_QuestEN[47690] = { title = "The Defiler's Legacy", description = "It seems you are not so easily deterred. Very well.\n\nYour deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success.\n\nThe greatest of your challenges lies before you.\n\nYou must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil.\n\nFew have overcome this obstacle. I hope he does not make too much of a mess of you.", objectives = "" }
WordHunterWoW_QuestEN[47691] = { title = "A Non-Prophet Organization", description = "I have complete faith that Velen is nearby. We would know if he had been captured.\n\nAll the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance.\n\nThat is why I am going with you.\n\nWe will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.", objectives = "" }
WordHunterWoW_QuestEN[47695] = { title = "Sound the Alarm", description = "Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around?\n\nSince you're already going down there... mind culling their numbers a bit?", objectives = "" }
WordHunterWoW_QuestEN[47696] = { title = "Krag'wa the Terrible", description = "Your previous attack has angered the blood trolls. They now send an army to take everything. They are too late! I am Krag'wa! I will not be eaten, I do the eating!\n\nMeet me at the edge of Razorjaw River. You will bear witness to my power, and I will bear witness to yours.", objectives = "" }
WordHunterWoW_QuestEN[47697] = { title = "Krag'wa's Aid", description = "Well done, {name}!\n\nBefore we left, I heard dat Princess Talanji be headed ta Gloom Hollow. She should be dere by now.\n\nWe better be headin' back. She would want ta hear da tale of ya success!", objectives = "" }
WordHunterWoW_QuestEN[47706] = { title = "Hunt for King K'tal", description = "Hunters! Dis challenge be for de King of de Preserves.\n\nKing K'tal is a mighty predator, smart and fast. Gold and honor await de hunter who brings me de head of de King.", objectives = "" }
WordHunterWoW_QuestEN[47709] = { title = "The Great Gnomeregan Run", description = "Ready for the big race today, {name}?\n\nEvery year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay!\n\nIt reminds us that no goal is too tall, even for us!  Whether you run fast or slow, alone or with friends, you'll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!", objectives = "" }
WordHunterWoW_QuestEN[47711] = { title = "Head of the Viper", description = "While I was scouting out the area, I saw a big armored naga bossing the rest of the snakes around. Call it a hunch, but I'm pretty sure he's their leader.\n\nAs long as the Naga have a commander our operations here will be threatened. Take him out.", objectives = "" }
WordHunterWoW_QuestEN[47716] = { title = "Searching the Ruins", description = "Dese dunes are crawling with assassins. Nowhere is safe, but we must press on.\n\nDe ruins aren't far from here. \n\nLet's continue our search on foot.", objectives = "" }
WordHunterWoW_QuestEN[47725] = { title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", objectives = "" }
WordHunterWoW_QuestEN[47726] = { title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", objectives = "" }
WordHunterWoW_QuestEN[47727] = { title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", objectives = "" }
WordHunterWoW_QuestEN[47733] = { title = "The Loa-Speaker's Betrayal", description = "Listen, stranger. I don't have a lot of time left.\n\nI was in de village when Zolani brought de king to us. Said to keep it a secret, or else Zul would find us.\n\nLook around. Dey found us!\n\nBut I know... I know it was not de prophet's doing. Our loa-speaker gave Zolani her pretty words, said she would help, then turned around and sold us out.\n\nIt is Kihara's fault dat we are dying now. She brought dis upon us!\n\nKill her... Make her pay!", objectives = "" }
WordHunterWoW_QuestEN[47734] = { title = "Partners in Heresy", description = "Rezan struggles against his bonds, but we cannot reach him.\n\nDe mogu dat Zul called here have raised a shield dat rejects my magic. Find and kill de creatures dat stand between me and my loa.\n\nI must gather myself for de fight to come. They will know de wrath of TWO kings before dis day is done.", objectives = "" }
WordHunterWoW_QuestEN[47735] = { title = "Ancient Tortollan Remedies", description = "Ah, yes, the situation is urgent. We must act quickly, but not hastily.\n\nThere is a way to save Rastakhan, but it will require three very specific ingredients. Listen well, young one.\n\nThe first, foam bubbling from the mouth of a crab. The older, the better.\n\nThe second, the spine of a puffer fish. Venomous!\n\nThe third, a brutosaur scale.\n\nWhy? These are the secrets of my people, {name}. Longevity is cultivated like the rarest of flowers... carefully, and with much practice.", objectives = "" }
WordHunterWoW_QuestEN[47736] = { title = "Heads Will Roll", description = "Zul's forces try to lay claim to de loa of kings's temple.\n\nYou must teach dese traitors de meaning of their actions.\n\nSweep de temple of de filth dat defiles it. Destroy those who spit in de face of de loa. Bring me their heads so I may remind others of what happens to those who betray their faith and their king.\n\nWhen you are finished dealing with de unworthy, come find us. Rezan's altar lies deep within de temple grounds.\n\nIn Rastakhan's name, heads will roll!", objectives = "" }
WordHunterWoW_QuestEN[47737] = { title = "The Temple of Rezan", description = "De chronicler's words are dire. If Zul truly does wish to sacrifice Rezan...\n\nDis will not come to pass! I will defend my loa with my life.\n\nCome, {name}, we go to de Temple of Rezan. We must stop dis heresy at once!", objectives = "" }
WordHunterWoW_QuestEN[47738] = { title = "The Will of the Loa", description = "Jol's remedy healed Rastakhan's flesh. But his spirit is still lost. Dere is only one thing stopping him now.\n\nDeath.\n\nHe is walking in Bwonsamdi's shadow. For most, dere would be nothing to be done. But... he is bound to another loa. A loa who gives life to his faithful.\n\nYou must call on Rezan, loa of kings, and ask him to claim back Rastakhan's soul.\n\nUp de path, you will find my tent. Place dis idol and wait dere. If we are lucky, he will aid us.\n\nIf not... It was nice knowing you.", objectives = "" }
WordHunterWoW_QuestEN[47739] = { title = "The Scent of Vengeance", description = "I know my king, and I know he is not weak willed. His spirit struggles under de weight of dis betrayal, and confusion roots his spirit too close to death for my comfort.\n\nWe will need to remind him of his purpose. His anger.\n\nI have heard shouts of terror from de village below. Zul's followers torment Zeb'ahari while dey hunt for him. Slay those who would harm his people and bring me their blood.\n\nPerhaps de scent of vengeance can revive de devilsaur inside ol' Rastakhan.", objectives = "" }
WordHunterWoW_QuestEN[47740] = { title = "House of the King", description = "I hear Rezan's call. I will answer, but first you must help me.\n\nOur loa give us many boons, and we repay dem in worship. Offerings, sacrifices, and idols are our tools to earn favor, but dey are much more to our loa.\n\nDey are sources of strength.\n\nZul's dogs have begun to corrupt de great golden statues dedicated to Rezan. Even now, I can feel his power dwindling.\n\nStop dem. Cleanse de idols to de great hunter. Teach dem to respect de house of de king.", objectives = "" }
WordHunterWoW_QuestEN[47741] = { title = "To Sacrifice a Loa", description = "Rezan's power is fading. My usurpers have nearly completed their task.\n\nI have read of de horrors of Zul'Drak, and I have seen de results of dese acts. To think one of my own people would bring dis heresy here is... unimaginable.\n\n<Rastakhan snarls in anger.>\n\nCome! We will end dis traitor who spits in de face of all loa!\n\nDi chuka Rezan!", objectives = "" }
WordHunterWoW_QuestEN[47742] = { title = "Zul's Mutiny", description = "A ship such as Rastakhan's Might does not readily sail without her crew.\n\nDat means de Zandalari aboard have succumbed to Zul's machinations and have betrayed their king as surely as he has.\n\nBoard my ship. Kill those who think to rise against their king. We will take no prisoners.\n\nDe punishment for de crime of mutiny is death!", objectives = "" }
WordHunterWoW_QuestEN[47743] = { title = "The Child of Light and Shadow", description = "It is time, {name}.\n\nXe'ra is returned to us. We have Light's Heart. We have her Chosen One.\n\nCome, let us restore her. Let us forge a bright new path against our foes.\n\nSpeak to me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[47744] = { title = "Smoke, Meat, and Pretty Flowers", description = "Back of town's on lockdown, kid. And yes, I do have a key, but you're a stranger.\n\n<Emery pats his pocket gingerly.>\n\nListen, I'd like to help you out. You've got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o' yellow flowers, and I might be able to make an exception.", objectives = "" }
WordHunterWoW_QuestEN[47745] = { title = "Yeah, Definitely for the Kids", description = "I don't know if you've ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and...\n\n...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they're from me. For the kids.", objectives = "" }
WordHunterWoW_QuestEN[47746] = { title = "Holing Up", description = "Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street!\n\n<Meliana regains her composure.>\n\nI need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky.\n\nChildren! Everybody, get into the house!", objectives = "" }
WordHunterWoW_QuestEN[47747] = { title = "Fight Plague with Fire", description = "One final request of you, stranger. I've seen what's happening outside, and I've heard about this \"plague\". I don't want to go down without a fight.\n\nI have enough rum in the back of this bar to set this whole tavern on fire, but I don't have the tools to do it safely. Fetch me a flint and some rope, and I'll give you my key to the backstreets of Stratholme.", objectives = "" }
WordHunterWoW_QuestEN[47750] = { title = "For Emery", description = "We do have plenty of food here, however. If you're braving the streets, please deliver this venison to that big dummy at the tavern.\n\nTell him it's from the kids.", objectives = "" }
WordHunterWoW_QuestEN[47751] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[47754] = { title = "Lightly Roasted", description = "Can you hear me, {name}? Good.\n\nLight's Judgment has been installed on the Vindicaar. We should be able to harness its power immediately.\n\nWe can use it both to clear the rubble blocking the Xenedar as well as destroy our enemies.\n\nAs with any new piece of technology, we should test it out. Thoroughly. I trust you have plenty of targets down there.", objectives = "" }
WordHunterWoW_QuestEN[47755] = { title = "Captured and Enraptured", description = "You gotta help me! Me and my crew were running late on a delivery, so we decided to take a detour through this grotto ahead. Boy... that was a mistake. This place is crawling with sirens!\n\nIf there's one thing my men like more than women, it's grog! Here, take some. Use it to bring them back to their senses. Might be best to rough 'em up a bit to weaken the enchantment.", objectives = "" }
WordHunterWoW_QuestEN[47771] = { title = "Locating the Longshot", description = "We're going to need a bigger gun if we hope to free Xe'ra.\n\nOne of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he's found the main cannon of the ship.\n\nIf you head over that way, make sure he hasn't died, will you?", objectives = "" }
WordHunterWoW_QuestEN[47772] = { title = "Sky Ablaze With Cannonfire", description = "Oh! It's me! And {name}, was it? I remember this!\n\nI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.\n\nThink you could take it out for me?", objectives = "" }
WordHunterWoW_QuestEN[47773] = { title = "Sky Ablaze With Cannonfire", description = "Oh! It's me! And {name}, was it? I remember this!\n\nI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.\n\nThink you could take it out for me?", objectives = "" }
WordHunterWoW_QuestEN[47807] = { title = "Worried About My Friends", description = "I've heard about some trouble over at the black dragonshrine. I know, I'm a bronze dragon, but still! I worry about them sometimes! They weren't ALWAYS so grumpy.\n\nIf you're going there anyways, would you mind taking care of... whatever's causing so much of a disturbance?", objectives = "" }
WordHunterWoW_QuestEN[47808] = { title = "The Dead Walk", description = "Greetings, {race}. I know you are here in the service of the bronze, but I have a request of you.\n\nThe Ruby Dragonshrine is plagued by undead. My shrine's wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?", objectives = "" }
WordHunterWoW_QuestEN[47809] = { title = "Darkness in the Ley", description = "A strange, dark disturbance perturbs the ley lines in my flight's dragonshrine. Do you have the time to investigate?", objectives = "" }
WordHunterWoW_QuestEN[47810] = { title = "Darkened Dreams", description = "The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?", objectives = "" }
WordHunterWoW_QuestEN[47811] = { title = "Whispers from the Shadows", description = "It seems the Necrodark cult has been lurking in the shadows, waiting for their chance to free the Grey One. My absence from Highmountain weaked the wards and gave them their chance.\n\nThe final ward lies deep with the twisting tunnels of Neltharion's Vault. Navarrogg knows those tunnels like the back of his hand. Seek out his aid.\n\nYou have learned much by walking in the footsteps of ancient heroes, {name}. But the future of our mountain depends upon what you do this day.", objectives = "" }
WordHunterWoW_QuestEN[47835] = { title = "The Hand of Fate", description = "{name},\n\nWe have won many battles against the Burning Legion, but it is time to end this war once and for all. \n\nFinal preparations have begun to depart for Argus.\n\nMake haste to Bladefist Bay. A ship awaits you there to grant you and your allies passage to Azuremyst.", objectives = "" }
WordHunterWoW_QuestEN[47851] = { title = "Sealing Fate: Marks of Honor", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[47853] = { title = "Flanking Maneuvers", description = "I will take command of Fareeya's lieutenants and we will escort Velen to the Crest of Knowledge. His mission must not fail.\n\nWe face an old foe-- one the Army of the Light has encountered on numerous occasions. Talgath will try to block us in and prevent our retreat.\n\nYou must not let that happen. Find out how he is bringing in his forces and cut them off. All we need is time to get in and get out.\n\nWe are counting on you.", objectives = "" }
WordHunterWoW_QuestEN[47854] = { title = "Wrath of the High Exarch", description = "Where the Legion is concerned, violence is always the answer.\n\n<Turalyon hefts his blade with a grim expression.>\n\nThey are between us and Velen. Nothing will stop them from finding him unless we act. Now is not the time to hold back.\n\nTogether we will sow chaos among their ranks.", objectives = "" }
WordHunterWoW_QuestEN[47855] = { title = "What Might Have Been", description = "<Velen continues to stare at the statue as he speaks.>\n\nThousands of years ago, when I was young, I made a choice.\n\nA choice that allowed my world to fall to ruin. A choice that made my people exiles. A choice that forever separated me from my beloved brothers.\n\n<Velen shakes his head.>\n\nI cannot leave, not yet. Not until I have had a chance to reflect.", objectives = "" }
WordHunterWoW_QuestEN[47856] = { title = "Across the Universe", description = "Talgath. There was a time I called him an ally, a friend.\n\nI put my trust in him when it came time to leave Argus. I asked him to call out to the others who would join me.\n\nI gave him all that he needed to betray me and slaughter my followers.\n\nI do not know what brought this hatred to lurk in his heart, but his machinations repeatedly forced my people to flee world after world. He made it his mission to hunt us across the universe.\n\nThis must end, {name}. Talgath must die.", objectives = "" }
WordHunterWoW_QuestEN[47864] = { title = "Sealing Fate: Additional Marks of Honor", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[47865] = { title = "Sealing Fate: Piles of Marks of Honor", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[47867] = { title = "Two If By Sea", description = "The draenei have crafted a vessel to take us to Argus safely. They are gathering the invasion force on Azuremyst Isle as we speak. \n\nWe will join them there by sea. The Legion is no doubt keeping a close eye on the gateway to their world. We must retain the element of surprise.\n\nLet me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[47868] = { title = "The Necropolis", description = "A deal is a deal, and I pay my debts.\n\nBwonsamdi is a mighty loa and you are going to need a powerful ritual to obtain his attention.\n\nYou are in luck. I already know exactly what needs to be done.\n\nBwonsamdi's temple, de Necropolis, is just to de north. Meet me in de courtyard and we shall see about obtaining an audience with de loa of death.", objectives = "" }
WordHunterWoW_QuestEN[47870] = { title = "Dead Men Tell No Tales", description = "I'm an employee of the Ashvane Company. We're number one in the Azerite trade. \n\nWhen I took this job, no one told me it would be a one-way trip!\n\nI'd do just about anything to escape these dunes, including working with you.\n\nMaybe we can help each other out?\n\nI'd be willing to part with the code to the captain's lockbox, if you're willing to help me escape this wretched desert.\n\nFor my plan to succeed, my expedition party needs to die. Can't have them telling anyone I'm missing...", objectives = "" }
WordHunterWoW_QuestEN[47871] = { title = "Seafaring Necessities", description = "She might not be much to look at, but this boat will take me back to Boralus. \n\nBefore my voyage can begin, I'll need a few seafaring necessities. \n\nLuckily, everything I need can be found in the Ashvane encampment.", objectives = "" }
WordHunterWoW_QuestEN[47873] = { title = "The Captain's Cache", description = "Well, I'm sure you've figured it out by now, eh?\n\nI never was fixing to abandon the crew, I just wanted to move up the ranks. You've helped me out a great deal in that respect.\n\nSpeaking of respect, I believe there's the matter of Captain Hartford's lockbox...\n\nHere's the code, courtesy of the fallen captain. Just as I promised. It's all yours!\n\nNow, don't go telling anyone about our little arrangement, okay? I wouldn't want something like that to spoil such a profitable partnership!", objectives = "" }
WordHunterWoW_QuestEN[47874] = { title = "Clearing the Fog", description = "Did you lead Kaja here? I told her not to come after me. It isn't safe...\n\nMy mind remains fogged, but de memories are slowly returning. Jakra'zet... de weapon...\n\nCome, let us find some fresh air. I will tell you what I've discovered.", objectives = "" }
WordHunterWoW_QuestEN[47880] = { title = "A Tribute for Death", description = "Everything for de ritual is together. Now, it is time to begin. \n\nFor dis to work, I must chant de words of old. It is an exhausting task, so I need you to take my mojo fetish and draw de ritual circle, then beat upon de drums.\n\nIf all goes well, Bwonsamdi may invite us into de temple.\n\nIf not, our souls are forfeit.\n\nLet's not make any mistakes.", objectives = "" }
WordHunterWoW_QuestEN[47882] = { title = "Conservation of Magic", description = "I have an idea. This construct will be of use to us. We simply need to jolt it awake.\n\nWe once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just.\n\nTake this.\n\n<Y'mera hands you a brightly glowing crystal.>\n\nIt will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so.\n\nStabilizing a few should allow us to access the whole network.", objectives = "" }
WordHunterWoW_QuestEN[47883] = { title = "The Longest Vigil", description = "It was a good thing we sought two sources of energy. Even with the conduits active, the construct has not stirred.\n\nIt has likely been inactive a long while. Perhaps as long as Eredath has floated above Argus.\n\nWhat a long, lonely vigil it must have been.\n\n<Y'mera is silent for a moment as she peers at the construct.>\n\nGo ahead and jostle it a little. That combined with one last burst of magic ought to do the trick.", objectives = "" }
WordHunterWoW_QuestEN[47889] = { title = "The Speaker Calls", description = "Magni sent for you to meet him in the Krokul Hovel. He has found something that he believes could help us overcome the Legion's infinite armies.\n\nWe need every advantage we can muster if we are to see this war through. You should seek him out.", objectives = "" }
WordHunterWoW_QuestEN[47890] = { title = "Visions of Torment", description = "I've been hearin' whispers ever since we got to Argus. They're just like Azeroth's, only... they ain't hers.\n\nI'm convinced that Argus has a titan of its own that's reachin' out to us!\n\nThe broken have a relic stowed away that's darn near holy to 'em. Hatuun says they hear whispers from it... I think it might have some sort o' link to Argus itself!\n\nIt's just in this chamber. Let's see what we can learn.", objectives = "" }
WordHunterWoW_QuestEN[47891] = { title = "Dire News", description = "Azeroth was right in sendin' us here, {name}. We have to stop whatever it is Sargeras is plannin', or we may not have a home left to save when this is all over.\n\nYe should go back to Turalyon and let him know what ye've seen. I'll stay here and see if I can't glean anything else that might help us.", objectives = "" }
WordHunterWoW_QuestEN[47892] = { title = "Storming the Citadel", description = "We have already secured ground near Nath'raxas Hold. It is one of the Legion's chief military fortifications on Argus.\n\nStriking it now, and hard, may be our only opportunity to tip the scales in our favor.", objectives = "" }
WordHunterWoW_QuestEN[47894] = { title = "Jump Around", description = "", objectives = "" }
WordHunterWoW_QuestEN[47895] = { title = "Bert's Bots", description = "If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach.\n\nWhat I'm saying is that I need to put these bots to the test! A real, live-action field demo.\n\nAre your pets up for a code review?", objectives = "" }
WordHunterWoW_QuestEN[47897] = { title = "Zanchuli Traitors", description = "Dey are trying to cast down our loa, claiming dem to be false gods.\n\nDey have turned to de old ways of blood, sacrifice, and subjugation.\n\nI cannot even begin to say how offensive dis is. Kill any of dese traitors you find.", objectives = "" }
WordHunterWoW_QuestEN[47904] = { title = "Preserve the True Future", description = "I know how this looks, {name}. I'm not asking for your help simply because I don't want to get killed.\n\nI need your help because this isn't how I'm SUPPOSED to die. I will die - I've seen it! - but it happens much later than this. Besides, meddling with the timeways for personal reasons - well, it goes against pretty much everything my dragonflight stands for.\n\nLet's stop all four of the dragonshrine attacks. That should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[47906] = { title = "The Deaths of Chromie", description = "It looks like we're going to have to stop all eight attacks on me. In one fifteen-minute span.\n\nEven to me, that doesn't seem like a lot of time.\n\nStill, if anybody can do it, it's us. Are you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[47915] = { title = "Rescuing the Taken", description = "We are doing our best to contain de fighting in Zanchul and not let it spill out into de other terraces, but we can't hold for long.\n\nIf you are going to help, start by freeing Wardruid Loti. Dey are trying to break her on de platform above with a dark ritual.\n\nHer soul is bound to a fetish. You must find dat fetish if you are going to free her.", objectives = "" }
WordHunterWoW_QuestEN[47918] = { title = "To Serve Krag'wa", description = "There are other forces who seek to disturb my frogs. The vile naga attack my shores and drain my frogs of their magic!\n\nThey seek to use my followers as a feast for their thirst for mana. It must be stopped!\n\nA powerful shadow hunter named Narez is currently fighting them. You must go aid her and stop the naga from feasting on my frogs!", objectives = "" }
WordHunterWoW_QuestEN[47919] = { title = "Just Say No to Cannibalism", description = "Of course the Natha'vor trolls have Shoak! Why would it be easy?\n\nI'm sick and tired of running from these trolls. That's why you're going in to end this.\n\nThe Natha'vor trolls have three powerful troll witch doctors called \"corpse mongers\". Take them out and you'll send the tribe into disarray.\n\nOf course, this could all fail spectacularly and make my terrible day even worse.", objectives = "" }
WordHunterWoW_QuestEN[47924] = { title = "Profanity Filter", description = "I hate this place! I just want to go home, but I can't because that oaf, Shoak, is missing.\n\nListen, {race}t, I'll make it worth your while if you help me find that dunce.\n\nI've got a way to find Shoak, but of COURSE these stupid totems are blocking my magic! Why wouldn't they?\n\nTake this scroll and use its magic to burn these totems. I'm going to look around to see if that bonehead is just sleeping somewhere.", objectives = "" }
WordHunterWoW_QuestEN[47925] = { title = "Shoak's on the Menu", description = "I don't know what stupid thing Shoak did to get captured by the Natha'vor trolls, we'll find out once you rescue him.\n\nI bet they're getting ready to make a meal out of Shoak. You need to work fast and get him out! \n\nShoak's one of the largest oafs that I know, those trolls won't be happy that you're taking their \"meal\" away.", objectives = "" }
WordHunterWoW_QuestEN[47928] = { title = "Offering for the Loa", description = "The time has come for you to make contact with the great loa Eraka no Kimbul.\n\nI can only imagine what it will be like to be in the presence of such an ancient and powerful deity. You have earned the Ring of Tides, so it must be you that addresses the loa. \n\nPlease present the loa with this offering from our tribe. Tell him of our plight against the naga.\n\nEraka no Kimbul is our only hope of survival now.", objectives = "" }
WordHunterWoW_QuestEN[47939] = { title = "If the Key Fits...", description = "These Ashvane are unreasonable. I've tried to bargain for my release, but they refuse any offer I bring to the table. \n\nAll they want is whatever's bubbling up in that mine. My kind know better than to go near that stuff. It's volatile.\n\nThere are prisoners in the mine being forced to extract it. Us in the cages? We're back up. When someone dies in the mines, they just send another in. \n\nIf you release me, I'll make sure you're rewarded! We just need to find the right key for this cage...", objectives = "" }
WordHunterWoW_QuestEN[47943] = { title = "Crab Trapping", description = "We are trapped here with little in the way of food and supplies.\n\nThe territorial sethrak control the land to the west, and the spiteful naga the waters to the east. We are caught between a barren desert and a hostile ocean.\n\nIf you are headed to the lagoon to face the naga, will you bring us back some crabs to eat?\n\nI fear that our tribe will soon perish without food...", objectives = "" }
WordHunterWoW_QuestEN[47945] = { title = "To Market, To Market", description = "Thanks heaps for getting us out of that pickle, mainlander. I'd hate to ask, but would you be willing to help with another matter?\n\nEven before this curse struck the village, our sausage shipments from Carver's Harbor started slowing down. If we don't get them sausages, I won't be able to feed my family!\n\nCan you help an honest sausage merchant out? Carver's Harbor is just down the road from here.", objectives = "" }
WordHunterWoW_QuestEN[47946] = { title = "Save Their Bacon", description = "This is going to sound strange, {class}, but some of my workers were turned into pigs! Lucky I was out on an errand, or I'd have been caught too! Now my people are tied up awaiting... processing. \n\n<Thomas suppresses the urge to retch.>\n\nI can't get past those monsters, but you look like the sort who could. Not sure if this helps, but I coulda sworn I heard some wild cackling coming from the warehouse.\n\nPlease... save my people!", objectives = "" }
WordHunterWoW_QuestEN[47947] = { title = "Big Bad Wolves", description = "Wolves with strange, glowing eyes have taken over the area! I don't know what they are or why they're glowing but it cannot mean anything good. They have to be removed!\n\nPlease, {class}, slay them before more of my friends are killed.", objectives = "" }
WordHunterWoW_QuestEN[47948] = { title = "Pork Chop", description = "Roland Hacksaw was the best butcher I've ever worked with... but he's gone insane! He's still processing pigs into sausage!\n\nYou have to stop him!", objectives = "" }
WordHunterWoW_QuestEN[47949] = { title = "That's Not My Fetish", description = "<The glassy eyes of the pig fetish seem to follow you as you approach. The dark power emanating from the witch's fetish must be what is keeping the workers transformed. \n\nPerhaps Thomas Staughton might have some idea what to do with it.>", objectives = "" }
WordHunterWoW_QuestEN[47950] = { title = "Cured Ham", description = "That foul thing has to be what's keeping my men transformed into pigs.\n\nHmm. Well there isn't too much that can withstand a good cleansing fire! I say we burn it! \n\nToss it into the campfire!", objectives = "" }
WordHunterWoW_QuestEN[47952] = { title = "The Missing Fleet", description = "The tidesage order has a sizable monastery right here in Boralus. I say we start our search for the fleet there.\n\nSomeone there has to know something, right? You don't just lose the entire legendary Kul Tiran fleet on accident!\n\nWe'll need to take a ferry over to the monastery. Make sure you bring your pass with you!", objectives = "" }
WordHunterWoW_QuestEN[47959] = { title = "The Warguard's Trail", description = "Rakera's journal suggested she moved south. It's de only lead we have. \n\nMeerah is headed dat way, and has invited us to travel with her. \n\nThese vulpera know de desert better than any troll I've ever met. \n\nOur chances of survival are highest if we travel together.", objectives = "" }
WordHunterWoW_QuestEN[47960] = { title = "Tiragarde Sound", description = "We must convince Katherine Proudmoore to pledge Kul Tiras to the Alliance. Flynn believes the Ashvane Trading Company's new gunpowder is our best lead.", objectives = "" }
WordHunterWoW_QuestEN[47961] = { title = "Drustvar", description = "The stalwart protectors of House Waycrest hold fast along the western border, but recently all contact with them has been lost. We must secure their aid in order to bring Kul Tiras together under the Proudmoore banner.", objectives = "" }
WordHunterWoW_QuestEN[47962] = { title = "Stormsong Valley", description = "The Kul Tiran fleet has been lost at sea. The tidesages of Stormsong, with their mystical oceanic magic, may be our only way to locate the fleet of legend.", objectives = "" }
WordHunterWoW_QuestEN[47963] = { title = "The Ancient One", description = "Dis is far worse than I thought. Pa'ku is crying out in my mind. Dey are doing something to her. Something old and terrible, smelling of de old ways.\n\nShe is nearby, just south of here. Come, {name}, meet me at Pa'ku's roost and we'll rescue her.", objectives = "" }
WordHunterWoW_QuestEN[47965] = { title = "The Ruined Temple", description = "The loa may be our only hope against the naga, but the temple lies abandoned and broken.\n\nTwo of my tribe have gone ahead to scout the ruins. They may be able to help you make contact with Eraka no Kimbul.\n\nIf the spirit of the loa remains at the temple, we must find a way for him to hear our plight.", objectives = "" }
WordHunterWoW_QuestEN[47967] = { title = "An Argus Roper", description = "My warriors stand no chance against even the smallest of the Legion's forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.", objectives = "" }
WordHunterWoW_QuestEN[47968] = { title = "Signs and Portents", description = "<The bulletin that Mayor White was posting at the time he was struck by the spell indicates that there have been some strange happenings in the town lately. \n\nIt is likely these events are connected to whatever cast this spell on the village.\n\nPerhaps there might be records from other villagers that could shed some light on the source of this magic.>", objectives = "" }
WordHunterWoW_QuestEN[47978] = { title = "The Wayward Crone", description = "<The ledger indicates that an old woman named Helena Gentle recently took up residence in a house down the road from the town.\n\nThe villagers' writings point to her being involved somehow with a variety of maladies that struck the village recently. \n\nIt's possible that she may know what's behind this spell, if it hasn't afflicted her as well.>", objectives = "" }
WordHunterWoW_QuestEN[47979] = { title = "Witch Hunt", description = "A curse on the villagers? Oh my, how dreadful!\n\nAlthough, to be honest, there have been some strange happenings around Fallhaven of late. I wonder if these could be culprit?\n\nTake a seat and have a spot of tea. I'll tell you all that I know.", objectives = "" }
WordHunterWoW_QuestEN[47980] = { title = "Furious Familiars", description = "<The wildlife in the foothills appear to be under Helena's spell, and this villager appears to be one of their victims. \n\nThey must be the cause of the recent disappearances from Fallhaven.\n\nPerhaps if their numbers were cut down, they would pose less of a threat to the townspeople.>", objectives = "" }
WordHunterWoW_QuestEN[47981] = { title = "Cracking the Curse", description = "<In her haste, it looks like Helena left her spellbook behind. The pages of this book detail the ritual that she used to entrap the villagers of Fallhaven. \n\nIt seems the effigy holding the spell in the village is protected by smaller ones surrounding the town. If these are destroyed, you may be able to affect the one holding the spell on the townsfolk.>", objectives = "" }
WordHunterWoW_QuestEN[47982] = { title = "The Final Effigy", description = "<The effigy's protection has been broken.\n\nAll that remains is to break the effigy itself.>", objectives = "" }
WordHunterWoW_QuestEN[47986] = { title = "Scars of the Past", description = "The Army of the Light's warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return.\n\nMy modifications to this frame should give us the edge we need, but several critical components are still missing.\n\nThere are remains of battles past in Nath'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.", objectives = "" }
WordHunterWoW_QuestEN[47987] = { title = "Preventive Measures", description = "There is no end to the Legion's depravity. Every battle won, every world conquered, yields more souls to fuel their war machine.\n\nThey have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter.\n\nThey deserve a better fate.", objectives = "" }
WordHunterWoW_QuestEN[47988] = { title = "Chaos Theory", description = "Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are.\n\nThe plan is simple. Let chaos reign in their ranks, and the day will be ours.", objectives = "" }
WordHunterWoW_QuestEN[47989] = { title = "Heralds of Apocalypse", description = "We've been presented with a rare opportunity.\n\nOur scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion's war effort.\n\nThe inner circle of Sargeras' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.", objectives = "" }
WordHunterWoW_QuestEN[47990] = { title = "A Touch of Fel", description = "Our warframe is almost operational! It just needs a good jolt to revitalize its systems.\n\nWarlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe's Judgment Core!", objectives = "" }
WordHunterWoW_QuestEN[47991] = { title = "Dark Machinations", description = "Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe.\n\nThe spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.", objectives = "" }
WordHunterWoW_QuestEN[47992] = { title = "Dawn of Justice", description = "Thanks to your efforts, our enemy is in disarray and their defenses inoperable.\n\nWe must take the ground at the spire's base and tighten the noose around their commander's neck.\n\nYou have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.", objectives = "" }
WordHunterWoW_QuestEN[47993] = { title = "Lord of the Spire", description = "Lord Nath'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago.\n\nMake no mistake, he is powerful, but he has also grown overconfident in his seat.\n\nTake advantage of his hubris and make use of the warframe's firepower while you can. We will storm the courtyard shortly!", objectives = "" }
WordHunterWoW_QuestEN[47994] = { title = "Forming a Bond", description = "", objectives = "" }
WordHunterWoW_QuestEN[47995] = { title = "Overt Ops", description = "My soldiers are out there, {name}.\n\nI need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads.\n\nInform them that their orders are to regroup with the Prophet at once.\n\nThe time for subtlety has passed. There is a small army between us and them. Do what you must.\n\nLight keep you safe.", objectives = "" }
WordHunterWoW_QuestEN[47998] = { title = "Killing Cannibals", description = "Shoak and I have had a few run-ins with the Natha'vor trolls. Must be why they wanted to capture that idiot.\n\nThe women in that tribe actually eat the men... and anyone else they can get their hands on. I'm sure they're getting ready to eat Shoak.\n\nDo us all a favor and kill some of those cannibals. The world would be a better place without them.", objectives = "" }
WordHunterWoW_QuestEN[48002] = { title = "Limited Supplies", description = "Hello, {name}. It's good to see a fellow alchemist again.\n\nI've been supplying our camp with necessary potions to deal with the demons, but lately I've been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning.\n\nI try to recycle as much as I can, so you see, those vials are precious to me. If you'd be willing to go out and retrieve them, I could show you what I've been making to help combat the demons.", objectives = "" }
WordHunterWoW_QuestEN[48003] = { title = "The Lord's Behest", description = "Lord Norwington will want to thank you for saving his son himself. Why don't you come to the estate? We're preparing for a festival, and everybody's welcome.\n\nWe'll go ahead and tell him of all that has happened. See you there!", objectives = "" }
WordHunterWoW_QuestEN[48004] = { title = "Beginner Equitation", description = "You may know how to ride already, but you don't know how to ride like a Kul Tiran!\n\nWe'll let you borrow a horse for the festivities. Take one of our lesson masters, Cooper. He's trained many a beginner in his day!\n\nMount up, get in the ring, and show us what you've got! I'm sure you'll be a quick learner!", objectives = "" }
WordHunterWoW_QuestEN[48005] = { title = "Be Our Guest", description = "My dear friend {name}, I do hope you enjoy the festival. I throw it every year to bring riders from all over Kul Tiras together for a grand celebration of the sport!\n\nIn fact, you deserve the whole nine yards. Please, tour the estate at your leisure and partake in the delicious food and drink, introduce yourself to the people. I insist!", objectives = "" }
WordHunterWoW_QuestEN[48008] = { title = "Dangerous Cargo", description = "By the time I realized what was happening, it was too late.\n\nPeople had been acting strange, but I thought nothing of it. After all, they seemed to still be doing their jobs.\n\nWhile inspecting some of the cargo, this grub jumped out in an attempt to latch onto my face. I managed to take it out, but it was too late.\n\nAll of the shipments are infected. Take this torch. Destroy them.", objectives = "" }
WordHunterWoW_QuestEN[48009] = { title = "Betrayal of the Guard", description = "My boys have gotten in too deep.\n\nThey've given in to whatever dark forces are at work here.\n\nDo not hesitate to do what you need to and put them down. They knew what they were signing up for when they picked the wrong side.", objectives = "" }
WordHunterWoW_QuestEN[48013] = { title = "Tracking the Trackers", description = "{name}, have I told you about my tracking potion? Our scouts use it to track demons, especially their \"fiends\".\n\nThose particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb.\n\nIf you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits.\n\nI could also teach you the recipe for this potion for your effort.", objectives = "" }
WordHunterWoW_QuestEN[48014] = { title = "Clear the Riffraff", description = "The naga sent their tiny, foul, muck-smelling minions into our camp. They are quite bothersome. \n\nIf we do nothing, and their numbers continue to grow, they could pose a threat.\n\nYou look quick and handy. Could you perhaps expunge a few for us?", objectives = "" }
WordHunterWoW_QuestEN[48015] = { title = "The Scrolls of Gral", description = "These gilblins are ridiculous! They are like a swarm of angry bees, buzzing around.\n\nHmm, maybe not bees. Bees are useful, and make honey, and don't steal things.\n\nThey ransacked our scrolls. Most were unusable, but there were three that are quite... potent. \n\nIt would be most unfortunate if those made it back to their masters, the naga. Please clean up their mess and bring back our scrolls.", objectives = "" }
WordHunterWoW_QuestEN[48016] = { title = "Ascending Alchemy", description = "I've seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... \"alchemist stones\"?\n\nI can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that's often found amongst the herbs.\n\nI'm certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.", objectives = "" }
WordHunterWoW_QuestEN[48021] = { title = "Chromie", description = "{name}. Is that you?\n\nI'm convinced that something unusual has happened in the timelines. I need your help!\n\nCome find me at Wyrmrest Temple, in Dragonblight, and I'll show you.", objectives = "" }
WordHunterWoW_QuestEN[48023] = { title = "Orders Received", description = "We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. \n\nDey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders.\n\nGet me some of dem scrolls so we can be seein' who be callin' da shots.", objectives = "" }
WordHunterWoW_QuestEN[48025] = { title = "Saving for Later", description = "We need time to recover the artifacts from this place. Time the naga will not let us have.\n\nHowever, we do have a plan.\n\nWe simply hide what we don't want them to find, and then come back in a decade or two. They will have forgotten about this place by then.\n\nTake this illusion scroll and use it to conceal the notable artifacts of power.", objectives = "" }
WordHunterWoW_QuestEN[48026] = { title = "Beneath the Waves", description = "Those witches dare! In my temple? \n\nSiavass is stretching past the realm of that which she can comprehend. There is a darkness seeking them, and they call to it! Her kind will become no more than a hollow tool to those who may answer.\n\nI feel it moving beneath us, around us. I feel it like a tremor through my being. \n\nThere is a pressure there, it has a weight greater than that of the deepest ocean. \n\nWe must stop them. They are not welcome here!", objectives = "" }
WordHunterWoW_QuestEN[48027] = { title = "The Glory of Argus", description = "<Amazed that anything so pure could continue to grow on this planet, you pick the flower from the ground. You feel a small power radiate from it and then vanish.>\n\n<As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.>", objectives = "" }
WordHunterWoW_QuestEN[48028] = { title = "Youthful Resistance", description = "<As you begin to gather the flowers, you realize that some of the younger blooms are still resistant to your approach and refuse to yield. Perhaps Funen might know more about how to handle the herb in its adolescent stages.>", objectives = "" }
WordHunterWoW_QuestEN[48029] = { title = "The Heart of It", description = "<Having handled astral glory for a while now, you've picked up on something interesting about its roots. Tightly wound in a cocoon, small flecks of light permeate through the cracks creating a shimmering effect.>\n\n<Perhaps Funen might be able to expand on the nature of these lights.>", objectives = "" }
WordHunterWoW_QuestEN[48034] = { title = "Empyrium Deposit Chunk", description = "<As you swing your pickaxe into the ore, it hits with a resounding thud, sending a small chunk of it to the ground. At this rate, it would take you all day to get a sufficient amount of ore from this deposit.>\n\n<Perhaps someone can give you some insight into how to mine this deposit properly.>", objectives = "" }
WordHunterWoW_QuestEN[48035] = { title = "Angling For a Better Strike", description = "<Looking at the empyrium dust from taking down this deposit, you wonder if there's a way to prevent part of the deposit from shattering with each impact.>\n\n<Perhaps Khamir will know something further that he can share with you.>", objectives = "" }
WordHunterWoW_QuestEN[48036] = { title = "Precision Perfected", description = "<While you've learned to extract as much of the deposit as you can, the core of the deposit is always left unusable. Looking closely, you can see where your strikes were causing fractures in its structure.>\n\n<One more lesson from Khamir might be needed to correct this problem.>", objectives = "" }
WordHunterWoW_QuestEN[48037] = { title = "Empyrium Seam Chunk", description = "<At first you thought the ore to have a mirrored surface, reflecting the starry space above you. After breaking off a chunk, you realize that the ore itself has a starry quality all of its own.>\n\n<Perhaps someone back at the Vindicaar can give you some insight on how to better extract these seams more efficiently.>", objectives = "" }
WordHunterWoW_QuestEN[48038] = { title = "Don't Just Pick At It", description = "<Even though you've learned to expose the ore, large chunks of it still seem to be embedded in the surrounding rock. Picking those pieces away may not result in the pure form of empyrium that you're looking for.>\n\n<Perhaps Khamir can show you a way to remove the ore from these sections of the seam.>", objectives = "" }
WordHunterWoW_QuestEN[48039] = { title = "Balancing the Break", description = "<Getting down to the root of the seam, you're left with nothing but small bits and pieces. Collectively though, they would have been enough to work with.>\n\n<Khamir might know a way to prevent this from happening.>", objectives = "" }
WordHunterWoW_QuestEN[48040] = { title = "Tainted Scraps", description = "<As you begin to carefully remove the skin from the corpse, you notice it quickly becoming corrupted by the decay of the creature.>\n\n<Pulling away, you were only able to extract a small amount of leather and something foul smelling. Perhaps someone on the Vindicaar might know more about this foul hide.>", objectives = "" }
WordHunterWoW_QuestEN[48041] = { title = "A Larger Cut", description = "<While you've become quicker at removing pieces of the hide, there is still much that is spoiled before you're able to remove it.>\n\n<Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>", objectives = "" }
WordHunterWoW_QuestEN[48042] = { title = "Order of Operations", description = "<The skins have been more abundant, but you're only able to gather a couple teeth and claws before they take on the corruption.>\n\n<Unsure as to how to extract as many teeth and claws as possible, you find yourself wanting to have one last conversation with Enstraa back at the Vindicaar.>", objectives = "" }
WordHunterWoW_QuestEN[48053] = { title = "Weigh Anchor", description = "{name}, I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships.\n\nI'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them?\n\nI heard there's a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn't be a long trip or anything.", objectives = "" }
WordHunterWoW_QuestEN[48054] = { title = "Weigh Anchor", description = "{name}, I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships.\n\nI'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them?\n\nI heard there's a portal to Orgrimmar in the Windrunner's Sanctuary here in Dalaran so it shouldn't be a long trip or anything.", objectives = "" }
WordHunterWoW_QuestEN[48055] = { title = "Empyrial Strength", description = "I see my armor's caught your interest. It's made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates.\n\nI could show you how to craft one, but you'll need to bring your own supplies, I'm afraid. Our stores of the ore are low and we need all that we have.\n\nBut here are the plans so you'll know what you need to find...", objectives = "" }
WordHunterWoW_QuestEN[48056] = { title = "A Harsh Mistress", description = "So there I was thinkin' about how to get everyone ready for movin' around Argul or whatever it's called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you're wearin' down there.\n\nNext thing I hear, the gravity on that planet? Completely the same as ours!\n\nRegardless, I figure I could get the prototype workin'. Mind givin' me a hand? Maybe when we're done you can like, sell 'em to kids or somethin'.", objectives = "" }
WordHunterWoW_QuestEN[48065] = { title = "Extraterrestrial Exploration", description = "{name}, I hear you've been over to that large green planet in the sky already. Swarming with demons too, I hear.\n\nI was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet.\n\nProblem is we need to get readings on the landscape, and I'd go, but uh... well I need to stay here and run the shop. Can't leave it to these bozos to handle.\n\nHere, take this and get some readings for me, will ya?", objectives = "" }
WordHunterWoW_QuestEN[48066] = { title = "A Feast for Our Kin", description = "Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion.\n\nAre you interested in hearing how they joined the Horde? It is quite the tale!\n\nIt all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...", objectives = "" }
WordHunterWoW_QuestEN[48067] = { title = "Shadow Over Thunder Bluff", description = "A dark force has descended upon us. I refuse to believe that the Highmountain are behind it.\n\nThe cacophony out there is disturbingly familiar. Could it be... \n\nNo! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, {name}!", objectives = "" }
WordHunterWoW_QuestEN[48068] = { title = "A Cure for Ebonhorn", description = "A dark force holds Spiritwalker Ebonhorn in its grip. I do not know if we possess the means to cure him, but we must try.\n\nI can think of a few of my kin who might have experience in dealing with such maladies.\n\nSeek out Nara Wildmane, Kador Cloudsong, and Aponi Brightmane. By combining their wisdom, I hope we find the answer we need.", objectives = "" }
WordHunterWoW_QuestEN[48069] = { title = "The Wrench Calls", description = "{name}, Didi the Wrench is looking for you back in Dalaran. You might want to see what she's working on. Pretty fancy stuff from what I heard.", objectives = "" }
WordHunterWoW_QuestEN[48070] = { title = "The Norwington Festival", description = "To whomever receives this invitation,\n\nYou are cordially invited to the 15th annual Norwington Equestrian and Hunt Festival!\n\nPeople of all walks of life from across Kul Tiras shall gather to delight in life's greatest competitions, equestrianism and hunting, while meeting those of like minds and fine tastes.\n\nHunting events shall start first, led by Abbey Watkins in Foxhollow Woods. They shall be followed by equestrian events at the Norwington Estate.\n\nWe hope to see you there posthaste!", objectives = "" }
WordHunterWoW_QuestEN[48074] = { title = "Looming Over Me", description = "When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom. Without it, I'm forced to labor for much longer to make garments of power for our allies.\n\nBut you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me?\n\nI'd be more than willing to share my knowledge of sewing lightweave with you.", objectives = "" }
WordHunterWoW_QuestEN[48075] = { title = "A Colorful Key", description = "{name}, I hear you're a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion.\n\nI hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs.\n\nBut you, you're strong, you could fight your way into my home and recover my book!\n\nHowever, I locked it away in a special chest that requires the gems of this land to unlock. You'll need one of each to open it.", objectives = "" }
WordHunterWoW_QuestEN[48076] = { title = "A Crowning Achievement", description = "With my book nearly being lost forever, it occurs to me that I shouldn't keep all this knowledge in one place. I would like to pass it along to you, {name}.\n\nMy most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns. Each one uses a different combination of gems to render different effects of power.\n\nLet me show you how to construct one and then I'll show you how different combinations of gems create different results.", objectives = "" }
WordHunterWoW_QuestEN[48077] = { title = "The Stoat Hunt", description = "One of the greatest hunting sports amongst the nobles of Boralus is the stoat hunt. It is a sport of determination, patience, and skill. Do you think you can rise to the challenge?\n\nStoats are agile, sneaky, and sharp. They're next to impossible to catch out in the forest, so the best way to find one is to find its burrow and scare it out.\n\nFind their burrows and bring back their pelts. Their fur is soft and much loved amongst the nobles.", objectives = "" }
WordHunterWoW_QuestEN[48078] = { title = "Counterbalancing", description = "In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts.\n\nNow I'm forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint.\n\nThe cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable.\n\nHere, take my oil and see for yourself.", objectives = "" }
WordHunterWoW_QuestEN[48079] = { title = "Return to Highmountain", description = "Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid.\n\nLet us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.", objectives = "" }
WordHunterWoW_QuestEN[48080] = { title = "An Element of Danger", description = "These nobles really think killing weasels is the mark of a good hunter? Ha!\n\nIt ain't hunting if there isn't a bit of danger involved. There are boars in these woods. That's more our speed out in the mountains! Why don't you kill some of those, then bring me their tusks as proof?", objectives = "" }
WordHunterWoW_QuestEN[48081] = { title = "A Floating Ruin", description = "We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment.\n\nI know of a relic on Eredath, my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us.\n\nPerhaps there we will find the salvation we so desperately need.", objectives = "" }
WordHunterWoW_QuestEN[48086] = { title = "Poaching the Poachers", description = "Da orders say Skrathax be da one snatchin' most of dem cute frogs.\n\nHe be haulin' lots of frogs ta da main camp. Ya need ta save dem cute dings from Skrathax before it be too late.\n\nI'll be workin' on scoutin' dere camp more. Dis Skrathax can't be da one leadin' all da naga here, but it'll help ta take him down.", objectives = "" }
WordHunterWoW_QuestEN[48087] = { title = "Equine Retrieval", description = "I like the cut of your jib, friend!\n\nI'll tell you what. The rest of the partygoers should be arriving any time now. Would you do me the honor of retrieving my favorite horse from the estate on the hill?\n\nImagine, our guests' first impression of you to be on the most regal horse in all of Tiragarde! Wondrous!", objectives = "" }
WordHunterWoW_QuestEN[48088] = { title = "No Party Like a Trogg Party", description = "Troggs? At my party?\n\nMy grandfather pushed them back to that cleft years ago to build this estate. To think that they would attack in such force after all these years?\n\nThis is just what we needed to make this year's festival the greatest ever!\n\nShow us your heroism firsthand, {name}! Mount Cooper and defeat these troggs! Drag them behind you, jab them with your harpoon... whatever it takes!", objectives = "" }
WordHunterWoW_QuestEN[48089] = { title = "Mountain Sounds", description = "Kul Tirans won't go down without a fight!\n\nTake this horn. We use it in the mountains to warn each other of danger and lead the charge into battle. Use it to rally our allies against the troggs!", objectives = "" }
WordHunterWoW_QuestEN[48090] = { title = "Krag'wa's Chosen", description = "Dis be a real mess, {name}. Da naga be drainin' da magic of Krag'wa's frogs ta feed demselves!\n\nDere be three frogs, Krag'wa's champions, dat dey be torturin' as we speak.\n\nTake dis potion, it be returnin' da power of dem noble frogs. Dey deserve better dan bein' drained by dese snake bastards.\n\nI be stayin' here. Da naga got in some lucky hits on me. All me life, I wanted ta see Krag'wa, and I let meself get hurt by some naga!", objectives = "" }
WordHunterWoW_QuestEN[48092] = { title = "Vengeance of the Frogs", description = "Da naga here be led by a priestess, Zaldraxia. She be da one dat figured out how ta drain da frogs of their magic.\n\nZaldraxia be stoppin' at nothin' ta drain every frog here.\n\nDo what I could not, and kill dis priestess. Show da naga dat Krag'wa ain't a loa ta be takin' lightly.\n\nI be prayin' ta Krag'wa for ya success.", objectives = "" }
WordHunterWoW_QuestEN[48104] = { title = "A Greater Challenge", description = "<this is a placeholder breadcrumb for a NYI POI.>", objectives = "" }
WordHunterWoW_QuestEN[48107] = { title = "The Sigil of Awakening", description = "This relic is too powerful to keep it out in the open.\n\nWe must return to the Vindicaar at once. The Prophet will know what to do.\n\nI did want to thank you, {name}. Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.", objectives = "" }
WordHunterWoW_QuestEN[48108] = { title = "The Waycrest Daughter", description = "You seek House Waycrest? Oh, your timing could not be worse!\n\nI had just received a raven regarding Lord Waycrest's daughter, Lucille, shortly before this... curse came upon us.  They apprehended her in Fletcher's Hollow and are taking her to trial.\n\nThey say she is a witch, herself! \n\nIf she's found guilty, she will surely hang! You must make haste to Hangman's Point.  With what you've seen here, maybe you can convince them of her innocence.", objectives = "" }
WordHunterWoW_QuestEN[48109] = { title = "The Woods Have Eyes", description = "The sooner I can return the lady Waycrest to Highroad Gate the better, but I will honor her wishes if we can assure her safety.\n\nThere are dark things happening in these lands that you don't fully understand. If we must dally, then there are measures that need be taken.\n\nFirst, the wildlife here can serve as eyes to dark powers. Kill them.", objectives = "" }
WordHunterWoW_QuestEN[48110] = { title = "In Case of Ambush", description = "There is more to worry about in these woods than simple beasts. Our enemy employs constructs of wicker and bone that can rip a man apart.\n\nFortunately for us, these constructs are not very perceptive.\n\nTake these traps and set them up throughout the woods behind us.  If our enemies do seek to ambush us here, at least these will slow their minions down.", objectives = "" }
WordHunterWoW_QuestEN[48111] = { title = "Trial by Superstition", description = "Witchcraft has long lived in the superstitions of the people here. It is only recently that some of these superstitions have become reality.\n\nAccording to tradition, one who is tried for witchcraft is allowed to choose the means by which they are tested from among the requests of her peers.\n\nThe villagers here no doubt have some strange beliefs of what witches can and cannot do. Speak with them, and see what we can do to prove my innocence.", objectives = "" }
WordHunterWoW_QuestEN[48113] = { title = "A Pungent Solution", description = "The first test should be simple enough. While I may not do so often, I am certainly capable of crying.\n\nThough to be honest, I've never had to cry on cue.\n\nMaybe you could help with that, though. Nearby there is an onion field that belonged to one of the local farmers. It's abandoned, and most of it is dried up by now, but you might be able to find one onion ripe enough in there to cause some tears.", objectives = "" }
WordHunterWoW_QuestEN[48165] = { title = "Harmful If Swallowed", description = "This last test I am not looking forward to, but it is certainly better than being set on fire. \n\nThey say that a witch can't get sick. We will prove to them that I can.\n\nA venom comes from the saurolisks nearby that is used by our healers when a child swallows something they shouldn't. When ingested, it will make you immediately ill, emptying the contents of the stomach.\n\nYou'll need several of their venom glands to get enough venom for an appropriate dose. Removing them intact may prove difficult.", objectives = "" }
WordHunterWoW_QuestEN[48170] = { title = "Once Bitten, Twice Shy", description = "I am all too familiar with the bloodfly's bite. We had them all over the fields surrounding Waycrest Manor.\n\nThough I'm loath to subject myself to them on purpose, if it will help convince these people, I am willing to deal with that nuisance. \n\nFind a jar and collect as many bloodflies as you can. They are common in these parts, and shouldn't be hard to find.", objectives = "" }
WordHunterWoW_QuestEN[48171] = { title = "The Curse of Fletcher's Hollow", description = "It's obvious the constable won't be swayed until we discover what happened at Fletcher's Hollow. I know very little myself--only that the village has been overrun by monstrous creatures.\n\nI must ask that you travel there in my stead and try to uncover what befell the village. I'm sure Marshal Reade will prevent the constable from harming me while you're away.\n\nDo this for me, and I will help you as I can.", objectives = "" }
WordHunterWoW_QuestEN[48176] = { title = "Big Trouble in Little Tortolla", description = "I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them.\n\nGo see what they want and you will have the favor of the King.\n\nAnd {name}, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.", objectives = "" }
WordHunterWoW_QuestEN[48179] = { title = "Rescue Rangers", description = "We're barely holding off those monsters here. If it hadn't been for the Thornspeakers, we'd surely be dead. I was worried Rebecca hadn't made it!\n\nYou've brought Rebecca's supplies just in time. We have many injured out in the field, Thornspeaker, ranger, and companion alike. I'll hold the line here. Go into the ruins and heal as many of the wounded as you can!", objectives = "" }
WordHunterWoW_QuestEN[48180] = { title = "Really Big Problem", description = "Hey! Mainlander!\n\nI know I'm supposed to be trying to knock over cairns and hauling out lost rangers, but d'you see that massive stone monster? I'm thinking that's gonna be a problem.\n\nYou look like you know how to handle yourself. Think between the two of us we can take it down?", objectives = "" }
WordHunterWoW_QuestEN[48182] = { title = "Total Cairnage", description = "My mentor sensed the activation of ancient powers here. We came to stop them but were too late. We banded together with the rangers for mutual protection, but our task remains unfinished.\n\nThere is a set of ancient cairns here. These help empower the Drust constructs. Destroying them will also help to settle the undead stirring from the land.\n\nDestroy the cairns and we'll be able to bring sanity to this place.", objectives = "" }
WordHunterWoW_QuestEN[48183] = { title = "The Hills Are Alive", description = "The Drust constructs are drawn from the land, but the heart of these constructs is a runic power core. \n\nWe have been trying to collect and destroy as many of these cores as we can. We know of a way to disrupt the magic in the core. Doing so will prevent more of these monstrosities from being created around the dark hearts and protect the land and all living in this region.\n\nBring me as many Runic Power Cores as you can find and the Thornspeakers will see they are put to good use.", objectives = "" }
WordHunterWoW_QuestEN[48184] = { title = "Pieces of History", description = "There is an opportunity here.\n\nLearning more about the Drust can not only help us understand the texts that Lady Lucille found, we might be able to discover greater details about how they and their constructs were finally defeated. Filling in the gaps of history could be key to victory now.\n\nThis was one of their settlements before it became the place of their final defeat. Let's look for clues in the ruins.", objectives = "" }
WordHunterWoW_QuestEN[48185] = { title = "Shadow of the Sepulcher", description = "Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this \"Darkness\" once manifested.\n\nMeet me there, {name}. I will show you how to walk in the memories of a great Skyhorn hero.", objectives = "" }
WordHunterWoW_QuestEN[48190] = { title = "Huln's Mountain", description = "We have made progress reactivating the wards, but more must be done.\n\nI sense Ebonhorn's struggle. Though he fights with all his strength, he is slipping away. Should this \"Darkness\" emerge into our realm, I fear our friend will be lost.\n\nEbonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.", objectives = "" }
WordHunterWoW_QuestEN[48195] = { title = "Troublesome Troglodytes", description = "Troggs are base creatures. They barely have any brain process, living mostly on survival instinct alone. They are pests through and through, and need to be dealt with.\n\nThe fewer of them there are, the better.", objectives = "" }
WordHunterWoW_QuestEN[48196] = { title = "Following Eddie's Trail", description = "My life is equestrian. I'm not a fighter. I could maybe take a trogg or two, but not a whole tribe.\n\nPlease, go into Mistfall Cleft and see if you can find Eddie. Lord Norwington would be furious if something happened to him, and nobody wants to bear witness to that!", objectives = "" }
WordHunterWoW_QuestEN[48198] = { title = "The Burden of Proof", description = "I think we have everything we need to conduct three of the villagers' tests. Let us hope this is enough to convince them.\n\nI'm sure Constable Framer is champing at the bit to proceed with his trial, and I would prefer it if you were the one to administer the tests. I may not know you well, but I trust you farther than the constable.\n\nSpeak with him when you're ready to begin.\n\n...and do me a favor. Make this quick.", objectives = "" }
WordHunterWoW_QuestEN[48199] = { title = "The Burning Heart", description = "The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us.\n\nI wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru.\n\nThis must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack.\n\nWe need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!", objectives = "" }
WordHunterWoW_QuestEN[48200] = { title = "Securing a Foothold", description = "Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements.\n\nOur first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts.\n\nSpeak to Romuul when you are ready to head down to the surface.", objectives = "" }
WordHunterWoW_QuestEN[48201] = { title = "Reinforce Light's Purchase", description = "Now that we have established a foothold, we need to rendezvous with our soldiers in the field.\n\nWe have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis.\n\nAlleria went to scout the area. Find her, and see what information she has gathered.", objectives = "" }
WordHunterWoW_QuestEN[48202] = { title = "Reinforce the Veiled Den", description = "The foothold you established allows us to check in with our field operatives.\n\nOn our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment.\n\nIllidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.", objectives = "" }
WordHunterWoW_QuestEN[48203] = { title = "The Burning Throne", description = "The time has come, {name}, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.\n\nWe will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.\n\nAfter all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.", objectives = "" }
WordHunterWoW_QuestEN[48230] = { title = "Fragment of the Past", description = "<Your eye is drawn to the faint glow of the crystalline fragment. Examining the piece, you trace the partial pattern of a rune that had been inscribed upon its surface.\n\nThe fragment appears similar to the argunite crystals used by the Army of the Light to power their armaments. Could this crystal have belonged to the eredar who fought to escape Argus so long ago?\n\nPerhaps Captain Fareeya would be able to tell you more about the crystal.>", objectives = "" }
WordHunterWoW_QuestEN[48231] = { title = "The Seat of the Triumvirate: Armor of the Triumvirate", description = "This reforged key will grant entry into the armory inside the Seat of the Triumvirate.\n\nLocked away inside is the Armor of the Triumvirate, crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void's forces.\n\nOnce the armor is in your possession, please bring it to Archivist Ionaa. He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.", objectives = "" }
WordHunterWoW_QuestEN[48261] = { title = "The Power to Reforge", description = "I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light's defenses.\n\nHmm... dendrite clusters might be an alternative. They were used by the elite of Eredath to power simple devices. If enough of the city ruins are still intact, I'd wager the fallen magi or the broken may still have some in their possession. \n\nOf course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.", objectives = "" }
WordHunterWoW_QuestEN[48271] = { title = "Recovering the Pieces", description = "The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. \n\nWe must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession.\n\nGet those key fragments, {name}... any way you have to.", objectives = "" }
WordHunterWoW_QuestEN[48272] = { title = "Visions of Fear", description = "I've done it, lad. I've reached him again! \n\nOh, but it's so painful. So painful! He's not doin' well, not one bit!\n\nYou'll have to listen on in with me to understand.", objectives = "" }
WordHunterWoW_QuestEN[48273] = { title = "The Speaker Listens", description = "Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus.\n\nI suggest you find him immediately. His last vision foretold Aggramar's coming, and there is still so much we do not know of Sargeras' plans.", objectives = "" }
WordHunterWoW_QuestEN[48277] = { title = "The Speaker Seeks", description = "Our forces are ready for battle, but we still do not know where Eonar's spirit lies.\n\nYou should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.", objectives = "" }
WordHunterWoW_QuestEN[48280] = { title = "Visions of Another", description = "Whoever's tryin' to reach us now might give us the information we need to find Eonar.\n\nWe need to see what's goin' on right away!", objectives = "" }
WordHunterWoW_QuestEN[48283] = { title = "Standing Accused", description = "So you wish to speak with the accused?  I see no reason why not.\n\nBe quick about it, though. I will not have our trial delayed. This woman will answer for the fate of our village!", objectives = "" }
WordHunterWoW_QuestEN[48313] = { title = "Nature's Remedy", description = "Your friend doesn't have much time left. The scorpid venom is likely rotting his veins right now. \n\nHe will certainly meet death without a cure.\n\nI will help. \n\nThe first ingredient I'll need is the root of the prickly plum cactus. Its natural healing properties will make a suitable base for the salve.", objectives = "" }
WordHunterWoW_QuestEN[48314] = { title = "Creeping Death", description = "Scorposhi venom usually induces a slow, creeping death.\n\nIt's remarkable that your friend has survived this long.\n\nAs with most antivenoms, the thing that kills is also the thing that heals. \n\nI'll need to extract the venom from several scorpashi stingers to craft the cure.\n\nWhen the extracted poison is mixed with cactus root salve, we will have the antivenom we need to treat his wounds.", objectives = "" }
WordHunterWoW_QuestEN[48315] = { title = "Hollow, Empty Eyes", description = "<Carved into the ancient statue are two eye sockets that look like they once held gems. \n\nPerhaps the missing gems can be found within the ruins?>", objectives = "" }
WordHunterWoW_QuestEN[48317] = { title = "A Nose for Magic", description = "I have it! The readings from the ruins are unmistakable. Somewhere to the south and west of the ah... \"foot\", as it were, is a source of great magical energy.\n\nIt can be nothing but the Eye of Xibala!\n\nWe will need to place a few more scrying vessels to pinpoint the Eye's exact location.\n\nMeet me deeper in the ruins. I will personally oversee this effort.", objectives = "" }
WordHunterWoW_QuestEN[48320] = { title = "The Best Kill is Overkill", description = "I watched you kill those Sandfury earlier, {name}. You have blood instinct. I like dat.\n\nI bet de others have you hunting frivolous luxuries for de inn. I'll give you an assignment worth your talents.\n\nDis oasis is full of dangerous beasts dat'll scare away guests and harrass my pterrordaxes flying in and out.\n\nKill dem.\n\nOnce de skies are clear, my pterrordaxes can fly you wherever you want.", objectives = "" }
WordHunterWoW_QuestEN[48321] = { title = "Creative Marketing", description = "De Goldtusk Gang is de best gang in all of Zandalar.\n\nI know dat. You know dat. Everyone in de gang knows dat.\n\nBut we need to make sure dat everyone who sees our inn knows dat too.\n\nWe need something big... Something like a massive gold tusk!\n\nI don't know where we'd find one of those, but I got a plan.\n\nDere's a huge saurolisk in de oasis. Bring me one of its giant bones and I'll take care of de rest.", objectives = "" }
WordHunterWoW_QuestEN[48322] = { title = "A Goldtusk Greeting", description = "Thanks to you, de Goldtusk Inn has never looked better!\n\nWe got food, we got beds, we got piles of dead Sandfury nearby. Dis is everything I ever dreamed it be!\n\n<Rhan'ka looks out into the oasis.>\n\nYou hear dat? Sound like we got our first guest of de day!\n\nWhy don't you greet dis one? Show 'em all de great amenities ya built here!", objectives = "" }
WordHunterWoW_QuestEN[48324] = { title = "Lost in Zem'lan", description = "Legends say that a mountain of treasure sits deep inside the Port of Zem'lan, pillaged from every corner of Azeroth. But it's guarded by unkillable, eternal monsters.\n\nNo vulpera or exile has ever stolen treasure from the Port of Zem'lan and made it out alive.\n\nMy caravan was going to be the first. Our scout, Meeki snuck in to figure out a route, but he never came back.\n\nIt would be wisest for you to leave here and never return. But, if you go into the port, please find Meeki.", objectives = "" }
WordHunterWoW_QuestEN[48326] = { title = "This Be Mutiny", description = "It be time to face Pirate-King Zem'lan and bring dis mutiny to bear, {name}.\n\nZem'lan keeps a gong at de top of his treasure isle dat any crew member can ring to challenge him to a fight. I only ever seen one lass brave enough to ring it, and it didn't end well for her.\n\nBut you and me, we be de scourge of de seven seas, aye? Even mighty Zem'lan be no match for de two of us together.\n\nRing de gong, and let's make Zem'lan pay for cursin' his crew and treatin' us like dogs.\n\nMutiny or de yard arm!", objectives = "" }
WordHunterWoW_QuestEN[48327] = { title = "A Strange Delivery", description = "The last time our caravan rolled through the Whistlebloom Oasis, we found an odd Zandalari living in a cave. We traded a few things and he paid me upfront to bring him a pineapple. I don't know why.\n\nIt took me a long time to find one, but a vulpera holds up her end of the trade.\n\nI was planning to stop by and drop it off after we finished here. But, thanks to your help, we've got a lot more treasure hunting to do here at the port.\n\nIf you have time, would you deliver it for me?", objectives = "" }
WordHunterWoW_QuestEN[48329] = { title = "Beaten But Not Broken", description = "<Beastbreaker Hakid's crystal-encrusted key looks like it will open the large cage nearby.\n\nThe pterrordax inside that cage, Scion of Rakjan, is stronger than the other hatchlings you've seen in the Crackling Ridge. He holds his head high and doesn't seem bothered by the myriad scars and fresh wounds that cover his body.\n\nIf you release him, he'll likely want to return to Rakjan the Unbroken at the top peak of Crackling Ridge.>", objectives = "" }
WordHunterWoW_QuestEN[48330] = { title = "Zandalari Treasure Trove", description = "We've looted some quality goods already, but the real reward is still ahead. The big chamber in the back of the ruins is filled with powerful artifacts.\n\nA treasure trove like that is the sort of thing that can save lives and sell for a fortune out here in Vol'dun.\n\nBut those specters you killed weren't lying. Their master or king or whatever is very well-protected in there.\n\nWe'll have to take this one down as a group. Let me know when you're ready to head up to the chamber.", objectives = "" }
WordHunterWoW_QuestEN[48331] = { title = "Siphoning Souls", description = "<Tacha rummages through her sack of scavenged supplies.>\n\nSo these golems are powered by Zandalari souls?\n\nNo problem... I've had to deal with that before... I've got just the tool for it.\n\n<Tacha pulls out an eerie Zandalari totem.>\n\nHere it is! Found this ol' soulcatcher totem in one of the southern ruins years ago. It's gotten us out of a few jams.\n\nDisable the golems and throw down this totem next to it. It'll siphon off the souls.\n\nKeep the totem. We'll need it later.", objectives = "" }
WordHunterWoW_QuestEN[48332] = { title = "Ranishu Are Resources", description = "We can't afford to waste resources out here.\n\nOver time, we've learned to take anything that looks even remotely useful, and be creative using what we have. I've turned a skull into a boat and a sethrak into a tent flap.\n\nI can't spit dust when it comes to magic, but I can mix poisons and potions with the best of 'em.\n\nRanishu stomach acid makes wicked poison, but it's nasty to collect. Don't try to bottle it. Just bring me their stomachs whole and intact. No leaks!", objectives = "" }
WordHunterWoW_QuestEN[48334] = { title = "They've Got Golems", description = "I've sacked countless ruins across Vol'dun. Everything from saurolisk-infested dens to the cursed Port of Zem'lan.\n\nI don't say this to brag. I want you to understand that I know what I'm doing.\n\nI've survived this long because I take my time, avoid risks, and only take what I need.\n\nThat's what we'll be doing here today.\n\nOmi reported heavy golem activity on her first scouting trip into the ruins. Zandalari golems are formidable. We need to learn what's powering them before we head in.", objectives = "" }
WordHunterWoW_QuestEN[48335] = { title = "The Strongest Rope in Vol'dun", description = "You ever tried tying up a sethrak with vulture string? Won't hold 'em for long.\n\nWhen you really gotta keep something, or someone, tied down, you need sandspinner silk.\n\nThick, pliable, and not as sticky as you'd think.\n\nThis isn't a tailoring lesson. Omi's scouting report showed a lot of sandspinners inside the ruin courtyard. Get their silk and bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[48344] = { title = "We Have a Problem", description = "We have a problem, {name}. The Legion has come to Eredath.\n\nWhen you claimed the Sigil it was as if we announced our presence to all of Argus. The eyes of Antorus are firmly upon us.\n\nJust wait. It gets worse.\n\nVelen took Captain Fareeya and her forces into the Arinor Gardens area to search for the Crest of Knowledge. To my knowledge, they are all now behind enemy lines.\n\nCome with me to the Conservatory. We need to bring Velen and the others back before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[48345] = { title = "Talgath's Forces", description = "I must continue to seek the Crest of Knowledge, my friend. Nothing short of the whole Crown of the Triumvirate can turn the tide in the battle we face.\n\nTalgath's forces stand between us and that goal. I will need you to clear a path.\n\nWe can let nothing stand in our way. Not even Talgath.", objectives = "" }
WordHunterWoW_QuestEN[48347] = { title = "Anglepoint Wharf", description = "HELP WANTED.\n\nAn unidentified illness has cropped up in Anglepoint Wharf. Those experienced with medicine or healing should report to the Therold Wavestone at their earliest convenience.\n\nCitizens are advised against visiting Anglepoint on personal business until further notice.\n\nThank you for your cooperation.", objectives = "" }
WordHunterWoW_QuestEN[48348] = { title = "Stinging Barbs", description = "The Outrigger hunters exhibit the pinnacle of Kul Tiran brawn. But they would indubitably be unable to succeed in taking down the most impressive of their prey without my own inventions!\n\nI present to you, the most ordinary of harpoons. However, with just a tad of gnomish ingenuity, this average weapon can become so much more! \n\nAll that I need are barbs from the rays in the harbor. Using them, I can fashion a poison that can stun even the most colossal of sea monsters!", objectives = "" }
WordHunterWoW_QuestEN[48352] = { title = "A Cure from the Sea", description = "You may not believe it, but seaweed is one of the most important gifts the sea grants to us. Without it, my tonic shall be useless.\n\nI know it is much to ask, but can you go into the harbor and collect some for me? The water is tumultuous in this trying time, but I will give you my blessing.", objectives = "" }
WordHunterWoW_QuestEN[48353] = { title = "Pulse of the Wharf", description = "I am at a loss for ideas, {name}. The tides churn, and I can feel their pain as if it is my own.\n\nWhile I am out of ideas, perhaps the merchants in town may have seen something? They are always watching and gossiping, making them quite good sources of information.", objectives = "" }
WordHunterWoW_QuestEN[48354] = { title = "Tainted Shipments", description = "If one shipment was compromised, who knows how many of the others are.\n\nNearby, the fishpackers prepare shipments to be sent to the rest of Kul Tiras. We must check the rest of the shipments before this plague can spread!", objectives = "" }
WordHunterWoW_QuestEN[48355] = { title = "Evacuate the Premises", description = "The people of Anglepoint need me to stand tall, to not panic in the face of the unknown.\n\nI will admit to not being the best at this.\n\nEven now, the fishpackers are handling the tainted product and preparing it for shipment. They are in great danger, and we cannot allow them to stay in harm's way.\n\nWe must get them to safety!", objectives = "" }
WordHunterWoW_QuestEN[48356] = { title = "Possessive Headgear", description = "It is fortunate that we have found Alby. He has filled me in on the situation in the packing district.\n\nIt's not good, {name}.\n\nThe workers walk, yes. They work as if nothing is out of the ordinary, yet they are controlled by parasites. Mindstealers that force them to do their bidding.\n\nIt is they who contaminate the shipments.\n\nYou must destroy as many of those mindstealers as you can. Free the minds of the possessed!", objectives = "" }
WordHunterWoW_QuestEN[48365] = { title = "The Young Lord Stormsong", description = "When the town fell, I got separated from my charge.\n\nLord Stormsong is being held hostage in his own house. I should've been there to protect him.\n\nWhen you go in there, succeed where I failed. Bring him back safely.", objectives = "" }
WordHunterWoW_QuestEN[48366] = { title = "Paddle to Safety", description = "Perhaps... perhaps I can still help my people.\n\nI overheard conversations between the foreman and his men. It sounds as if the source of this corruption comes from the deeper waters, where the Stormriggers do their monster hunting.\n\nPlease, assist me in investigating this. I can still redeem myself and this operation.", objectives = "" }
WordHunterWoW_QuestEN[48367] = { title = "Those Aren't Fish Eggs", description = "Corruption has seeped into the sea.\n\nPart of our job is to keep the monsters of these parts under control. A cruel magic has taken over many of the beasts. I take the challenge of the hunt with pride, but too many and we are overrun!\n\nMonster eggs are scattered across the breeding grounds, pulsing with a dark energy.\n\nGet your stompin' boots on.", objectives = "" }
WordHunterWoW_QuestEN[48368] = { title = "Deep Sea Defilement", description = "The sea...\n\nI understand its screams now. It is as if a veil has been lifted, revealing the chaos that has taken hold.\n\nCorrupting such a vast swath of sea cannot be done with simple spells. The cultists must have erected some sort of structures to channel their dark magics through...\n\nYou must find and destroy them, {name}. Only then can we hope to restore the waters to balance.", objectives = "" }
WordHunterWoW_QuestEN[48369] = { title = "Emergent Strategy", description = "My son went where? Chasing our workers into the woods once again?\n\nThat boy is too soft-hearted. No matter what I do, he will never be strong enough to take over the family business.\n\nI demand he come back this instant. He's got better ways to spend his time than going on wild goose chases for our employees!", objectives = "" }
WordHunterWoW_QuestEN[48370] = { title = "Death in the Depths", description = "My own people have fallen to the mad whispers of the voices of the deep, deep sea.\n\nCultists inhabit caves in the ocean, spreading hysteria deeper and deeper into Tiragarde with their mad rituals.\n\nWe must put an end to them, {name}, before they get even more out of hand.", objectives = "" }
WordHunterWoW_QuestEN[48372] = { title = "Eldritch Invocations", description = "This is my fault, my friend.\n\nThe leader of these cultists is none other than Director Deepwarden, a man who I once trusted as an advisor and business partner.\n\nIt seems he did not approve of how I ran our operation... to a ludicrous degree.\n\nHe gave his humanity for power, using his frustration to overthrow the village from the inside. Who knows what he plans next.\n\nI can no longer stand idly by. Take out Deepwarden. Show him that Anglepoint will not fall to his madness.", objectives = "" }
WordHunterWoW_QuestEN[48394] = { title = "The Necrodark", description = "Things are worse than I expected.\n\nWe might be in trouble, {name}. With this place all but taken over by the Necrodark, they might have already unleashed the Grey One.", objectives = "" }
WordHunterWoW_QuestEN[48395] = { title = "Whispers from the Shadows", description = "Hero, we have a problem.\n\nThe ancient Necrodark cult has returned.\n\nWhen Dargrul was the Underking he would quell these cultists whenever they appeared, keeping them from exploring the vault of Neltharion.\n\nBut now, with Dargrul gone, they are sieging the vault in force.\n\nWe must stop them before they find what they are looking for.", objectives = "" }
WordHunterWoW_QuestEN[48399] = { title = "A Dark (Iron) Tide", description = "Their red eyes... flaming beards... dark, dusky skin. These can only be Dark Iron dwarves. I have never seen one before this day.\n\nIt is my understanding that they have been sent here on an errand for the Alliance. Given my people's allegiance, I believe we are now placed in a position to better demonstrate our loyalty to the Horde.\n\nThe Dark Iron must die. See that they do not claim so much as an inch more of this beach.", objectives = "" }
WordHunterWoW_QuestEN[48400] = { title = "Grand Theft Telemancy", description = "They must not keep the Eye, {name}.\n\nFortunately I am more than an archaeologist. I am a telemancer. Chief Telemancer Oculeth himself trained the woman who trained my master. I can retrieve the relic with these arts.\n\nAll you need to do is place a telemancy beacon near the Eye. I can then retrieve both it AND you safely back to camp. The Alliance will find themselves empty-handed.\n\nWhile you're at it, do deliver my \"thanks\" to the individual responsible for snatching the Eye out from under us.", objectives = "" }
WordHunterWoW_QuestEN[48402] = { title = "A Poisonous Touch", description = "You... I saw you speak with Zentimo. Please, I don't have much time left...\n\nThese trolls, they came for our blood. I was already nearly bled dry before this one succumbed to my poison.\n\nSearch it's body, the blowgun and darts should still be there. Dip the darts into my blood and use them to weaken as many of their number as you can. \n\nI will not let my death be in vain! If these trolls want our blood so badly, then they shall have it!", objectives = "" }
WordHunterWoW_QuestEN[48403] = { title = "The Darkness", description = "For thousands of years, the Darkness was held at bay. The wards stood... protecting Highmountain.\n\nNow they are gone, and evil is free once more.\n\nThe Darkness that haunted our dreams... that even the kobolds spoke of only in frightened whispers... has come.\n\nUul'gyneth, herald of the Old Gods, paves the way for his masters. Unless we stand together and defeat him, all is lost.\n\nYou must hold nothing back, champion. None of us can.", objectives = "" }
WordHunterWoW_QuestEN[48404] = { title = "The Scamps", description = "You there! You have legs and a need for money? I wish to hire you.\n\nConfounded, despicable, parentless children have been stealing my scrolls again. Those scrolls are dangerous in the wrong hands.\n\nWhat is worse, I believe these junior vagabonds to be organized.\n\nFind these street scamps and relieve them of their bounty, and I shall pay you for it.", objectives = "" }
WordHunterWoW_QuestEN[48405] = { title = "Mista Nice", description = "I am normally not a violent tortollan, but if there is one thing I cannot abide, it is a scoundrel using children for his own profit.\n\nThe street scamps appear to be working at the behest of a ring leader. I do believe they call him \"Mista Nice\" though I suspect the name to be sarcastic in nature.\n\nI have a scroll here that can let you move among the scamps and see if they lead you back to Mista Nice. If they do, slay him and I shall pay you a bounty.", objectives = "" }
WordHunterWoW_QuestEN[48419] = { title = "Lured and Allured", description = "Lookin' for a friend from the wreck, eh?\n\nIf he survived he may have wandered up the path to our camp.\n\nNow if he ain't up there toastin' his buns by the fire, well... lotta poor souls fall victim to the song of the sirens. \n\nYou should check the camp before you go wadin' out into the tideway. Ask our leader, Stabby Jane. She'd know for sure if a new survivor showed up!", objectives = "" }
WordHunterWoW_QuestEN[48421] = { title = "Blood in the Tides", description = "Curse these slimy wenches!\n\nTheir singin' sets men's hearts afire and their brains adrift. \n\nMy ship's aground. My cargo's lost.\n\nNothin' for it now but to fight!", objectives = "" }
WordHunterWoW_QuestEN[48433] = { title = "Together We Are the Horde!", description = "What began with a simple feast led to a battle against an ancient evil seeking to consume the world.\n\nMy kind of day!\n\nYour deeds have helped secure an alliance between Orgrimmar and Highmountain. These tauren will make a valuable addition to the Horde.\n\nThe Warchief will be pleased.", objectives = "" }
WordHunterWoW_QuestEN[48434] = { title = "How Fares Ebonhorn?", description = "Three of the ancient wards are restored. The mountain is not yet secure, but we may have done enough to break Ebonhorn free of the shadows gripping him.\n\nLet us return to Thunder Totem and see how he fares. Hopefully Ebonhorn can tell us more about what is happening with the Necrodark and the insidious master they serve.", objectives = "" }
WordHunterWoW_QuestEN[48435] = { title = "The Spiritwalkers", description = "Ebonhorn is in the care of Spiritwalker Graysky. A cure is proving elusive... he has asked for your help.\n\nPlease speak with him at once, {name}. The spiritwalkers are the keepers of our past. I pray the answer lies somewhere in the ancient truths they hold.", objectives = "" }
WordHunterWoW_QuestEN[48440] = { title = "Into the Night", description = "What we do this day, we do for Azeroth. For the countless souls lost to the Legion's foul crusade.\n\nOnce you are ready we will take the Vindicaar into the very heart of the Legion.\n\nArgus awaits.", objectives = "" }
WordHunterWoW_QuestEN[48441] = { title = "Remnants of Darkfall Ridge", description = "My riders have talbuk, but my people need supplies. Food. Tools. Weapons.\n\nFor millennia, we have migrated from one hovel to the next, moving each time the Legion discovered us. Never able to flee with our possessions, we left them behind.\n\nYou are powerful, your followers are capable, but you do not know Argus. The landscape will dispatch you as mercilessly as the Legion. Recover our supplies from Darkfall Ridge, and I will order my people to guide your forces through the Argus Wastes.", objectives = "" }
WordHunterWoW_QuestEN[48442] = { title = "Nath'raxas Hold: Preparations", description = "One of two fates await krokul prisoners taken to Nath'raxas Hold. Consume the fel, and become a willing soldier in the infinite army, or be mutated into a disfigured abomination. An ur'zul.\n\nWhile the Army of the Light occupies the Legion's attention, I am presented with an opportunity to save my people. I ask for your aid.\n\nBefore we begin, your forces must be adequately equipped.", objectives = "" }
WordHunterWoW_QuestEN[48443] = { title = "Nath'raxas Hold: Rescue Mission", description = "Your forces are adequately equipped for the mission to save my people from Nath'raxas. Order your champions to bolster my assault, and together we will dismantle the Legion's stranglehold over the region.", objectives = "" }
WordHunterWoW_QuestEN[48445] = { title = "The Ruins of Oronaar", description = "Many krokul wander the city below, shrouded in shadow. I will not accept that they are all beyond redemption.\n\nArkhaan was a leader, once. Some among his followers may still reside in the ruins of Oronaar, straddling the thin divide between reason and oblivion. Enlist the aid of your order. Scour the ruins for any that can be saved.", objectives = "" }
WordHunterWoW_QuestEN[48446] = { title = "Relics of the Ancient Eredar", description = "I failed Arkhaan. I won't fail again. \n\nIf there is to be any hope of freeing the krokul, the ethereal threat must be removed from Eredath. L'ura has been vanquished, but the void clings heavily near the Shadowguard Incursion.\n\nBefore we commence, ensure your forces are protected from the shadow. Your champions should seek ancient eredar armaments in the nearby ruins.", objectives = "" }
WordHunterWoW_QuestEN[48447] = { title = "Shadowguard Dispersion", description = "Lend me the aid of your order once again, that we might end the Shadowguard threat permanently. While you confront the Legion, we will face the void. The attack commences once your forces arrive.", objectives = "" }
WordHunterWoW_QuestEN[48448] = { title = "Hindering the Legion War Machine", description = "{class}t, I could use your help. The Army of the Light is coordinating an attack against the Spirit Crucible, Terminus, and Shaper's Rise to cripple the Legion's ability to wage war outside of the Antoran Wastes. We do not have enough soldiers to defend our footholds and execute this operation.\n\nWill you approach the {class}s on our behalf? This gambit could succeed with them fighting by our side. We can paralyze the Legion war machine.", objectives = "" }
WordHunterWoW_QuestEN[48452] = { title = "The Red Market", description = "You came with de Princess Talanji?\n\nI need a hand with a most unsavory task. Crimson cultists have made demselves a market for blood magic. Dis is bad, mon. Dis is very bad indeed.\n\nI need you to go down dese steps and bring back any evidence you can of blood practices. And destroy their chalice. Big chalice. Don't forget de chalice.", objectives = "" }
WordHunterWoW_QuestEN[48453] = { title = "Strike Back", description = "As you may have seen, the ritualists in this forest kidnap our people and perform heinous rituals on them. The souls of our fallen now roam as twisted creatures. This sin cannot go unpunished. Kill as many ritualists as you are able, but be sure to strike at the dark demon that leads them.", objectives = "" }
WordHunterWoW_QuestEN[48454] = { title = "Evidence of Evil", description = "Jakra'zet refused to patrol dis area. Yazma's spies did not warn us of de evil lurking beneath our city. And Zul did not foresee blood magics festering under our noses.\n\nThese are serious allegations, and de evidence is in your hands. Present dem to Zolani, Blade of the King. She will know best their meaning and how best to present dem to de king.", objectives = "" }
WordHunterWoW_QuestEN[48455] = { title = "Duskcloak Problem", description = "Here in this forest, species of talbuk and panthara still roam. However, the balance has been disrupted and now the panthara risk hunting the talbuk to extinction. To ensure their survival, we must decrease the number of panthara.\n\nDo not let their suffering linger. A swift death is the most merciful.", objectives = "" }
WordHunterWoW_QuestEN[48456] = { title = "Witch Doctor Jala", description = "{name}, I received word dat an old friend of mine is down here and in need of some extra muscle.\n\nWitch Doctor Jala. She is an old crone, but de loa find her amusing enough to keep around.\n\nSeek her out for me and lend what aid you can.", objectives = "" }
WordHunterWoW_QuestEN[48460] = { title = "The Wranglers", description = "Great evil exists on Argus and our forests house some of the worst of it. My wranglers are at the edge of the forest and are waiting for reinforcements. That would be you.\n\nSeek out Lead Rider Jerek, he will tell you more.", objectives = "" }
WordHunterWoW_QuestEN[48461] = { title = "Where They Least Expect It", description = "The Legion's fanatical crusade leaves them spread thin. As they focus their defenses on Argus, we are free to tear into their forces on other worlds.\n\nTravel through an Invasion Point on Argus and show the Legion that there is no hiding from death.", objectives = "" }
WordHunterWoW_QuestEN[48468] = { title = "Bwonsamdi's Deliverance", description = "We be havin' a task from Bwonsamdi, da loa a death, ta purge dis place of its undead.\n\nDey be controlled by a monster called Kel'vax.\n\nCan ya help? Dere be zombies destroyin' Bwonsamdi's temple over dere, and we no have da strength ta fight 'em all.\n\nTake dis torch. Kill dem zombies, den burn them corpses with da torch. It should be deliverin' their souls ta Bwonsamdi.\n\nYa do dat, and we be one step closer ta stoppin Kel'vax.", objectives = "" }
WordHunterWoW_QuestEN[48473] = { title = "Respecting the Rites", description = "If we be deliverin' Kel'vax's soul ta Bwonsamdi, we need ta be doin' it properly. We need ta be doin' two things.\n\nFirst, dere be torches remainin' around da temple nearby. Light dem with da torch I gave ya.\n\nDa torches used ta be our way ta show dat we be deliverin' a spirit ta Bwonsamdi. Kel'vax will be knowin' it be his time.\n\nSecond, I be needin' special ritual powder dat be deep within da temple. It be da key ta stoppin' Kel'vax.\n\nGo now, I be prayin' Bwonsamdi be favorin' us.", objectives = "" }
WordHunterWoW_QuestEN[48475] = { title = "Seeing Spirits", description = "The spirits in the cemetery are riled up! I'd ask 'em direct but I don't have any of the necessary salve I use to commune with the dead. My family's been making it for ages!\n\nThe herbs and tools I use to make it are inside, but I can't get over there! Some of those spirits are beyond reason and attack me on sight!\n\nWhy don't you go collect those herbs, make the salve with my tools, and ask one of the calmer spirits what's going on. Aaron Cresterly is a good spirit to look for.", objectives = "" }
WordHunterWoW_QuestEN[48476] = { title = "Split Party", description = "In life my compatriots and I were valiant champions as you are. In death we are potent souls to make the witch's accursed minions even more powerful. \n\nWith your help I have resisted thus far, but this foul witch pulled brave Bridget from her justly won rest. She is now trapped in one of these macabre constructs. This witch intends to use Bridget to bring death upon the lands she was oathsworn to protect!\n\nFree Bridget Fairwater's soul from the construct which entraps her!", objectives = "" }
WordHunterWoW_QuestEN[48477] = { title = "Looking For One More", description = "Our loathsome foe, 'Sister' Westwood, yet continues her work. After subjugating myself, she set her malicious sights on my companion, fair Mercy. \n\nOf us three, Mercy was most kind and possessing of uncommon inner strength, yet I fear for her. Corrupting such a soul would make for a fearsome creature, indeed.\n\nStop the vile ritual before Mercy is taken. Allow the dead their rest. Slay Sister Westwood and free us from her grasp!", objectives = "" }
WordHunterWoW_QuestEN[48478] = { title = "Kel'vax's Home", description = "Kel'vax's soul be bound ta three phylacteries, protected by his voodoo. Even if ya destroy him, he just be reformin' in dem.\n\nMe old power be returnin' after ya lit dem torches. I be able ta enchant dis powder dat allow ya ta go through Kel'vax's voodoo.\n\nFind dese phylacteries and bring 'em ta me. We gonna look Kel'vax in da eye when we destroy 'em.\n\nI should warn ya... dis powder might be messin' with ya head. Ya may have some... visions after ya use it. Be careful.", objectives = "" }
WordHunterWoW_QuestEN[48479] = { title = "Bones for Protection", description = "Kel'vax be havin' powerful voodoo on his side, da kind dat could kill ya instantly if ya not careful.\n\nI know how we can be stoppin' dis magic, but we need bones. Lots a them. We be lucky, Kel'vax be havin' a large skeleton army.\n\nI need ya ta be goin' out dere and collectin' their bones. Bring 'em ta me and I'll prepare 'em ta be used against his voodoo.", objectives = "" }
WordHunterWoW_QuestEN[48480] = { title = "The Fall of Kel'vax", description = "We be ready ta kill Kel'vax and send his soul ta Bwonsamdi for judgment. Ya should know someting before ya go in.\n\nKel'vax was our son. Dat be why Bwonsamdi chose us ta stop dis madness.\n\nI not be knowin' why Kel'vax chose ta forsake everyting we believed in centuries ago... but here we are.\n\nEven without his undead, Kel'vax be very powerful. Be prepared... dis be our shot to end him and find our rest.", objectives = "" }
WordHunterWoW_QuestEN[48483] = { title = "A Stranger's Plea", description = "My people... enslaved...\n\nBeaten... within death's grasp...\n\n<The cowled figure weakly raises his arm, handing you a small liquid skin.>\n\nHelp... us...", objectives = "" }
WordHunterWoW_QuestEN[48489] = { title = "The Spires of Home", description = "My sister Vereesa told me of the events that led to the high... excuse me, \"blood\" elves joining the Horde.\n\nPart of me still can't accept it.\n\nPrince Kael'thas led my people down a dark path. I have to believe the majority of sin'dorei would shrug off the Horde if given the choice.\n\nThe last time I spoke to Lor'themar, we served together in the Farstriders. He was a fine ranger and a good man. I pray the years have not changed that.\n\nCome. We must not keep the regent waiting.", objectives = "" }
WordHunterWoW_QuestEN[48492] = { title = "Getting a Leg Up", description = "I seem to be in a bit of a... predicament.\n\nMy squad was scouting on behalf of Lady Sylvanas when we were ambushed by some snake men calling themselves \"sethrak\".\n\nAs you can see, my legs have been separated from my body in the ambush. It's just a flesh wound, luckily.\n\nCare to help me get re-attached? Then we can get down to this business of vengeance against these sethrak.", objectives = "" }
WordHunterWoW_QuestEN[48496] = { title = "Reuniting the Company", description = "Right, then. First order of business, rescue the remnants of my company. \n\nThese sethrak kept yelling about expanding their empire and conquering Azeroth as they attacked us. Lovely, really.\n\nThey killed most of my company and took some hostages. I assume they're being told how grand the sethrak empire is.\n\nI'd like the remnants of my company back, if you please. I'll put in a good word with Lady Sylvanas, once this is all over. \n\n...not that someone like you needs it.", objectives = "" }
WordHunterWoW_QuestEN[48497] = { title = "Show of Force", description = "These things called the sethrak think that we're easily handled. That's only because we were ambushed and not ready for a fight.\n\nWell, all right, perhaps we were easily handled. But that doesn't mean we won't strike back.\n\nKill as many of those sethrak as you can. I don't know who they are or what they want, but I do know one thing.\n\nThey signed their death warrants when they attacked my squad and cut me in half.", objectives = "" }
WordHunterWoW_QuestEN[48498] = { title = "No Mercy for Sithis", description = "Heh heh... thanks for the rescue! I could use your help in a little plan that I have.\n\nThe commander of this place is a sethrak called Sithis. He's got this thing called a \"skycaller gem.\"\n\nWord is they're looking for some sort of shadow magic in Nazmir to try and really power this thing up.\n\nHeh heh... luckily, yours truly has her own shadow magic to do just that! Maybe you do, too. I don't keep up on what powers you keep getting.\n\nGet the gem from Sithis and we'll have some REAL fun afterwards.", objectives = "" }
WordHunterWoW_QuestEN[48499] = { title = "Return to Dust", description = "It appears the sethrak are quite serious about keeping this gem. I do wonder where they found it in the first place.\n\nHrm... perhaps Lady Sylvanas would be interested in this as well. Something to ponder.\n\nIngrid believes this gem can unleash lightning and shadow magic of, her words not mine, epic proportions.\n\nI do believe it would be best for everyone if you tested it out on the small sethrak army currently looking for us.", objectives = "" }
WordHunterWoW_QuestEN[48500] = { title = "A Moment of Respite", description = "For all we have seen, we must remember not to dwell on the past, but to look forward and prepare for what is to come.\n\nTake this opportunity to familiarize yourself with the Vindicaar.", objectives = "" }
WordHunterWoW_QuestEN[48504] = { title = "Through the Old Roads", description = "Lady Waycrest has entrusted me with securing the town of Falconhurst and the services of Master Alchemist Ashton who lives there. However, I have found out no one has heard from Falconhurst in some time.\n\nThe skies above the forest are impassable, so we must travel the old roads through Drust ruins in the mountains. A small capable party has a better chance to bypass the growing forces of the witches and to help secure Master Alchemist Ashton.\n\nTo that end, I ask you to assist me.", objectives = "" }
WordHunterWoW_QuestEN[48505] = { title = "Lovesick and Lost", description = "Ugh. My head. My HEART.\n\nFeels like a good hangover and a bad breakup put together.\n\nOn the bright side, I think I know where we are. And where that ship was headed.\n\nFreehold.\n\nIt's a... free town. For, uh... free folk. The only rule is that there are no rules. Lotta guys with peg legs and eye patches and exotic pets. Catch my drift?\n\nThere's a trail through the hills that'll take us there. Pretty sure I remember the way...\n\nLet's get moving. Gotta walk off that damn siren's witchery.", objectives = "" }
WordHunterWoW_QuestEN[48506] = { title = "The Hand of Fate", description = "Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there.\n\nWith the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force.\n\nYou should make your way to Stormwind Harbor right away. Arrangements have been made for a ship there to take you to Azuremyst.", objectives = "" }
WordHunterWoW_QuestEN[48507] = { title = "The Hand of Fate", description = "Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there.\n\nWith the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force.\n\nYou should make your way to Bladefist Bay right away. Arrangements have been made for a ship there to take you to Azuremyst.", objectives = "" }
WordHunterWoW_QuestEN[48513] = { title = "Invasion Point Offensive", description = "The invasion points are key to cutting off Legion reinforcements to Argus. Defeating their armies within the lesser portals will allow us to assault larger invasion points and extinguish the Legion presence within.", objectives = "" }
WordHunterWoW_QuestEN[48515] = { title = "Silver Blades", description = "<This drust warrior was felled by a silvered blade long ago. This blade is still good despite the ages.\n\nPerhaps these weapons could be brought into service of fighting the Drust once more.>", objectives = "" }
WordHunterWoW_QuestEN[48516] = { title = "Toxic Community", description = "A traveler? Nobody uses this trail unless they got a death wish.\n\nThe only thing more poisonous than the marrowflies are the saurolisks that eat 'em all day.\n\nThat marrowfly toxin is what I'm here for. Y'see, I'm a purveyor of, uh... specialty goods. And my clients are just dyin' for more of my product. Heh.\n\nYou bring me their stingers, I pay you. Simple as that. \n\nYou can even find 'em in the saurolisks, if you don't mind gettin' your hands dirty.", objectives = "" }
WordHunterWoW_QuestEN[48517] = { title = "Honorable Discharge", description = "Some of the spirits on the battlefield are too weary to go on. These were brave Kul Tirans. They have more than earned their rest but their sense of duty holds them here.\n\nOrder the most weary spirits off the field of battle. Hopefully they will be convinced to rest.", objectives = "" }
WordHunterWoW_QuestEN[48518] = { title = "Save Who We Can", description = "These things seem intent on capturing our people... but we're not quite sure what for.\n\nThe ones in the town might be too tough to reach right now, but we might be able to save some of the woodsmen who work along the strand.\n\nHead to the lumber fields just east of here, and see if there's anyone still alive out there. We can shelter them here until we can arrange safe passage out of here.", objectives = "" }
WordHunterWoW_QuestEN[48519] = { title = "Hope They Can't Swim", description = "We've got a small boat docked right across the way there. If we can get these villagers safely on board, they should be able to make it to Fallhaven by river.\n\nYou're a capable fighter, no doubt. Can I count on you to fend off any attackers while we get them to safety?", objectives = "" }
WordHunterWoW_QuestEN[48520] = { title = "The Three Sisters", description = "If you're looking to absolve Miss Waycrest of this mess, you'll need to head into the town. Recently, I've seen some oddly dressed women among the creatures, who seem to be calling the shots.\n\nIt's likely that they're the key to this whole nightmare, but we can't get in to question them. Their minions don't seem to slow you down, though. \n\nIf you can get to them, you might be able to find some answers for the both of us.  Be careful, though. They likely aren't very friendly.", objectives = "" }
WordHunterWoW_QuestEN[48521] = { title = "Charming the Lifeless", description = "<You've seen a charm like this in Fallhaven being used to control a wicker construct.\n\nIf you can figure out how to use it, you may be able to take control of one of the coven's wicker constructs.>", objectives = "" }
WordHunterWoW_QuestEN[48522] = { title = "A Revealing Missive", description = "<The strange woman possessed a letter from someone calling herself \"Matron Levae\" which appears to have orders to take the town of Fletcher's Hollow.\n\nThis could be the evidence needed to absolve Lucille Waycrest. Mayor Pare should be interested in seeing this.>", objectives = "" }
WordHunterWoW_QuestEN[48523] = { title = "The Murderous Matron", description = "I know that you've got what you came for, but I need to ask you one more favor.  This town won't be safe until this Matron Levae is taken care of. \n\nAccording to the letter, she must be holed up in that cave. None of our people have been able to enter it, but I know I've seen their constructs go in!\n\nThis charm you found might be the key. If you can take control of one of these wicker men and send it after her, we might have a shot!", objectives = "" }
WordHunterWoW_QuestEN[48524] = { title = "Culling the Coven", description = "If the mine really was their objective, I can only imagine they'd have even more forces in there.  \n\nMy men and I may be able to take care of the remnants out here, but if an even bigger force comes out of that mine, we're not going to stand a chance.\n\nWhile you're hunting down the matron with this wicker contraption, do you think you could... you know... soften them up a bit?", objectives = "" }
WordHunterWoW_QuestEN[48527] = { title = "Ravenous Landsharks", description = "Warbeast Kraal is important to de empire. All de beasts dat haul our goods, carry our armies, and fight our wars are born and bred here. \n\nIf you want Rastakhan's support, you had better impress us. I have some thoughts on where you can start.\n\nWe have ourselves a diemetradon problem. Usually nothing to worry about, but dey had a big hatching dis year. Now dey're breaking into de pens and eating our eggs.\n\nKill diemetradons, protect our beasts, and we will see about de rest.", objectives = "" }
WordHunterWoW_QuestEN[48529] = { title = "Hungry Mouths To Feed", description = "We don't have much in de way of supplies right now.\n\nMojambo and his gang will be back to finish us off, of dat I'm sure. But without food and supplies, dere will be none of us alive for dem to kill.\n\nOur cook is looking for someone to help gather supplies so we can feed de camp.\n\nSpeak with him and see if you can find what he's looking for.", objectives = "" }
WordHunterWoW_QuestEN[48530] = { title = "I Heard You Lost the Herd", description = "Our herd of alpacas went missing dis morning.\n\nIt may seem like we have more pressing matters to worry about, but de meat and milk de alpacas provide are essential to our survival.\n\nThose alpacas won't survive long on de dunes. Speak with Mugjabu and help him find de alpacas before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[48531] = { title = "Mystery Meat", description = "Mojambo's gang may be coming to kill us, but we've still got to eat. And when you live in a harsh wasteland, you make do with what you've got.\n\nSometimes fresh meat is hard to find.\n\nDat's how I came up with de idea for my famous mystery meat pie.\n\nDe secret ingredient is dung beetle, but with enough seasoning you can't even tell!\n\nOur food supplies are dangerously low right now. I need someone to go beetle hunting as soon as possible!", objectives = "" }
WordHunterWoW_QuestEN[48532] = { title = "Alpacas Gone Wild", description = "Our herd of alpacas escaped dis morning. Dey're out dere wandering de dunes as we speak.\n\nProbably for de best, if you ask me. We'll all be dead soon once Mojambo comes back.\n\nSince you seem to care so much, take dis alpaca whistle and use it to round dem up. I blow de whistle every day at feeding time, so de alpacas should come running home when dey hear de sound.", objectives = "" }
WordHunterWoW_QuestEN[48533] = { title = "Vol'duni Fried Chicken", description = "Have you ever tried my delicious Vol'duni fried chicken?\n\nMe neither! Probably because dere aren't any chickens in Vol'dun.\n\nDere are plenty of vultures, though. Why don't you see if you can find some tasty vulture meat?\n\nDe secret to delicious fried chicken is to roast de meat before you fry it, but it only works if de meat is fresh.\n\nI've soaked dese arrows in alpaca fat. If you ignite de arrows and shoot down de birds, dey'll start cooking before dey're even dead!", objectives = "" }
WordHunterWoW_QuestEN[48534] = { title = "Snarltooth's Last Laugh", description = "It's not just Mojambo's gang we have to worry about. We also need to keep a watchful eye at night due to frequent hyena attacks.\n\nDe most dangerous of de hyenas is Snarltooth. He ambushes us at night, laughing maniacally as he slaughters his prey.\n\nI need you to slay de beast once and for all! Snarltooth's den is just south of de arena in de Arid Basin.", objectives = "" }
WordHunterWoW_QuestEN[48535] = { title = "Nazmir, the Forbidden Swamp", description = "Da Horde promised Princess Talanji dat we be dealin' with dese blood trolls in Nazmir before dey can attack Zuldazar.\n\nGrab a pterrordax and get over ta Talanji's camp in Nazmir. We be waitin' for ya there.\n\nMake sure ya ready, {name}. Dere be no civilization in Nazmir, just us and whatever be lurkin' dere.", objectives = "" }
WordHunterWoW_QuestEN[48538] = { title = "An Airtight Alibi", description = "It'll take us a while to clean up the beasts that are left over, but I'm confident we'll be able to take back Fletcher's Hollow--thanks to you, of course.\n\nHere, take this letter to the constable. It should be enough to clear Miss Waycrest's name. \n\nI'm sorry you had to witness all of this, mainlander. We are good people, but these are terrible times.", objectives = "" }
WordHunterWoW_QuestEN[48539] = { title = "Freehold", description = "Well, there she is: Freehold.\n\nYou can get anything you want there, provided you can pay for it. \n\nWhether you pay with gold or steel is up to you.\n\nTake a look.", objectives = "" }
WordHunterWoW_QuestEN[48540] = { title = "Aiding the Wharf", description = "We have read the tides, and never before have I seen them in such turmoil. They call to the tidesages, begging for help.\n\nA debilitating sickness is running rampant amongst the villagers, and it comes from the sea.\n\nWe are but few. There is only so much we can do!\n\nPlease, take this list and gather the listed reagents from around the pier while I attempt to calm these folks. I should be able to create a tonic that will help.\n\nI hope.", objectives = "" }
WordHunterWoW_QuestEN[48542] = { title = "Strike Back", description = "The scroll details a dark spell which steals the souls from the neighboring Krokul to create a new demon, the Ur'zul. The scroll is signed by Lady Shahrazad.", objectives = "" }
WordHunterWoW_QuestEN[48544] = { title = "Woah, Nelly!", description = "{name}, you have my thanks. My Wranglers should be able to take it from here. If I can ask one more favor, would you pass a message to Chieftain Hatuun? Tell him the forest is secure once again. I'm sure he will reward you for all of your effort.\n\nI'll loan you one of my fastest Cragscalers for the trip. Make sure to look both ways before crossing that path outside this forest, there's a giant Legion Obliterator that patrols there. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[48549] = { title = "Grozztok the Blackheart", description = "A group of us were dropped off here and left to die. \n\nOur first night at camp, I was jolted from sleep by de gurgling cries of my fellow exiles. Jakra'zet sent assassins to our camp, looking for Rakera. \n\nTheir leader, Grozztok, came for me, but Rakera intervened. \n\nShe chased him into de dunes, but dat was days ago. \n\nIf you cross paths with Grozztok, don't hesitate to drive a blade into his black heart.", objectives = "" }
WordHunterWoW_QuestEN[48550] = { title = "Stolen Satchels", description = "One within our group spoke of a temple in de mountains dat welcomes exiles, though none are permitted to enter without an offering to their loa.\n\nI would have given anything to find some solace in dis wasteland, but now I have nothing, thanks to those thieving assassins.\n\nEach of us had a satchel dat carried de last of our possessions. We didn't have much, but it was more than one troll would need. \n\nIf you search de dunes looking for your friend, could you keep an eye out for our satchels?", objectives = "" }
WordHunterWoW_QuestEN[48551] = { title = "Wither Without Water", description = "The flora in this area weren't always so aggressive. \n\nWithout water, the thistlevines wither and waste until they become something unrecognizable and angry.\n\nTake my watering can and wet the withering thistlevines to prevent them from becoming carnivorous.", objectives = "" }
WordHunterWoW_QuestEN[48553] = { title = "Let it Flow", description = "The fountains here have seen better days. They're currently incapable of holding water, but we can fix that!\n\nYou can use my spare tools to repair the cracks. \n\nWith a little luck and elbow grease, the fountains will be flowing again in no time!", objectives = "" }
WordHunterWoW_QuestEN[48554] = { title = "The Source of the Problem", description = "I checked my work twice when working on this fountain. I made no mistakes. \n\nThere must be something wrong at the source. \n\nThe fountain draws water from a modest reservoir above the terrace. \n\nWould you mind checking it out?", objectives = "" }
WordHunterWoW_QuestEN[48555] = { title = "We Can Salvage the Seeds", description = "I've studied the flora within the terrace extensively. Once a thistlevine completely dries out, it's too late for the plant to be saved. \n\nIts seeds are still viable, however. Under the right conditions, they can be used to cultivate new, healthy thistlevines. \n\nSalvage seeds from the carnivorous thistlevines that can no longer be saved, and plant them within the fertile mounds of dirt. \n\nThe thistlevine plant is extremely quick to sprout, so the terrace should be filled with seedlings in no time!", objectives = "" }
WordHunterWoW_QuestEN[48557] = { title = "Sowing Saplings", description = "Algerson destroys the forests and leaves nothing remaining! It is up to us to take care of Azeroth, to help her live and grow as she was meant to!\n\nTake these seeds, find the soil that calls for them, and help our planet recapture her grace and vitality!", objectives = "" }
WordHunterWoW_QuestEN[48558] = { title = "The Irontide Crew", description = "You see those salty looking guys in red? That's the Irontide crew.\n\nThey're the worst of the worst. Cutthroats and brigands, to a man.\n\nIrontide wouldn't be guarding the docks if they didn't stand to gain something...\n\nLighten their pockets. See what kinda hardware they've got.", objectives = "" }
WordHunterWoW_QuestEN[48559] = { title = "An Offering of Light", description = "I sense it. The nobility in Xe'ra's heart. Her relentless defiance of the Legion. Let this be her legacy.\n\nIn building the Vindicaar, we fashioned the Netherlight Crucible to harness the tremendous powers at play on Argus. I believe Xe'ra's essence is one key to that potential.\n\nYet the Light alone is not enough. Without balance, there can be no harmony, no cohesion.\n\nInfuse this essence into the crucible, champion. It is the first step in unlocking the strength needed to end the Burning Crusade.", objectives = "" }
WordHunterWoW_QuestEN[48560] = { title = "An Offering of Shadow", description = "Can you sense it, {name}? The darkness within this essence is palpable.\n\nIn the past, I might have shunned such power, even denied its very existence. But what have we learned throughout our long struggle, if not that Light and shadow must coexist?\n\nThis may prove to be exactly what we need to bring balance to the Netherlight Crucible. To give us the edge we need against the Legion.\n\nInfuse this essence into the crucible, champion. Draw one step closer to realizing your weapon's full potential.", objectives = "" }
WordHunterWoW_QuestEN[48573] = { title = "Crocolisk Life", description = "I need my shaman mojo back if we are going to kill Urok. He beat me bad de last time I tried to put him down.\n\nYou help me get my power back, and I help you make Urok dead. Deal?\n\nFirst step, I need you to use dis dagger to absorb what is left of de life force of any crocolisk you kill.\n\nWhen de dagger seems full, come find me.\n\nHeh heh, dat's right Sur'jan. Dey gonna help us, den Urok will see who de strongest is!", objectives = "" }
WordHunterWoW_QuestEN[48574] = { title = "Pulling Fangs", description = "I need more things to help me get strong. I need you to get me some saurid teeth.\n\nNo, Sur'jan, you're not trusting him TOO much. Just enough. I won't be betrayed again.\n\nI need dese teeth for a ritual I'm gonna perform to help me get my power back. Once I'm not so weak, you and I are gonna take down dis undead monster.", objectives = "" }
WordHunterWoW_QuestEN[48576] = { title = "Safe Flying", description = "I'm feeling... stronger! But I need more power before we take down Urok.\n\nNo, Sur'jan, YOU are scared of Urok more than me. I'm not scared of nothing!\n\nYou got an attachment to me now after dat ritual. I need you to go kill de skyterrors nearby. Their deaths will fuel my strength.\n\nTake my grappling hook. You can drag de skyterrors down from de sky with it, and it'll put de hurt on dem too.", objectives = "" }
WordHunterWoW_QuestEN[48577] = { title = "Terrorizing their Eggs", description = "Sur'jan, I should be doing dis! What do you mean, I need to recover? Bah, fine.\n\nI need more power, and de skyterrors have eggs nearby. I need you to bash some of their eggs to fuel my energy.\n\nThose eggs got lots of life force in dem. You destroy dem, and I will feel de energy coming back to me.\n\nCome on, Sur'jan, dis will be easy! I can do dis! Hmph... well, you make a good point. You always were de smarter one out of us.", objectives = "" }
WordHunterWoW_QuestEN[48578] = { title = "There's No Eye in Skyterror", description = "There's a real big skyterror dat I name Jarkadiax. I need his tongue...\n\nWhat's dat, Sur'jan? Not his tongue? His eye? You sure? Hrm.\n\nI need his eye for my next ritual. I know what you're thinking. De tongue makes more sense. Dat's what I--\n\nLook, Sur'jan, I still think it's his tongue. We'll see which of us is right!\n\nGo get Jarkadiax's eye and bring it back to me for de next ritual.", objectives = "" }
WordHunterWoW_QuestEN[48581] = { title = "A Good Spanking", description = "Pinky is contained in de direhorn pen for now, but de handlers are having a real hard time with him!\n\nDis calls for some tough love.\n\nWill you help dem?", objectives = "" }
WordHunterWoW_QuestEN[48584] = { title = "The Blood of My Enemies", description = "I feel my power returning, but we aren't done yet. We need more power to kill dis undead Urok.\n\nWe'll be pushing in to Urok's lair. Dreadticks are swarming in de area. I want you to bring me their blood for de final ritual.\n\nTake dis. It's my trusty dreadtick gasser. Throw it in de area, dreadticks sniff it... den DIE! Hahaha! Now get going!\n\n...Sur'jan, you keep telling me to let him do dis sorta work, but I could do it too! Fine, I'll just work on getting de ritual ready.", objectives = "" }
WordHunterWoW_QuestEN[48585] = { title = "Wasteland Survivor", description = "<The leather has become dry and cracked in the sun, but the supplies inside are mostly intact.\n\nIt's unknown what gruesome death befell the backpack's former owner, but supplies like these are in high demand among the outcasts.\n\nThe desert has claimed many lives... perhaps there are more supplies to be found among the dunes. >", objectives = "" }
WordHunterWoW_QuestEN[48590] = { title = "My Head and Shoulders", description = "If we're going to fight Urok, I will need my gear back. It was all lost when I was running from Urok de first time.\n\nShut UP, Sur'jan! I had to ditch it in order to run faster.\n\nBring my gear back to me, and I'll be ready to fight Urok with you.", objectives = "" }
WordHunterWoW_QuestEN[48591] = { title = "Urok's True Death", description = "This is it! My power is back; we are ready to put down Urok. He used to be a noble beast, you know. Big, strong.\n\nNow Urok is just a mindless undead. It isn't right. We'll put him to rest.\n\nI'm going to run up ahead. When you get near Urok, I'll hop out to ambush him. Let's do dis!\n\nShut up, Sur'jan. Of course we're going to win! If we don't, I'll just find another {class} to help me out.", objectives = "" }
WordHunterWoW_QuestEN[48597] = { title = "Saurolisk Escape", description = "You cautiously approach a saurolisk tied to a post. It doesn't snap at you, but looks at you with defeat in its eyes.\n\nThe troggs seem to be keeping these saurolisks against their will. They should be freed before they are abused further.", objectives = "" }
WordHunterWoW_QuestEN[48600] = { title = "Take the Edge Off", description = "The demons streaming out of Antorus equip themselves at Felfire Armory. We need to deny those weapons. Will your {class}s fight alongside the Army of the Light once again?\n\nBefore the assault, gather materials. My smiths will craft your soldiers more powerful armor. The Legion won't give up Felfire without a fight.", objectives = "" }
WordHunterWoW_QuestEN[48601] = { title = "Felfire Shattering", description = "A thin series of stone bridges connects the Burning Breach to Felfire Armory over Fiend's Run. The Army of the Light will stem Legion reinforcements while your people deal with the armory itself.\n\nWork swiftly.", objectives = "" }
WordHunterWoW_QuestEN[48604] = { title = "Home Again, Home Again", description = "I can't thank you enough for the help here! You showed up just in time.\n\nHere is Elijah's sausage order. Don't worry, it's just regular sausage- nothing questionable.\n\nNow if you'll excuse me I have to see to my workers.", objectives = "" }
WordHunterWoW_QuestEN[48605] = { title = "Commander's Downfall", description = "A champion of the Legion is vulnerable within an invasion point! Track it down and destroy it before it can return to fight on Argus.", objectives = "" }
WordHunterWoW_QuestEN[48606] = { title = "Loaded for Bear", description = "<This glittering cannonball stands out from the others. You notice the familiar sheen of Azerite across the surface.\n\nYou can't help but notice the nearby cannon, conveniently pointed at the ships loaded with stores of Ashvane Company weapons.>", objectives = "" }
WordHunterWoW_QuestEN[48616] = { title = "Bolas and Birds", description = "Up in the mountains we know the value of a good hunting companion. We use bolas to shoot down our flying prey, then our retrievers go and bring us our kill!\n\nYou want to take a shot? Nickel can accompany you. Shoot down some of the falcons in the woods. My dog will finish the job.", objectives = "" }
WordHunterWoW_QuestEN[48620] = { title = "Greater Invasion Point: Mistress Alluradel", description = "", objectives = "" }
WordHunterWoW_QuestEN[48622] = { title = "The Vanishing Lord", description = "Unfortunately, we don't have any contacts within House Waycrest, so our efforts in Drustvar will have to start from the ground up.\n\nWe have arranged for a ferry to take you to Fallhaven - a farming village in eastern Drustvar. The mayor there, Cyril White, is a longtime friend of the Proudmoores, and I think he can help us get in touch with someone from the house.\n\nI hope you can get to the bottom of their absence, {name}. Their martial might is invaluable to the Kul Tiran fleet.", objectives = "" }
WordHunterWoW_QuestEN[48653] = { title = "A Bejeweled Prison", description = "<As you gaze into the strange gem you feel a sudden need to travel into the swamps of Nazmir and return the gem to it's rightful resting place, wherever that may be.>", objectives = "" }
WordHunterWoW_QuestEN[48654] = { title = "Beneath Oronaar", description = "The krokul we found beneath Oranaar did not wish to leave. Could you speak with him, {name}? Convince him to board the Vindicaar.", objectives = "" }
WordHunterWoW_QuestEN[48655] = { title = "The Chef's Apprentice", description = "<Sezahjin rummages through his cooking ingredients in frustration.>\n\nWhere is Junji? I sent him to scavenge for vulture eggs, but he hasn't returned.\n\n<Sezahjin pauses for a moment.>\n\nHe was just going on about de size of saurolisk eggs, but those oversized lizards are far too dangerous for a boy! He can't possibly be so foolish...\n\nIf he has gone to de saurolisk breeding grounds... he may already be dead. Please find him before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[48656] = { title = "Savage Saurolisks", description = "Please, help me! I'm trapped in dis box and I can't make it out alone!\n\nI came here to collect eggs. I knew it was a bad idea, but I thought I could sneak around and grab de eggs before de saurolisks noticed.\n\nI was wrong...\n\nI hid underneath dis crate to avoid being eaten!\n\nCan you clear out de saurolisks and tell me when it's safe to come out?\n\nPlease, don't leave me here!", objectives = "" }
WordHunterWoW_QuestEN[48657] = { title = "They Might Be Delicious", description = "Saurolisk eggs are de most delicious eggs in de desert!\n\nI mean, I've never tried dem myself... but look at de size of them! Dey're huge! Bigger is better, right?\n\nIf I go back to camp empty handed, Sezahjin is going to kill me! We have to get some of those eggs!\n\nYou sound a lot older and stronger than I am. Gather up de eggs so we can take dem back for everyone to eat.\n\nDon't worry about me, I'll wait for you here. It's not like I'm going anywhere...", objectives = "" }
WordHunterWoW_QuestEN[48668] = { title = "Lightforged Beacon: City Center", description = "Hail, friend!\n\nCaptain Fareeya sent us ahead to secure this area. We were just about to call down a beacon and report back to the Vindicaar.\n\nWe would be honored if you would help us complete our mission.\n\nThe signal beacon just needs a light touch. The Grand Artificer will do the rest.", objectives = "" }
WordHunterWoW_QuestEN[48669] = { title = "Urok, Terror of the Wetlands", description = "You! You can help me!\n\nI know, Sur'jan, he looks like a {class}, but I know we can trust him.\n\nUrok, de terror of de wetlands, is undead now. We have to put it down before it tries to destroy dis entire place.\n\nJust give me a minute, and you will see dat Urok is bad news.\n\nShhh, Sur'jan, dey gonna see, dey are all gonna see!", objectives = "" }
WordHunterWoW_QuestEN[48670] = { title = "Runaway Rider", description = "Lord Norwington demanded I take Eddie out riding in the woods, but I knew it was too soon! I just knew it!\n\nWe've got to go find him. Meet me across the river!", objectives = "" }
WordHunterWoW_QuestEN[48677] = { title = "Wicker Worship", description = "Hail, traveler! You look like just the sort who might be able to help me out with a predicament!\n\nIt's my son Edwin, you see. We were travelling through Drustvar to ply our wares when the damned fool ran off to join some cult here in Autumnvale! Since then we haven't seen a trace of him, and the brown-robed loons won't speak a word of his whereabouts!\n\nCould you see if you could persuade them to talk? His poor mother is worried sick!", objectives = "" }
WordHunterWoW_QuestEN[48678] = { title = "Questionable Offerings", description = "So the traders sent you? As I told them, I only discuss the happenings of our family with those who understand our cause.\n\nIf you wish to know his whereabouts, you must prove that you do.\n\nBehind us are several items gathered for offering to the Wicker Man. Bring us the items you feel will most appease it, so that it might give us its blessing.\n\nChoose the correct offerings, and we will know your intent.", objectives = "" }
WordHunterWoW_QuestEN[48679] = { title = "Mind the Hives", description = "The one called Edwin came to us not long ago, seeking to earn the blessings of the Wicker Man.  He wandered off into the hills looking for his own offering.\n\nUnfortunately, he managed to disturb one of the nearby beehives, causing the insects to become rather frenzied.\n\nThat was the last I saw of him, I'm afraid.", objectives = "" }
WordHunterWoW_QuestEN[48682] = { title = "A Simple Sacrifice", description = "You must hurry! Lord Autumnvale brought Edwin off to that cave right when he returned, saying something about \"an offering of blood!\"\n\nI think they mean to sacrifice him to appease the Wicker Man!\n\nJust what kind of crazy cult is this?!", objectives = "" }
WordHunterWoW_QuestEN[48683] = { title = "Changing Seasons", description = "I appreciate you saving me again, but we should do something to prevent this from happening to anyone else.\n\nSo long as that Wicker Man stands, it will attract more like Autumnvale to it.\n\nWe should destroy it! Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[48684] = { title = "On the Move", description = "Jorak's wounds have healed enough for him to travel.\n\nHe has agreed to guide us to de temple. \n\nDe sooner we leave, de better. Rakera won't survive in dis desert for long.", objectives = "" }
WordHunterWoW_QuestEN[48699] = { title = "Sneaking into Zalamar", description = "I know you might think nothing has changed, but trust me, de voodoo worked... I think.\n\nYou should transform into one of de blood trolls when you are near Zalamar, one of their villages.\n\nJo'chunga should be dere somewhere, most likely near a large gathering of blood trolls.\n\nFind Jo'chunga and tell him I have sent you, den see what he knows about de situation dere.", objectives = "" }
WordHunterWoW_QuestEN[48715] = { title = "Akunda Awaits", description = "I've spoken to every troll out here, asking if they've seen Rakera. As you might have guessed, Akunda is de only name dey know. \n\nLet's hope someone within de temple will be able to tell us something useful.", objectives = "" }
WordHunterWoW_QuestEN[48752] = { title = "A Need For Coal", description = "Ah! {name}! Just the person I was hoping to see!\n\nI was just getting ready to smelt some monelite down into ingots, but I noticed my coal supply was running low.\n\nWell, I mean... I have coal, yes, but I prefer using Ashvane Coal. It puts out less smoke and burns hotter, so I need less of it.\n\nIf you can  get some Ashvane Coal from the Ashvane Foundry south of here, I'd be more than willing to give you a couple pointers for mining monelite. Deal?", objectives = "" }
WordHunterWoW_QuestEN[48753] = { title = "Emergency Transplants", description = "With everything that's been happening over in Drustvar, there's been a sudden surge of wildlife in the sound. Normally, I wouldn't care, but they've been eating all the riverbud!\n\nIf things don't improve soon, we could try thinning their numbers so they don't consume everything, but I'll consider that the last resort.\n\nInstead, could you go plant some of these seeds to produce additional food for them?", objectives = "" }
WordHunterWoW_QuestEN[48754] = { title = "Breaking The Food Chain", description = "The extra riverbud you planted has helped, but it's not enough.  Some of the local wildlife are consuming the riverbud before they mature. The more riverbud that is eaten, the less we have for our own needs.\n\nThe largest group of young riverbud consumers are the turtles.\n\nIf the riverbud becomes a threatened species, we'll need to regulate harvesting it. Instead, go thin the number of the turtles in the area.\n\nDo that and I'll teach you everything I know about riverbud.", objectives = "" }
WordHunterWoW_QuestEN[48755] = { title = "Pollen Punching", description = "What I think happened is that some creature lapped up all the pollen with it's tongue.\n\nWhile I'm curious as to what creature could have done this, I doubt it matters. I believe we can safely reproduce this without needing any sort of rare or dangerous reagents.\n\nNext time you find a siren's sting, simply try wetting your glove so the pollen will stick to it. Water, wine, spit... It shouldn't matter.", objectives = "" }
WordHunterWoW_QuestEN[48756] = { title = "Here In Spirit", description = "Hey, {name}, how would you feel about doing some legwork for a favor?\n\nWe have a tradition here in Kul Tiras, that during a celebration, be it funeral, wedding, or birthday, we incorporate star moss into the decorations. We do that so those who are no longer amongst the living can be here in spirit.\n\nWith the recent fighting, my stores are near empty due to the number of funerals we've had.\n\nIf you bring me fresh star moss to restock my supply, I'll share a secret on how to get more from each star moss.", objectives = "" }
WordHunterWoW_QuestEN[48757] = { title = "Ghost Busting", description = "I hate to ask this of you, but are you available for some more grunt work? I'd do it myself, but this seems beyond my capabilities.\n\nRemember how I told you we use star moss to allow those no longer living to join us for a special day?\n\nYeah, well, sometimes once they show up, they don't want to leave.  There is a spirit on the other side that is lashing out, harming those it should be protecting.\n\nTake this smoldering star moss and cleanse the area until you find the offender and help them move on.", objectives = "" }
WordHunterWoW_QuestEN[48758] = { title = "Disgustingly Damp Flower", description = "Rummaging for pollen as usual, you use the harvesting technique you learned from the bees.  However, when you pull your hand away from the flower, you find that there is no pollen on your gloves.\n\nLooking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all within it.  Upon closer inspection you see that the flower is filled with a viscous liquid.  Could the flower have done this?\n\nWhile unpleasant to touch, you carefully pluck the flower to show Declan.", objectives = "" }
WordHunterWoW_QuestEN[48759] = { title = "Akunda's Bite - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48760] = { title = "Akunda's Bite - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48761] = { title = "Spiderphobia", description = "You're no stranger to monster fighting, right?\n\nThe other day I found a spider just outside my house. Nothing out of the ordinary, except it was the SIZE OF A HORSE!\n\nTwenty-five minutes of screaming and pick-axeing later and I had managed to kill it.\n\nI spoke with one of the guards, and he said that there was a huge nest of them just over the hill to the northwest.\n\nIf you can slay them or whatever you do, I'll teach you a secret to mining monelite. Otherwise, I'm going to have to move.", objectives = "" }
WordHunterWoW_QuestEN[48762] = { title = "Meet Sweetflower", description = "It looks like you've become familiar with the plants around here. There's a flower that grows in the snowy parts of the continent, but I can't tell you much else about it.  Can't stand being cold.\n\nHowever, if you're interested in learning more, I know of someone who may be able to teach you.\n\nHer name's Xun Xun Sweetflower, and last I heard she set up shop on the outskirts of Anyport over in Drustvar.  Tread carefully, though, that area is crawling with Irontide Raiders.", objectives = "" }
WordHunterWoW_QuestEN[48763] = { title = "The Frigid Boon", description = "While harvesting this winter's bite, you managed to pluck the flower without breaking any petals, a feat you had not accomplished before.\n\nTaking a quick mental note of every detail about yourself and your surroundings, one point sticks out to you.\n\nThe heat from your breath appears to have made the petals supple enough to bend instead of break. You also believe that this may be a way to prevent the flower from activating its defensive cold blast.\n\nIf that is the case, it could be extremely useful.", objectives = "" }
WordHunterWoW_QuestEN[48764] = { title = "Don't Pick a Fight", description = "Hey, you're not busy, right? I could use your help.\n\nYa see, I was out mining in Stormsong Valley, when this huge, two-headed monstrosity started chasing after me!\n\nI ran away, but I was back in Boralus when I realized I dropped my favorite mining pick!\n\nI know this may sound stupid, but if you could get it back for me I'd be grateful.\n\nYou don't need to do something crazy, like fight them. Instead, sneak by them and grab it.\n\nI'll show you a trick to mining monelite seams for your troubles.", objectives = "" }
WordHunterWoW_QuestEN[48765] = { title = "Aromatic Pollen - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48766] = { title = "Aromatic Pollen - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48767] = { title = "Seams Familiar", description = "You find a necklace in the shape of an anchor with the name \"Cabot\" etched in a banner.\n\nThe name immediately brings up Myra Cabot, the mining trainer in Boralus.\n\nThe condition of the necklace makes it look like it has been well maintained. She probably wants it back.", objectives = "" }
WordHunterWoW_QuestEN[48768] = { title = "Brined Justice", description = "{name}, I just got word that one of our ships was attacked and a large amount of storm silver stolen!\n\nThe sacred materials can't be replaced. Once it is blessed by the seapriest, it is buried underwater for a year!\n\nFrom what I heard, a group of pirates followed the ship to see where the metal was buried on the sea floor before killing the crew and taking her cargo.\n\nKill the pirates and get back that metal.", objectives = "" }
WordHunterWoW_QuestEN[48769] = { title = "Gathering Mementos", description = "I have a task that I can't really trust to anyone else, and I feel you could handle it with the reverence it deserves.\n\nAn old friend of mine came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship south east of Freehold. I'm not sure if it was pirates, the Horde, or a squall, but she said she didn't want revenge, just closure.\n\nIf you could get her something to remember him by, I'll tell you everything I know about sea stalks, and you'd have my gratitude.", objectives = "" }
WordHunterWoW_QuestEN[48770] = { title = "Three Sheets to the Wind", description = "Hey, {name}.  Now isn't a great time for me.\n\nIf you're interested in learning, you could talk to Franklin, my old apprentice. He used to be a damn fine miner, but now he's just a washed up drunk. You can find him asleep on the docks.\n\nI don't remember what he drinks, but if you bring him something he's sure to at least try it. He'll talk if he likes it.\n\nTalk to Harold Atkey, the bartender, he's sells a variety of drinks, I'm sure one of them is his choice.", objectives = "" }
WordHunterWoW_QuestEN[48771] = { title = "Herb 07 - Rare - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48772] = { title = "Herb 07 - Rare - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48773] = { title = "Papers, Please", description = "All this legwork will be for nothing if we can't show Katherine hard proof linking the Ashvane Company to the freebooters here in Freehold.\n\nAshvane might have been careful to encrypt their books, but I doubt the dockmaster here has any reason to be so secretive.\n\nCheck his office and find us something--anything--that connects him to Ashvane.", objectives = "" }
WordHunterWoW_QuestEN[48774] = { title = "The Beatings Will Continue", description = "Ain't seen you before. You a mercenary? \n\nI got some guys need roughin' up.\n\n<The grizzled woman spits through a gap where her front tooth should be.>\n\nEver since Harlan started fancyin' himself an admiral, his Irontide guppies been struttin' around like they own the place. Forcin' other crews to swear loyalty to Harlan, beatin' on us what can't defend ourselves.\n\nFreehold was never a safe town, but at least it was free.\n\n<She runs her tongue along the gap in her teeth.>\n\nBastards.", objectives = "" }
WordHunterWoW_QuestEN[48776] = { title = "Rig Robbing", description = "I'm out here tryin' to enjoy my break, but I ran outta hooch.\n\nGot some grog hidden in the water just off the dock, stashed in a crate tied up to some of the rigging. \n\nDo me a favor and fetch it, will ya? Rigging's pretty tangled so you might have to pull in a few lines before you get the right one.\n\nI'd do it myself, but if they see me they're gonna force me back to work unloadin' them new weapons.", objectives = "" }
WordHunterWoW_QuestEN[48778] = { title = "Stone Soup", description = "On the surface of the rock you find carvings of what you make out to be ingredients.\n\nIf you find the ingredients, perhaps you can make the troggs' soup for yourself.", objectives = "" }
WordHunterWoW_QuestEN[48790] = { title = "Stolen Goods", description = "It was brought to my attention recently dat many of our supplies went missing overnight.\n\nI suspected dat Tongo's crew was behind de theft, but we didn't have de strength or numbers needed to confront dem.\n\nI want you to search de hideout for signs of our missing supplies. If dere's anything left when you arrive, bring it back here and I'll make sure you're compensated.\n\nIf we're going to survive Mojambo's assault we're going to need those stolen supplies back as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[48792] = { title = "Menace to Society", description = "These troggs are a menace to the whole area! They raid camps and caravans and eat the livestock when they come down from their caves. The kids being up there might set them off!\n\nSlay some of those troggs before they decide to cause trouble.", objectives = "" }
WordHunterWoW_QuestEN[48793] = { title = "The Adventurer's Society", description = "Thank the Light!\n\nI was taking care of my grandson and his friends. I told them to play quietly while I took a nap. When I woke up they'd left a note saying they were 'Going on an Expedition'. They think they'll find Titan relics in the trogg caverns!\n\nThey're too young to fight troggs and I'm too old! My bad knee almost gave out getting here.\n\nYou look strapping. Find my grandson and the rest of the 'Adventurer's Society'. Send them home!", objectives = "" }
WordHunterWoW_QuestEN[48796] = { title = "Supporting Light's Purchase", description = "Our northern foothold is overrun, {name}. We must redouble our efforts in the south.\n\nThe teleporter network should still be operational. Meet with Alleria and see where she needs you the most.", objectives = "" }
WordHunterWoW_QuestEN[48798] = { title = "Ice the Ace", description = "Legion vessels continue to vex us. Time to do something about that.\n\nThese weapons are only as effective as the demons who operate them. Separate the two and both are vulnerable.\n\nIt seems one of their most infamous pilots has left his ship. See to it that he does not return to it.", objectives = "" }
WordHunterWoW_QuestEN[48799] = { title = "Fuel of a Doomed World", description = "There is a rare and precious resource to be found in these wastes, {name}.\n\nArgunite was once abundant on Argus. Its magical properties helped eredar civilization thrive. Far better for us to make use of its power than the Legion.\n\nSeek out all the pristine argunite you can, champion. Every bit you recover will aid our cause.", objectives = "" }
WordHunterWoW_QuestEN[48800] = { title = "Mark of the Bat", description = "Dere are three witches in de camp who have talismans empowered by Hir'eek.\n\nI need you to get those talismans for me to use after you prove my poison works perfectly.\n\nI will use de essence of Hir'eek within de talismans to make my own poison strong enough to use against de loa.\n\nIf my poison doesn't work... well, I do not want to think about dat. It will work, because we need it to. \n\nJust go get de talismans. I will be here, hiding from de blood trolls.", objectives = "" }
WordHunterWoW_QuestEN[48801] = { title = "Isolating Zalamar", description = "Hir'eek, de loa of bats, has been corrupted by G'huun! We will get no help from him.\n\nWe only have one option if dey have a loa on their side... we must kill Hir'eek.\n\nIt's crazy, and we will both probably die, but I have a plan. We need to isolate dis place first.\n\nDe blood trolls have wardrummers who sound an alarm if anything happens here. We need dem gone... but you have to be sneaky about it.\n\nYou have a good disguise, so you can order de drummers to go leave their posts.", objectives = "" }
WordHunterWoW_QuestEN[48803] = { title = "Forging a Key to the Past", description = "The armory key fragments are gathered, and the dendrite clusters should provide just enough power to reforge the key.\n\nThis should not take long... assuming it works. It has been a long time since I made one of these!", objectives = "" }
WordHunterWoW_QuestEN[48804] = { title = "Mistakes Were Made", description = "My friends and I wanna be explorers so we made the Society. There are troggs here, right? So that means there's probably ancient stuff nearby!\n\nThe books say troggs like shiny things so we pooled some of our allowance and gave them gold so we could dig.\n\nIt didn't work out like we expected.\n\nI escaped but they've got my friends! I've been trying to think about how to get them out.\n\nCould you do it? We'll include you in our exploration report as an honorary member!", objectives = "" }
WordHunterWoW_QuestEN[48805] = { title = "Research Recovery", description = "<The discarded paper contains a list of the items the Adventurer's Society has found during the course of their 'excavation' here at the Northern Caverns.\n\nIt is unlikely they actually found relics, but there's no harm in recovering the items the kids found. At the least they're souvenirs of the adventure.>", objectives = "" }
WordHunterWoW_QuestEN[48808] = { title = "Thesis Statement", description = "My thesis!\n\nThose smelly troggs took my thesis paper and fed it to their boars! Can you believe it!?\n\nI worked forever on it! Two whole days! If I don't get it back I'm ruined! Absolutely ruined!\n\nPlease get my thesis paper back for me?", objectives = "" }
WordHunterWoW_QuestEN[48823] = { title = "Projection Destruction", description = "Dis lich, Zardrax, be tryin' ta corrupt us ta join his side, {name}. I not be fallin' for it, and I know how ta be stoppin' it.\n\nHe be gatherin' power from dem mounds of skeletons. We gotta burn 'em ta cut Zardrax off a some power.\n\nI be strong in da fire mojo. I can be impartin' some of me connection to da fire to ya ta burn dem mounds.\n\nI be stayin' here with Kal'dran. I tink Zardrax be gettin' ta him.", objectives = "" }
WordHunterWoW_QuestEN[48825] = { title = "Power Denied", description = "Ah! Oh, it's you, {name}. Zardrax has me on edge, saying we are all doomed, dat dere is no hope.\n\nI had a plan to stop him. All we had to do was kill a hexxer, Nana'kwug, who is helping spread Zardrax's power, and steal de fetish she is using.\n\nDen you'd give dat fetish to Da'jul and he'd use his voodoo to grant us more power.\n\nBut it is hopeless now. Maybe we should just side with Zardrax. How can we stop someting as big as dis?", objectives = "" }
WordHunterWoW_QuestEN[48840] = { title = "Ruins-Level Marketing", description = "Now dat de Goldtusk Inn be open for business, we gotta make sure everyone in Vol'dun knows about it!\n\nI think we should focus on those wagon-riding vulpera first. Dey don't even have real homes!\n\nIn fact, I saw a pack of vulpera up at de ruins to de north de other day, and dey barely had anything.\n\nTake dem dis coupon and tell dem to stop by for a free first stay.", objectives = "" }
WordHunterWoW_QuestEN[48846] = { title = "Liquid Motivation", description = "<Zauljin motions for you to come closer. He is clearly drunk.>\n\nIf I had information concerning Mojambo...<hick!>...how much would dat be worth to you?\n\nYou don't...<hick!>...believe me? Nobody suspects a drunk. I hear all sorts of things...\n\nWhat do you have to lose? All it will cost is a bottle of...<hick!>...Zanchuli Reserve!\n\nWhaddya say, mon?", objectives = "" }
WordHunterWoW_QuestEN[48847] = { title = "Arming the Tribe", description = "We spotted some of Tongo's gang scouting de arena while you were away. It seems dis may be de calm before de storm.\n\nWe need to get de weapons you brought back from Tongo's hideout into de hands of our fellow outcasts. Mojambo's gang could attack any minute now.\n\nWe need to be prepared. Take de weapons and get dem to de unarmed members of de tribe.\n\nIf Mojambo thinks he can raid our home without a fight, he's got another thing coming.", objectives = "" }
WordHunterWoW_QuestEN[48850] = { title = "Tongo", description = "If Mojambo hired Tongo's gang as reinforcements, we're in even more trouble than we first thought.\n\nTongo is a cruel and sadistic marauder who takes great delight in suffering. His gang is notorious for torturing their prey.\n\nWe won't be able to defend ourselves against both gangs at once. Our only chance of survival now is to strike first.\n\nIf you take out Tongo before de ambush, Mojambo will be expecting reinforcements dat never arrive. We may be able to use dat to our advantage...", objectives = "" }
WordHunterWoW_QuestEN[48853] = { title = "Terminal Degree", description = "That's everyone but Nigel.\n\nHe's in the big cave! I bet he went in there to look for relics, but now he's tied up!\n\nWould you save him too?", objectives = "" }
WordHunterWoW_QuestEN[48854] = { title = "Offer of Power", description = "Ah... a {class}. You must be {name}... I have heard whispers of your name. Maybe you are smarter than dese two.\n\nZuldazar will fall to de blood trolls. You know dis. \n\nYou can be saved, if you promise to serve me. I can give you more power than you have ever imagined.\n\nListen to what I can offer you...", objectives = "" }
WordHunterWoW_QuestEN[48855] = { title = "Humbling the Terrors", description = "When we first got here, I be findin' a whole buncha problems on da other side a Zardrax's barrow. \n\nDere be dese monstrous zombies walkin' around da area. We gotta take 'em down ta make sure dey don't get ta Zuldazar.\n\nI used me voodoo ta be modifyin' dat fetish ya just found. Use dis new fetish ta weaken and kill dem zombies.", objectives = "" }
WordHunterWoW_QuestEN[48856] = { title = "Conduit Interruption", description = "Dere be skeletons dat be funnelin' blood magic inta Zardrax's barrow. Me guess be Zardrax created dem ta help gather more power.\n\nYa gotta kill dese skeletons if ya want any shot at killin' dis lich. He should be gettin' weaker if he not be havin' dem as a source a power.\n\nI be stayin' here in da meantime ta be watchin' our backs, no tellin' if dere be blood trolls comin' ta attack us.", objectives = "" }
WordHunterWoW_QuestEN[48857] = { title = "All Hope is Lost", description = "I am not doing dis anymore! You and Da'jul are WRONG! Dere is no stopping Zardrax!\n\nI am leaving, and you cannot stop me. Zardrax will save us all from destruction and give us new power!", objectives = "" }
WordHunterWoW_QuestEN[48864] = { title = "The Broken Blacksmith", description = "{class}, I believe this may be a piece of the key to the Armory of the Triumvirate. We locked it behind us as we made our escape from Argus. The last time I saw it, my second in command, Atalaa, was leading a force to secure the armory. That was so long ago...\n\nI cannot be certain, but there may be another who would know. The smith who forged the key was called Gaal. With the reports of broken surviving on Krokuun, he may still live.", objectives = "" }
WordHunterWoW_QuestEN[48869] = { title = "Payback's a Lich", description = "We can't be focusin' on da loss of Kal'dran. He be givin' up hope, and dat be someting we not gonna do.\n\nDis be da time ta strike at Zardrax. His power be waning. \n\nGo inta da heart of his barrow and destroy him, once and for all. Dat should show dem blood trolls who dey messin' with!\n\nI'd help ya, but I be weakened from da blood trolls dat be attackin' me when ya were gone. \n\nDon't worry 'bout me, I can still be handlin' dem animals if dey come back.", objectives = "" }
WordHunterWoW_QuestEN[48871] = { title = "Rescue the Relics", description = "According to the information you brought us, we should be adding those relics to our collection.\n\nExplore the ruins and see if you can find any of these \"tokens of affection\" the sethrak may have left for their Keepers. \n\nBetter we find hands that will cherish them, than ones that will destroy.\n\nPlus, add a little time, and anything becomes interesting... to the right people.", objectives = "" }
WordHunterWoW_QuestEN[48872] = { title = "Expedite the Excavation", description = "Everywhere we go, there they are. Sethrak. And it's never the ones you want to see.\n\nIt seems they are looking for some key. With this new information, I do not think they are looking in the right place.\n\nReally, as entertaining as it is to confound them, we need to wrap up our work here and move on.\n\nIf you could remove some of them, it would greatly help our crew!", objectives = "" }
WordHunterWoW_QuestEN[48873] = { title = "A Grizzly End", description = "This lodge serves as the largest supplier of furs and leather to Boralus.\n\n<Kennings puffs out his chest a bit.>\n\nAnd as its proprietor, it is my duty to ensure every request is met on time. With recent delays, I've decided to take a trip out here to see if the Holtons need my assistance.\n\nWe could use any available hands! Take this knife and bring back some pelts from the bears in the nearby pass.", objectives = "" }
WordHunterWoW_QuestEN[48874] = { title = "Pardon Our Rust", description = "The traps we've set up in the field require routine maintenance checks. Some of them are fairly old and will spring at incorrect times. If only we could get more funding for these sort of supplies. \n\n<The huntmistress glances towards Lord Kennings.>\n\nWhile you're out hunting, could you reset any sprung ones that you find?", objectives = "" }
WordHunterWoW_QuestEN[48879] = { title = "A Hunt for Hawk Eggs", description = "Before Alanna sends us on our grand hunt, there is something more immediate demanding our attention...\n\nI'm absolutely famished! No good man can hunt on an empty stomach.\n\nThere are hawks in the area, which means that there are also hawk eggs. I'm not sure how well they'll do in an omelet, but I'm always one for a culinary adventure!\n\nGood {class}, could you bring back a few before we get started?", objectives = "" }
WordHunterWoW_QuestEN[48880] = { title = "Mean Gulls", description = "Must... catch... Need more...\n\nThe gulls... they bite... scratch... take...\n\nI need them gone... but... I must... catch...", objectives = "" }
WordHunterWoW_QuestEN[48881] = { title = "The Reel Deal", description = "<These fishing rods must have been left behind when Art moved from the beach.  Most of them seem to have bites.\n\nMaybe you should reel them up and see what's hooked?>", objectives = "" }
WordHunterWoW_QuestEN[48882] = { title = "I Like Fish Guts and I Cannot Lie", description = "<It looks like some of the fish the gulls have been stealing from Art are still intact.\n\nHe'd probably be happy to get the innards from these as well.>", objectives = "" }
WordHunterWoW_QuestEN[48883] = { title = "Big Gulls Won't Die", description = "Still one more... takes my bait... my fish...\n\nMy finger...\n\nKill him... you will be... rewarded...", objectives = "" }
WordHunterWoW_QuestEN[48887] = { title = "Cleanse the Mind", description = "If you wish to invite Akunda into your mind, it can't be bogged down by fear or regret. \n\nMeditate at de Shrine of Thunder and confront whatever demons linger in de dark recesses of your mind.", objectives = "" }
WordHunterWoW_QuestEN[48888] = { title = "It Springs Eternal", description = "Water is a sacred resource in dese dunes, but those within dis temple never know thirst. \n\nAkunda commands de storm, allowing de nearby spring to never run empty. \n\nUnfortunately, our eternal water source attracts a variety of animals dat are a plague upon our temple. \n\nRid de valley of their presence before you return.", objectives = "" }
WordHunterWoW_QuestEN[48889] = { title = "Repairing the Past", description = "Dis explains why de loa has been silent. Akunda himself has forgotten who he is!\n\nSomeone or something must be abusing his power. \n\nWe won't know how to help without speaking to de loa.\n\nI can perform a ritual dat may repair Akunda's mind, but it is not without risk.", objectives = "" }
WordHunterWoW_QuestEN[48890] = { title = "How to Be a Blood Troll", description = "You will have to blend in if you don't want anyone getting suspicious. This won't be pretty.\n\nDere are drudges around de camp who have been tied up as part of a ritual. Dey get beaten as a test to make dem stronger.\n\nAny who fail de ritual are sacrificed. De ones who succeed are allowed to fight de Zandalari.\n\nIf you are going to blend in, you need to \"test\" dese drudges as part of de ritual. It's weird, but dat's how dey work.", objectives = "" }
WordHunterWoW_QuestEN[48894] = { title = "Trial of Truth", description = "Those within our temple have left their past lives behind. They devote themselves entirely to Akunda. \n\nDis final test is perhaps de most important. \n\nDis is de moment of truth. \n\nYou will speak your name, as you will be known from dis day forth.", objectives = "" }
WordHunterWoW_QuestEN[48895] = { title = "The Perfect Offering", description = "Dis offering is all dat I have to my name, but it wouldn't be right for me to use it for myself when I know your friend is in danger. \n\nShe saved my life, now I can save hers.\n\nTake de offering. Don't make me ask twice.", objectives = "" }
WordHunterWoW_QuestEN[48896] = { title = "Knowledge of the Past", description = "An old friend of mine came to de sands willingly to gain knowledge of de past. \n\nIf anyone can locate dis weapon, it would be Julwaba. \n\nLast I heard, she planned to excavate de ruins surrounding de great pyramid.", objectives = "" }
WordHunterWoW_QuestEN[48897] = { title = "The Bargain is Struck", description = "Now dat you have declared a patron loa for your time here in Zuldazar, you should inform de king of your decision.\n\nHe will appreciate dat you chose to follow de mighty Gonk.", objectives = "" }
WordHunterWoW_QuestEN[48898] = { title = "Lucky Charm", description = "My daddy would never admit it, but he's really superstitious. I don't think he'll ever feel safe on a horse unless he has a lucky charm!\n\nI heard about a fox somewhere around here that's been eating a lot of chickens, and escaping everybody trying to catch him. I bet he's really lucky! Maybe if you got his tail and gave it to my dad, he'd feel lucky too!", objectives = "" }
WordHunterWoW_QuestEN[48899] = { title = "Safety First", description = "The connection between horse and rider is fascinating to me, and I will never truly understand until I experience it.\n\nBut, well, you know... armor! How could I possibly even think to mount one of these beauties without some proper protection?\n\nI saw some waterfalls nearby. There must be shells near the banks of its pools! Would you entertain an old Tortollan by collecting some for his safety?", objectives = "" }
WordHunterWoW_QuestEN[48902] = { title = "Monstrous Energy", description = "Have you ever heard about eel juice? I don't know if it's safe for {race}s like you, but tortollans love it! It gives us a burst of energy, and puts a spring in the step of even the oldest tortollan.\n\nI saw some eels to the north of the estate when we were traveling. Can you go collect some of their venom for my dad?", objectives = "" }
WordHunterWoW_QuestEN[48903] = { title = "The Perfect Horse, of Course", description = "With all that you've collected for me... I guess it is time to mount, isn't it?\n\nHoo! I haven't felt such nerves for three hundred years! Would you mind assisting me in finding a suitable equine partner? I could not trust myself to make the decision alone!", objectives = "" }
WordHunterWoW_QuestEN[48904] = { title = "Take the Bait", description = "The bait... almost gone now... must catch...\n\nThe crabs... find them... get more...", objectives = "" }
WordHunterWoW_QuestEN[48905] = { title = "Unappreciated Scrolls", description = "Since you're here in Natha'vor, you might as well help out the rest of the pilgrimage with a problem.\n\nThese trolls have stolen several of our scrolls. Why they would, I have no idea, I doubt they're smart enough to even read.\n\nI want you to get them back. I'm not young anymore, I can't just be casting magic off the top of my head! \n\nEspecially healing magic... which I'm sure Shoak is going to need when you rescue his dumb shell.", objectives = "" }
WordHunterWoW_QuestEN[48909] = { title = "Noble Responsibilities", description = "From the state of this body, I would say a beast with formidable claws or fangs ravaged this camp. You say the trail leads westward? This camp usually houses more than one of Alanna's hunters. I wonder if they are tracking the beast down as well.\n\nHurry it up! I don't want to spend the day waiting around. Track our dangerous quarry!", objectives = "" }
WordHunterWoW_QuestEN[48910] = { title = "Supplying Krokuun", description = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.\n\nWhat say you, offworlder?", objectives = "" }
WordHunterWoW_QuestEN[48911] = { title = "Void Inoculation", description = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. \n\nWe can save more of my kin.", objectives = "" }
WordHunterWoW_QuestEN[48912] = { title = "Supplying the Antoran Campaign", description = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", objectives = "" }
WordHunterWoW_QuestEN[48913] = { title = "Monalite Deposit - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[48914] = { title = "Monalite Deposit - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
