WordHunterWoW_QuestEN[48929] = { title = "Sizing Up The Opposition", description = "No doubt your High Exarch will fret at the news that we lack the resources to assault Antorus. He is not used to believing his vaunted Army of the Light to be inadequate.\n\nHis pride is no concern of mine. While he plots a new strategy, I will bathe the ground in demon blood.\n\nGo. There is much to be done before we can achieve our final victory.", objectives = "" }
WordHunterWoW_QuestEN[48937] = { title = "Create Netherwalker's Portal Generator", description = "", objectives = "" }
WordHunterWoW_QuestEN[48939] = { title = "Show Me What You've Got", description = "It looks like you understand the basics. Now it's time to put everything together.\n\nHead for the ring. Once you hear the starting pistol, you will have one minute to score as high as possible.\n\nGnolls are worth one point. Run 'em through with the harpoon!\n\nIf you see a paper zeppelin, bag it with your bolas for fifty points!\n\nLeaping fences gives you style. Style gives you more points when you skewer gnolls or down zeppelins. It's super important, so don't forget to keep jumping fences!", objectives = "" }
WordHunterWoW_QuestEN[48941] = { title = "A Slight Detour", description = "If this coven is drawing its power from these ancient ruins, then I may just know of something that could help us fight back.\n\nMeet me at the first fork along the Highroad Pass. There is something there I want you to see.", objectives = "" }
WordHunterWoW_QuestEN[48942] = { title = "Yeti to Rumble", description = "It would seem that the guard have been lax in patrolling the Highroad Pass. The mountain yetis have taken advantage of their absence, and now lie directly in our path.\n\nI am no soldier, {class}, so I will need to ask that you take care of them while I try to sneak past.  If we can drive them off the road, at least it will make the pass safe again for travelers.", objectives = "" }
WordHunterWoW_QuestEN[48943] = { title = "Salvage Rights", description = "This poor trader was set upon by the yetis.  There's nothing we can do for him now, but we would be remiss to let his supplies be laid to waste by these brutes.\n\nSee if you can find any supplies worth salvaging. You can use Bella as a pack horse.\n\nDon't worry, she's a brave mare. She won't spook easily.", objectives = "" }
WordHunterWoW_QuestEN[48944] = { title = "Unlocking History", description = "I'm sure you're wondering why I've brought you here.  \n\nLocated somewhere inside this cottage is a hidden door. If we can find a way to access it, the answer to your questions, and possibly our survival against the coven, should lie beyond.\n\nHelp me search for it, {class}.", objectives = "" }
WordHunterWoW_QuestEN[48945] = { title = "The Ruins of Gol Var", description = "What lies beyond are more ruins, much like those the coven sought.  \n\nHowever, these ruins served a different purpose, one that established the legacy of House Waycrest thousands of years ago.\n\nLet us head inside, and I will explain.", objectives = "" }
WordHunterWoW_QuestEN[48946] = { title = "The Order of Embers", description = "The Order of Embers was the name given to those who took up these arms against the Drust. Using the tools and methods uncovered by the scholars, they were able to counter the Drust's magic, and ensure our victory in the war.\n\nIf the coven wants to use the Drust's magic against us, then we'll use the order's weapons against them.\n\nThe knowledge of the order rests here, but without a hand to wield it, it will do us no good. \n\nWill you be that hand, {class}? Will you revive the Order of Embers?", objectives = "" }
WordHunterWoW_QuestEN[48947] = { title = "Gol Koval", description = "A group of hunters went up into the hills awhile ago and we haven't heard back from them. \n\nMy niece is up there and it isn't like her to be out of touch for so long! Would you please find her?\n\nShe was headed towards Gol Koval.", objectives = "" }
WordHunterWoW_QuestEN[48948] = { title = "The North Pass Caverns", description = "Please, you must help!\n\nMy grandson got lost around the caves to the north, and I'm so afraid that the troggs might have got him!  \n\nMy husband went after him, but he's getting on in years, and I fear he imagines himself tougher than he really is.\n\nCould you help them? You should be able to catch up with Thaddeus along the northern road.", objectives = "" }
WordHunterWoW_QuestEN[48949] = { title = "Weeds of the Mire", description = "<Magura weakly opens her eyes as you approach.>\n\nHelp me... weak... can't heal...\n\n<Magura struggles to raise an arm to point towards a nearby plant.>\n\nGraveweed... help... more... please...", objectives = "" }
WordHunterWoW_QuestEN[48950] = { title = "Magura's Revenge", description = "Thank you, stranger.\n\nDa Graveweed, it dulls da pain for a little while but my injuries... they too great.\n\nI've not long remaining, but please grant me vengeance before death claims me.\n\nDa beast, Grukmire, ambushed me an left me for dead. Please, grant me my dying prayer and show me the head of the beast so that I may know it passes on before I do.", objectives = "" }
WordHunterWoW_QuestEN[48954] = { title = "Blood of a Titan", description = "<Before your eyes, a trickle of blood from the fallen titan Argus congeals into a flawless gemstone. Holding it in your palm, you sense an almost unfathomable power emanating from within... along with echoes of pain and sorrow.\n\nIt is the last remnant of a battle that should not have been winnable. An impossible achievement. Yet, as with all victories, this one came at tremendous cost.\n\nYou realize immediately to whom you must convey this prize.>", objectives = "" }
WordHunterWoW_QuestEN[48962] = { title = "Telogrus Rift", description = "Umbric and his blood elves were cast out of their home for their pursuit of understanding.\n\nI know the dangers of the void better than most. We should lend them our aid and ensure they don't do anything too foolhardy.\n\nThis rift will take us to their current location. I hope we are not too late to help them.", objectives = "" }
WordHunterWoW_QuestEN[48963] = { title = "Diversionary Tactics", description = "Our destination is that cottage up ahead. I know it doesn't look like much, but a great deal of history is hidden inside.\n\nFirst, though, we'll need to deal with that massive yeti camped just outside. I'd hate to ask it of you, but I'll need you to draw his attention so I can slip inside.\n\nOnce you've taken care of him, I'll meet you within.", objectives = "" }
WordHunterWoW_QuestEN[48965] = { title = "Settle the Score", description = "A year ago I lost my daughter to the largest boar in the forest.\n\nI have tracked him since, trading blows back and forth. But this time...\n\nLet's just say I don't have much time left.\n\nAll I wish for is vengeance. Please {class}, avenge us so that my soul can leave this plane and join my daughter, wherever she may be.", objectives = "" }
WordHunterWoW_QuestEN[48973] = { title = "Paragon of Argussian Reach", description = "Your allies among the Argussian Reach have requested your presence. They wish to reward you for your continued efforts on their behalf.", objectives = "" }
WordHunterWoW_QuestEN[48974] = { title = "Paragon of the Army of the Light", description = "Your allies in the Army of the Light would like to thank you for your continued support. They await you on the Vindicaar.", objectives = "" }
WordHunterWoW_QuestEN[48982] = { title = "Invasion Point: Aurinor", description = "", objectives = "" }
WordHunterWoW_QuestEN[48986] = { title = "Take the High Road", description = "Let us continue to Arom's Stand.  It will take some time to parse the knowledge of the tome and train more inquisitors for our cause.\n\nIf the order's weapons are as effective against the coven as they were against the Drust, we may stand a chance of rescuing my family and restoring this land to its former glory.\n\nI will make my way there on foot. Until we meet again, {class}.", objectives = "" }
WordHunterWoW_QuestEN[48987] = { title = "Valley of Sorrows", description = "Your friend's memories are gone. \n\nDat is Akunda's gift to us. He takes away our painful memories, but a lot more than dat has gone missing lately. \n\nI can't even remember what I had for breakfast, and it's getting worse by de day. \n\nSomething's not right. \n\nMeijani and I had a plan. We were going to do... something... in de Valley of Sorrows. It's where Akunda keeps de forgotten memories. \n\nIf you're looking for answers, finding Meijani is de best place to start.", objectives = "" }
WordHunterWoW_QuestEN[48988] = { title = "Memory Breach", description = "De memories of Akunda's followers rest within dis valley. \n\nMost are best left forgotten, but dey may be our only chance to find out what happened to Akunda. \n\nLook back upon de memories here. See if you can find any clues about what happened to our loa. \n\nBe warned. Dis task is not for de weak. What you witness in dese memories can't be unseen.", objectives = "" }
WordHunterWoW_QuestEN[48991] = { title = "Vile Infestation", description = "Redemption must be earned. \n\nWe do good works to show Akunda we are worthy of his blessing. \n\nDe ranishu are a plague upon these lands. Dey devour everything in sight, with no regard for taste or texture. \n\nIf dey go unchecked, those vile pests will eat their way straight to de temple.\n\nRid de mesa of their presence. Show Akunda you are worthy of his gift.", objectives = "" }
WordHunterWoW_QuestEN[48992] = { title = "Sacred Remains", description = "Dis area was once a lush jungle, home to many great and powerful thunder lizards.\n\nDe bones of those ancient and powerful creatures are still buried around de temple.\n\nGreat power lingers within those ancient remains... you will need such power to call upon Akunda.\n\nSearch de area and return to me with de ancient bones of de thunder lizards.", objectives = "" }
WordHunterWoW_QuestEN[48993] = { title = "Powerful Conductors", description = "Akunda offers us a chance to start anew. \n\nThrough a sacred ritual, de loa enters our mind and removes de memories dat cause us pain. \n\nIf you seek Akunda's blessing, den you must first prepare for de ritual. \n\nDe pests dat feed on de wildlife here have antennae dat are great conductors for magic. De larger, de better. \n\nTheir leader's antennae should do de trick. He's easily three times de size of de normal ranishu.", objectives = "" }
WordHunterWoW_QuestEN[48996] = { title = "Ending the Madness", description = "Akunda the Exalted is not who he seems. \n\nHe poisoned the eternal spring, sickening all who drank from it. Even I was not immune to his abhorrent alchemy.  \n\nNow he drains my power, abusing my gift to wipe the minds of all who might try to stop him. \n\nWe will not let him succeed. \n\nWhat little power I have left, I will lend to you. \n\nUse it to call the storm and end the madness that has taken over my temple.", objectives = "" }
WordHunterWoW_QuestEN[49001] = { title = "Inconvenient Spirits", description = "The sethrak have oppressed vulpera like me for countless generations.\n\nYou can't fight 'em. Trust me, {race}. My caravan tried.\n\nI took that beating as a lesson, and then I found a new pack to run with.\n\nHere, we keep our distance from the sethrak and scavenge ruins like this one for anything valuable we can use or trade.\n\nYou want in? We could use a fourth. This one's protected by nasty spirits that keep harassing us.\n\nTake them out and you're in.", objectives = "" }
WordHunterWoW_QuestEN[49002] = { title = "Forced Grounding", description = "<This is one of the spears that Faithless trappers use to pull pterrordaxes to the ground. It has a long chain attached to its base.\n\nWith good aim, you could use it to pull a Faithless pterrordax rider to the ground so you could fight them.>", objectives = "" }
WordHunterWoW_QuestEN[49003] = { title = "Vengeance From Above", description = "Emperor Korthek hides deep in his stolen temple below ground. We must create such chaos that he has no choice but to emerge to face us.\n\nThe vulpera riot is a good start, but it will not be enough. Alone, they are no match for the Faithless army.\n\nThankfully, they are not alone.\n\nWe will ride the mighty Rakjan through the skies. While you throw lightning bombs, I'll use my charged staff to blast the Faithless armies below.\n\nLet us hope that is enough to lure out Korthek. I am eager to finish this.", objectives = "" }
WordHunterWoW_QuestEN[49005] = { title = "Shattered and Broken", description = "Something is terribly wrong.\n\nUnwanted memories have been released from their magical confines. \n\nAkunda's power is supposed to keep dem sealed away...\n\nDe physical manifestation of our most haunting memories have no place in dis world. \n\nDey must be destroyed.", objectives = "" }
WordHunterWoW_QuestEN[49007] = { title = "Commander on Deck!", description = "<The device hums to life, ready to provide you with access to Squadron Commander Vishax's portal in the Antoran Wastes.>", objectives = "" }
WordHunterWoW_QuestEN[49014] = { title = "The Burning Throne", description = "The time has come, {name}, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.\n\nWe will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.\n\nAfter all you have done, it is fitting that you have the honor. Speak to Romuul and let us finish our mission.", objectives = "" }
WordHunterWoW_QuestEN[49015] = { title = "Antorus, the Burning Throne: The Death of a Titan", description = "There is no way to express the depth of my sorrow. My rage. What Sargeras has done...\n\nArgus, my home world, holds the soul of a titan. It has been twisted and corrupted beyond redemption, its power harnessed to fuel the Legion's infinite army.\n\nWe must do the impossible... breach the depths of Antorus and sever the Legion's connection to the world soul.\n\nPlease, {name}. End its pain, its suffering. In striking down the dark heart of Argus, we will defeat the Legion... and redeem the soul of my world.", objectives = "" }
WordHunterWoW_QuestEN[49027] = { title = "Targets of Opportunity: Terminus", description = "Those Legion ships are a problem, {name}.\n\nEven now they dock perilously close to the Vindicaar, threatening us with their presence.\n\nSometimes when fighting the Legion it is better to go straight to the top rather than thinning their numbers.\n\nGo to the shipyards of Terminus and slay their officers and commanders. That should rattle their forces and put them back on the defensive.", objectives = "" }
WordHunterWoW_QuestEN[49028] = { title = "A Sweater for Rupert", description = "The nights are cold in this area, and I am worried my poor dog will freeze to death. I wish to sew him a sweater, but I have no materials to make one with.\n\nI would pay anyone who brings me a pair of porcupine quills and four raccoon tails.\n\n-Kolta", objectives = "" }
WordHunterWoW_QuestEN[49029] = { title = "Invasion of Space", description = "We are on the Legion home world, but we must not let ourselves get caught unawares.\n\nThese invasion points can bolster their forces and ruin our plans. By defeating them on their territory we also damage their command and infrastructure.\n\nSlay the commanders and stop their invading forces. The fight to push the Legion back begins now!", objectives = "" }
WordHunterWoW_QuestEN[49030] = { title = "Fragments of the Abyss", description = "Our scouts have delivered a disturbing report, champion.\n\nSome of the more powerful creatures of the Void are carrying powerful crystals that augment their abilities. They now pose a greater threat than before, and we can no longer ignore them.\n\nFind these void-tainted monstrosities and take their crystals. We will find a way to dispose of them safely.", objectives = "" }
WordHunterWoW_QuestEN[49031] = { title = "Out With The Inquisitors", description = "Of all of the demons at the Legion's disposal, the inquisitors are some of the most terrible.\n\nEven feared by some of the lesser demons, these monsters delight in cruelty and torturing their captives.\n\nInquisitors revel in the terror they cause, but perhaps we can make that work to our advantage.\n\nFind the most powerful inquisitors you can and defeat them. Their deaths will not only improve the morale of our troops, but also send a message to their lesser forces.", objectives = "" }
WordHunterWoW_QuestEN[49032] = { title = "Antorus, the Burning Throne: Dark Passage", description = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.\n\nIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", objectives = "" }
WordHunterWoW_QuestEN[49036] = { title = "Best In Show", description = "Now that the troggs have been taken care of, let's get on with the real show!\n\nYou've more than proven yourself as a capable rider - ready to get back in the ring and go big?\n\nSee if you can beat three hundred points!", objectives = "" }
WordHunterWoW_QuestEN[49039] = { title = "The Start of a Monster Hunt", description = "This is the closest I've been to a dead body, how exciting! What do you think murdered him?\n\nRegardless, it is my duty to ensure the safety of individuals under my employ. With a combination of my wit and bravery, and your practical skills, we should be able to track it down.\n\nThis will be a tale for the ages!\n\nLet's start with looking around the camp, see if you can find any clues.", objectives = "" }
WordHunterWoW_QuestEN[49040] = { title = "Fond Farewells", description = "Dis is where we part ways, {name}.\n\nI'm going to take de name Akunda, and start a new life here. \n\nWhen you find Rakera, and I know you will, give her my thanks. \n\nShe saved my life, and I'm going to make sure to live a life dat was worth saving. \n\nIf you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", objectives = "" }
WordHunterWoW_QuestEN[49059] = { title = "The Bones of Xibala", description = "Our allies in the Explorers' League have alerted us to an exciting find. They have set up camp in the Xibala region of Zuldazar.\n\nMake your way to the camp and help them uncover anything that may advance our cause.", objectives = "" }
WordHunterWoW_QuestEN[49060] = { title = "Xibalan Ecology", description = "I want to take me boys out and really dig our picks in, but every scout I've sent into the ruins just came back half mauled to death.\n\nSome didn't come back at all.\n\nFrom what I can tell, the ruins are home to more'n just these spiky grass-eaters. Do you think you could be a peach an' thin their numbers a bit?\n\nI'd caution ye against tamperin' with the local ecology an' all, but in the interest of not gettin' eaten I think I'll let ye make the call.", objectives = "" }
WordHunterWoW_QuestEN[49064] = { title = "Torga, the Turtle Loa", description = "Name's Lashk.  We're not here to join any cause, we just want to hear Torga's legendary stories.\n\nI don't know if he'll help, but you can try persuading Torga, loa of the turtles, and see if he'll help you fight these blood trolls.\n\nYou can join on our pilgrimage to Torga, just keep quiet. Follow the path and find Kisha, she'll tell you where to go.", objectives = "" }
WordHunterWoW_QuestEN[49066] = { title = "Encase of Emergency", description = "The cliffs here are well known for the crystal clear ice which forms at their base, and even more so for the elementals that are responsible for such. The hunters in my lodge use shards from the primal bodies to keep their stock frozen for transport. \n\nMore importantly, think of how useful it could be for making and serving drinks!\n\nLet's see if we can't find some elementals and gather shards from them.", objectives = "" }
WordHunterWoW_QuestEN[49067] = { title = "Beseeching Bwonsamdi", description = "We must talk to Torga's spirit and find out what exactly happened here... and how we can stop it.\n\nHrm, you mentioned dat you are linked to Bwonsamdi now.\n\nIt is time to test dat link. We need Bwonsamdi to get us Torga's spirit.", objectives = "" }
WordHunterWoW_QuestEN[49069] = { title = "WANTED: Ol' Frostclaw", description = "Old Frostclaw has once again been spotted near the edge of the pass. Hunters in the area are advised to keep caution. This larger than average bear has killed four people to date, I'd hate for you to make it a fifth. \n\nAny individual who kills the beast will be rewarded, regardless of their occupation.\n\n-Alanna  \n\n<Below the huntmistress' signature is a child's drawing of a bear with the words \"Ol' Frostclaw\" above it.>", objectives = "" }
WordHunterWoW_QuestEN[49070] = { title = "Souls for the Death Loa", description = "Dere be blood trolls swarmin' all over dis place. Dey really be pickin' Torga clean, even eatin' his meat.\n\nDat be dark, even for me. \n\nDa souls of dese blood trolls be corrupted by eatin' a loa. Somethin' ya should be rememberin' for future reference.\n\nDese souls be worth a lot ta me, more dan just da normal souls of dese blood trolls. \n\nGet me da corrupted souls of dese blood trolls and I be callin' da spirit of Torga to ya.", objectives = "" }
WordHunterWoW_QuestEN[49071] = { title = "Dreadtick Combustion", description = "This whole thing is crazy, you know that? I don't think any story can top this one...\n\nBah! Do you hear that insufferable sound?\n\nIt's those stupid dreadticks sucking on Torga's meat. Makes my skin crawl! \n\nWhat? You can't hear it? Meh, trust me, they're around, and they need to be taken care of.\n\nHere, take this scroll. We've had to deal with these dumb insects in the past. Read it near them and it'll cause them to explode.", objectives = "" }
WordHunterWoW_QuestEN[49072] = { title = "Westward Noble", description = "While I am loath to involve you in this further, I don't have the men to afford an escort for Lord Kennings. If he gets hurt, we'll all be out of a job. Can you make sure he at least made it to the west camp?", objectives = "" }
WordHunterWoW_QuestEN[49073] = { title = "Ritualistic Denial", description = "I can't believe we're dealing with a death loa, a DEAD loa, and blood trolls. This isn't what I had planned today!\n\nLook, some of the other tortollans have said there are some blood rituals going on. They were spooked and started heading for the coast when they saw it.\n\nTake this scroll and read it near any blood rituals. It should cause it to disperse.\n\nBe careful with my scroll! It's old and they don't make them like they used to.", objectives = "" }
WordHunterWoW_QuestEN[49075] = { title = "Antorus, the Burning Throne: Dark Passage", description = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.\n\nIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", objectives = "" }
WordHunterWoW_QuestEN[49076] = { title = "Antorus, the Burning Throne: Dark Passage", description = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.\n\nIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", objectives = "" }
WordHunterWoW_QuestEN[49077] = { title = "Moments of Reflection", description = "<The crystal calls to you, resonating with sorcerous magic.\n\nAs you take hold of it, you hear the echo of a message left behind, a duty Illidan entrusted to you.>", objectives = "" }
WordHunterWoW_QuestEN[49078] = { title = "Poisoning the Brood", description = "Now we have room for our plan to kill Hir'eek. You see, {name}, my specialty is in making potions and poisons.\n\nI am working on a poison to use on Hir'eek, when de time comes. I have no idea if it will work or not.\n\nI want you to take what I already made and use it on de bats around here. It should kill dem instantly. \n\nIf it works, den I can make it stronger with my voodoo and give us a chance at killing Hir'eek.", objectives = "" }
WordHunterWoW_QuestEN[49079] = { title = "Hir'eek, the Bat Loa", description = "Hir'eek knows we are here. If my knowledge of Hir'eek is correct, he will personally kill us after we present ourselves.\n\nIt is time, den. You and I will walk out dere into a horde of blood trolls who want to watch their loa kill us.\n\nTake dis dagger. It is coated with de poison I made. I trust you to survive longer than me to use it.\n\nYou pretend to cower to Hir'eek, and I will do de talking. On my signal, you jump on Hir'eek and start stabbing!\n\n...And den we hope for de best.", objectives = "" }
WordHunterWoW_QuestEN[49080] = { title = "Cease all Summoning", description = "I feel something dark and powerful being summoned in de husk of Torga. You need to stop it!\n\nDere must be a summoner using Torga's blood to finish a ritual.\n\nDo what you can to stop dem. I will stay here to keep dese tortollans safe from de blood trolls.", objectives = "" }
WordHunterWoW_QuestEN[49081] = { title = "To Kill a Loa", description = "I am badly hurt... I don't think I can move. Don't worry, I have some potions dat can heal me... slowly.\n\nHir'eek is just down de cavern dere. De poison injured him, but he is a loa, and it will take more than dat to take him down.\n\nI can't believe we... YOU are going kill a loa. It's just not someting we do... but Hir'eek serves G'huun. We have no choice! \n\nIt's all up to you, now. Kill Hir'eek and end dis madness!", objectives = "" }
WordHunterWoW_QuestEN[49082] = { title = "Upward and Onward", description = "It is sad dat Hir'eek had to die, but at least de blood trolls are weaker now.\n\nMy potions are healing me up nicely. I did some looking around and came across dis guy.\n\nHe's skittish, but not hostile. I think you can use him to get out of here.\n\nHurry up and jump on, before he breaks de rope! I'll find my own way out; you don't have to worry.", objectives = "" }
WordHunterWoW_QuestEN[49091] = { title = "Invasion Point: Val", description = "", objectives = "" }
WordHunterWoW_QuestEN[49096] = { title = "Invasion Point: Naigtal", description = "", objectives = "" }
WordHunterWoW_QuestEN[49097] = { title = "Invasion Point: Sangua", description = "", objectives = "" }
WordHunterWoW_QuestEN[49098] = { title = "Invasion Point: Cen'gar", description = "", objectives = "" }
WordHunterWoW_QuestEN[49099] = { title = "Invasion Point: Bonich", description = "", objectives = "" }
WordHunterWoW_QuestEN[49120] = { title = "Speaking with the Dead", description = "Ya be livin' up ta ya part of da bargain. I be ready ta show ya what remains of Torga's soul. \n\nI gonna need a little part of ya ta act as a conduit ta be summonin' Torga. Don't worry, I be givin' ya all back.\n\nMostly.\n\nAfter we be done, I be headin' out. Ya always welcome ta call on me again... but only if ya got another deal ready.", objectives = "" }
WordHunterWoW_QuestEN[49122] = { title = "A Port in Peril", description = "A group of mogu have taken hold of Warport Rastari and now threaten to encroach further into my city.\n\nIt would seem Zul is losing his grip over his pets. \n\nDat port is vital to our military fleet. If de brutes succeed, Zuldazar will fall, and dere won't be a fleet to aid your precious Horde.\n\nYou wish to prove yourself an ally of de Zandalari? Meet my blade and shield at de port and clean up dis mess.", objectives = "" }
WordHunterWoW_QuestEN[49123] = { title = "Killer Crawgs", description = "You heard Torga. We need to be taking de fight to de blood trolls if we want to stop dis herald of G'huun.\n\nDe blood trolls have monstrous crawgs in a camp nearby. We destroy dem, we weaken de blood trolls! \n\nDe rest of us will move ahead to find out what else de blood trolls have planned around dis place.", objectives = "" }
WordHunterWoW_QuestEN[49124] = { title = "Tortollan Rescue", description = "If Torga wants us to help you kill the herald of G'huun, then I guess we'll help. First, we need to rescue our people.\n\nI found out that the blood trolls are draining the blood of our friends nearby and then feeding them to crawgs! \n\nThis is no way for a tortollan to die, not after hundred of years gathering stories on Azeroth. \n\nTake this scroll. It'll purge whatever blood magic the blood trolls using on my friends.\n\nBe careful with my scroll! I want it back in one piece.", objectives = "" }
WordHunterWoW_QuestEN[49125] = { title = "Negative Blood", description = "Okay, you want to kill the herald of a blood god? We can figure something out.\n\nThere's corrupted blood nearby that's feeding this monster's power. Lucky for you, I've heard stories of this sort of thing before.\n\nTake this scroll, but be careful with it! It'll destroy the corrupted blood that's feeding Jungo.\n\nOh, and I need you to find a scroll Holbruk was carrying, called the Scroll of Fate's Hand. It's REALLY powerful. We'll need it.", objectives = "" }
WordHunterWoW_QuestEN[49126] = { title = "Forcing Fate's Hand", description = "I got some good news and bad news for you about this whole quest to destroy the herald of G'huun. Bad news first.\n\nThere's an entire army of skeletons between us and the next area. I'm guessing they used Torga's blood to animate them.\n\nGood news is that scroll you recovered from Holbruk can summon the powerful Hand of Fate.\n\n...and the bad news is that the scroll got damaged when Holbruk died and is only good for one more use.\n\nMeh. Take this scroll and destroy that skeleton army!", objectives = "" }
WordHunterWoW_QuestEN[49130] = { title = "Loa-Free Diet", description = "Princess Talanji thinks we're almost ready to kill this herald of G'huun. Maybe she's right, maybe we're all dead, who knows?\n\nWhat I do know is the blood trolls here are... are carving and carrying away parts of Torga. Ugh!\n\nFrom what I can tell, they're using poor Torga's meat to power their blood rituals. This has to stop!\n\nGo out there and steal those pieces of meat from the blood trolls. I'll figure out a way to dispose of it.", objectives = "" }
WordHunterWoW_QuestEN[49131] = { title = "Sanctifying Ground", description = "We are so close to weakening dis herald, {name}. Dis is our final push. De nearby area is brimming with blood magic.\n\nWhile you were fighting, I was working on creating totems dat can cleanse de area of blood magic.\n\nTake dese totems and place dem nearby. Dey should drain some of de blood magic out of de area.\n\nDe herald should be weak enough for us to actually kill after all dis.", objectives = "" }
WordHunterWoW_QuestEN[49132] = { title = "Crushing the Skullcrushers", description = "Look, {name}, I'll be happy once we've killed this herald and we can have things go back to normal.\n\nUntil then, you need to deal with these monstrous blood trolls called \"skullcrushers\". Lovely, right?\n\nAs far as I can tell, these things have some sort of connection to this herald, might be why they're so huge.\n\nYou kill these skullcrushers and maybe we weaken this herald a bit more. Or maybe it gets even angrier and kills us all. \n\nWe'll have to see.", objectives = "" }
WordHunterWoW_QuestEN[49133] = { title = "Antorus, the Burning Throne: The Heart of Argus", description = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance.\n\nIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", objectives = "" }
WordHunterWoW_QuestEN[49134] = { title = "Antorus, the Burning Throne: The Heart of Argus", description = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance.\n\nIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", objectives = "" }
WordHunterWoW_QuestEN[49135] = { title = "Antorus, the Burning Throne: The Heart of Argus", description = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance.\n\nIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", objectives = "" }
WordHunterWoW_QuestEN[49136] = { title = "Jungo, Herald of G'huun", description = "Dis is it, {name}. De blood magic is weakened enough dat we can actually hurt de herald of G'huun.\n\nIt is going to take all of us fighting dis thing to stop it. We will meet you inside of Torga. \n\nWe cannot lose here. If de blood trolls control Torga's blood, den dere will be no way for us to stop dem.", objectives = "" }
WordHunterWoW_QuestEN[49138] = { title = "Captain Gulnaku's Treasure", description = "<This map is poorly drawn and covered in stains, but appears to identify three possible locations where a pirate captain may have buried treasure around the Port of Zem'lan. The treasure could be at any of the three locations.\n\nAt the bottom of the map, someone scrawled an order: Set traps!>", objectives = "" }
WordHunterWoW_QuestEN[49139] = { title = "An Army's Arsenal", description = "It's my job to scout out the ruins to identify threats and figure out the best way in.\n\nTwo storehouses contain the majority of the valuable weaponry in the ruins.\n\nUnfortunately, they're guarded by specters, powerful Zandalari spirits bound to this place.\n\nI... we need those weapons. Take out the specters so I... we can get to them.", objectives = "" }
WordHunterWoW_QuestEN[49141] = { title = "Diplomacy and Dominance", description = "May I entrust you with my staff, {name}? I do not offer this lightly, so do not accept it lightly either.\n\nWe will need every advantage when we face Emperor Korthek, and I've identified an opportunity to increase the power at our disposal.\n\nThe Faithless maintain a series of suppression spires on the ridge above us to subjugate the pterrordax. My staff can drain power from the spires to bolster its own potency.\n\nMeanwhile, I will recruit a much-needed ally for the next stage of our mission.", objectives = "" }
WordHunterWoW_QuestEN[49143] = { title = "Essence of the Light Mother", description = "This is a crucial moment, {name}. Our campaign must not lose momentum.\n\nThough she has fallen, I still sense Xe'ra's presence all around us. The Light that shone within her heart can yet be a source of strength for our cause.\n\nNo doubt the loss of Xe'ra has deeply wounded Turalyon. I will do what I can to ease his troubled spirit while you gather the vestiges of the naaru that remain.", objectives = "" }
WordHunterWoW_QuestEN[49144] = { title = "Wrath of the Zandalari", description = "Dere is no reasoning with de mogu. Dey only value one thing: strength.\n\nDat is something de Zandalari have like no other, but our forces are spread thin. We are simply not prepared to fight dem.\n\nYou have proven yourself a capable warrior, for a {race}. Would you be our \"ambassador\" to dese brutes? Show dem dat de Zandalari do not stand alone!", objectives = "" }
WordHunterWoW_QuestEN[49145] = { title = "No Troll Left Behind", description = "Dis is de primary port for de Zandalari fleet. Thankfully most of our ships were out when de mogu came, but Rastari is still an active fortification for de city.\n\nDe mogu did not land on abandoned shores, {class}. Dere are all manner of brave warriors stationed here, fighting for their lives.\n\nTake dis whistle and rally all you can. Our warriors will hear its scream and know dat dey are not alone.", objectives = "" }
WordHunterWoW_QuestEN[49146] = { title = "Spirits' Belongings", description = "You are no Zandalari, but your spirit burns with a passion I have not seen in many years.\n\nI am de wavebinder. It is through me dat de loa bless our ships. I will not see my home tainted by dese talking rocks.\n\nGather my bijous, my grimoire, and some of our fallen I set aside for just such an occasion.\n\nDe brutes think dey have won. Dey will answer to Bwonsamdi soon enough.", objectives = "" }
WordHunterWoW_QuestEN[49147] = { title = "Show of Strength", description = "Their leader's time is coming soon now, but we need to dispose of his lieutenants first. Our momentum will be lost if dey reform ranks.\n\nJao-Ti is de first. Legend has it Lei Shen himself said he showed a great connection to de storms. He is leading de mogu's stormbinders.\n\nDe other is Subjugator Zheng, a slaver dat would make de Kul Tirans blush. You have never seen depravity like his.\n\nKill dem both, and make dem suffer. De mogu are no strangers to war, but neither are we.", objectives = "" }
WordHunterWoW_QuestEN[49148] = { title = "Crumbling Apart", description = "De mogu army grows with each passing moment thanks to their animated stone warriors. It is only a matter of time before their forces are back at full strength.\n\nA thousand curses upon Zul. He was forbidden from bringing his pets here--and from resurrecting de Thunder King in Pandaria.\n\nWe are de only thing standing between dem and de city. We've got to stop dis while we still can!", objectives = "" }
WordHunterWoW_QuestEN[49149] = { title = "Embrace the Voodoo", description = "Dese heathens think we are weak. Dey think we are broken.\n\nBut Zandalari never truly die.\n\nI've blessed dat skull Habutu gave you with a bit of voodoo dat will let it break through to de Other Side. You will need to use my spirit obelisks to channel its power. Dey will take it from dere.", objectives = "" }
WordHunterWoW_QuestEN[49160] = { title = "Torga's Eternal Return", description = "Well, we did it. Doesn't make the plan we had any less crazy. But there's still one more thing left to do.\n\nI've been visiting Torga for years. He told me stories of powerful scrolls, one in particular that he said was meant to be used to put a loa's spirit to rest.\n\nI think you should be the one to read it. I mean, if you're SMART enough to read it. \n\nBah! Just take the scroll and read it before I have second thoughts.", objectives = "" }
WordHunterWoW_QuestEN[49178] = { title = "My Favorite Things", description = "It's tough out here.\n\nPirates. Deadly monsters. \n\nHungry Sam's seemingly endless battle with indigestion.\n\nNothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going.\n\nAsk around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture.\n\nMe? Oh... I had a locket... \n\nNever mind, it's too small, you'd never find it. It's nothing. Don't worry about it.", objectives = "" }
WordHunterWoW_QuestEN[49181] = { title = "Glimmering Locket", description = "<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design.\n\nOpening the locket reveals a hand-drawn picture of a woman with fiery red bangs. \n\nHer arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>", objectives = "" }
WordHunterWoW_QuestEN[49185] = { title = "Catching Up", description = "Good to see you in one piece, {name}. Nazmir is a place of nightmares, but you seem to be surviving.\n\nRokhan and I convinced your Horde dat we need more support. He is getting ready to meet with reinforcements.\n\nWe still need to get de loa's aid. What happened with Bwonsamdi and Hir'eek?", objectives = "" }
WordHunterWoW_QuestEN[49195] = { title = "Greater Invasion Point: Occularus", description = "", objectives = "" }
WordHunterWoW_QuestEN[49196] = { title = "Greater Invasion Point: Pit Lord Vilemus", description = "", objectives = "" }
WordHunterWoW_QuestEN[49197] = { title = "Greater Invasion Point: Sotanathor", description = "", objectives = "" }
WordHunterWoW_QuestEN[49198] = { title = "Greater Invasion Point: Inquisitor Meto", description = "", objectives = "" }
WordHunterWoW_QuestEN[49199] = { title = "Greater Invasion Point: Matron Folnuna", description = "", objectives = "" }
WordHunterWoW_QuestEN[49218] = { title = "The Castaways", description = "I see the sirens have made another catch. You're lucky they haven't stripped your bones yet.\n\nIf you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me.\n\nEveryone there washed up in the tides, just like you. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive.\n\nTalk to Stabby Jane. Don't worry about her nickname, she's actually real nice.", objectives = "" }
WordHunterWoW_QuestEN[49223] = { title = "The Long Con", description = "Hello again my young friend! I have good news.\n\nOur mutual acquaintance Carentan -- the man who scammed us in Freehold -- has finally come out of hiding.\n\nI have been communicating with him in letters delivered by various middlemen and even completed a few proxy trades to earn his trust. In our last correspondence, he agreed to meet for an in-person trade.\n\nHe thinks he is meeting with a Ms. Pixy Spindlespark, gnomish hairdresser with a weakness for poached furs.\n\nBut he'll be meeting you instead.", objectives = "" }
WordHunterWoW_QuestEN[49224] = { title = "The Netherlight Crucible", description = "The crucible thrums with power. Soon our weapons will shine like the stars themselves!\n\nWe will need that strength if we are to have any hope of defeating the Legion here.\n\n{name}, you have endured great hardship to bring us to this moment. The honor of first tapping the crucible's power must be yours.", objectives = "" }
WordHunterWoW_QuestEN[49225] = { title = "Chasing the Leader", description = "The locals and the league have been working together tae reclaim relics in this here cave up the hill. But it seems that we've angered the previous residents. I think the marines can keep the expedition safe fer now, but I dinna how long they can keep it up. \n\nWe need yer help before things go south! Find Hilde Firebreaker, the leader of our expedition. She ran back into the cave fer somethin' or another.", objectives = "" }
WordHunterWoW_QuestEN[49226] = { title = "Silencing the Sisters", description = "The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk.\n\nBut you can't very well kill all of them. Only a fool would try that.\n\nThe real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\"\n\nI managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.", objectives = "" }
WordHunterWoW_QuestEN[49227] = { title = "The Master Key", description = "None of the keys you found were the right fit! We're going to need another plan...\n\nI've heard that Overseer Morrison has a master key that can open any lock in the compound. It's dangerous, but I need you to get that key for me!\n\nYou'll find her running the mining operation inside the cave. Once you get the key, make sure you rescue any vulpera captives that you find.\n\nOnce you've rescued my friends, meet me back here and release me. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[49229] = { title = "The Ruins Fought Back", description = "Something set off a trap in the cave, and then the ruins themselves came tae life. I expect that most of our lads still in that cave aren't in fightin' form.\n\nCould ye clear out some of the livin' ruins tae help them escape?", objectives = "" }
WordHunterWoW_QuestEN[49230] = { title = "Local Flavor", description = "I'm STARVING.\n\nNot actually starving, like when I first got here, but you know... Emotionally starving.\n\nHaven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks.\n\nHow about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice.\n\nCan you get me some? I'm not much of a hunter. But I'll share it with you!", objectives = "" }
WordHunterWoW_QuestEN[49232] = { title = "Salvaging a Disaster", description = "Birch and I are helping out the expedition with field studies. I'm not much of a fighter, but I can't make another mistake, they might demote me!\n\nCould you recover some of the relics we packed up in boxes around the cave?", objectives = "" }
WordHunterWoW_QuestEN[49233] = { title = "I'm a Druid, Not a Priest", description = "The remains of previous trespassers also arose when we set off the main trap.\n\nCranklefuse here has been demanding that I help them, and while I can't say I'm too familiar with turning the undead, I believe I have found a solution.\n\nI've modified my staff to remove their curse. Take it and see if you can't help them.", objectives = "" }
WordHunterWoW_QuestEN[49234] = { title = "A Marine Out of Water", description = "A giant one of those stone creatures killed quite a few marines while we were trying to evacuate the cave. It didn't chase us too far, but ignoring it outright is too big of a risk.\n\nIt needs to fall!", objectives = "" }
WordHunterWoW_QuestEN[49239] = { title = "Dress to Impress", description = "Freehold used to be open to anyone, but now it seems the Irontide Raiders have declared themselves the owners. They're locking the place down and turning away anyone who isn't part of the crew.\n\nFortunately, they're also hiring.\n\nPut this on. Don't think about where it came from.\n\nWe'll pose as new recruits, get in, gather some information, and be back in Boralus in time for supper! Cyrus may be salty, but he's a decent cook.", objectives = "" }
WordHunterWoW_QuestEN[49242] = { title = "Quill or Be Quilled", description = "Oh, hello there. Sorry, we don't get many mainlanders in these parts.\n\nThis plot was my husband Sam's farm. He used to tend to the onion fields every day before the curse befell Glenbrook and took him with it.\n\nWith my husband gone, this farm is all I have left, and these quillrats are making sure I don't get even that.\n\nI'd hate to bother a perfect stranger, but could you help quell this infestation?", objectives = "" }
WordHunterWoW_QuestEN[49259] = { title = "And Justice For All", description = "Thank you for helping to redeem me in the eyes of my people, {class}. I am in your debt, and I will be sure to let my father know.\n\nIn the mean time, I think we should find out what this Heartsbane Coven is, and what they are doing in our lands. I hope the marshal will be able to enlighten us.\n\nFirst thing's first, though. Care to undo these ropes? They're starting to chafe.", objectives = "" }
WordHunterWoW_QuestEN[49260] = { title = "Backup While I Pack Up", description = "I came in here tae try an' reclaim as many relics as possible. Sneakin' in was easy, but I'm worried about things noticin' me while I pack up. \n\nMind watching me back while I get the relics stored in a safe place in my bag?", objectives = "" }
WordHunterWoW_QuestEN[49261] = { title = "Crabby Crew Stew", description = "Shouldn't you be in the mines? Look, I won't tell Morrison if you won't. I wouldn't want to be stuck in those mines, either. \n\nWe could use a hand out here, though. The crew is getting crabby. We've been eating nothing but slop and the occasional rat for weeks. \n\nI hear one of the deckhands makes a marvelous crab stew. Can I count on you to secure the meat?", objectives = "" }
WordHunterWoW_QuestEN[49262] = { title = "Gang Bustin'", description = "It's difficult to run a tight ship when you're so far from home. The crew has a tendency to get restless when they've been landlocked for too long.\n\nI've heard reports of deckhands sneakin' around and stealin' supplies. If the crew thinks they can steal from our employer on my watch, they've got another thing comin'!\n\nI need someone to crack down on these shady deals and send a message to the crew.\n\nThievin' won't be tolerated!", objectives = "" }
WordHunterWoW_QuestEN[49266] = { title = "Forge of Aeons", description = "The Lightforged have long stood as a beacon of hope against the Legion.\n\nBut few truly know what it takes to become the embodiment of Light's wrath.\n\nThese few champions among the Army of the Light are ready to undergo their final trial.\n\nWill you do us the honor of bearing witness?", objectives = "" }
WordHunterWoW_QuestEN[49268] = { title = "Sharks in the Water", description = "Recently a large gam of sharks has moved into the shallower water in the harbor. I have dealt with minor illnesses before that were caused by creatures carrying foreign contaminants to shore.\n\nPerhaps the sharks have brought something in from the deeper waters? Cull some of the sharks that have wandered too close to the pier. I shall read the tides for any changes.", objectives = "" }
WordHunterWoW_QuestEN[49274] = { title = "Morgrum's Survey", description = "Oi. Since yer hands are already dirty, what do ye say we make a deal?\n\nTo give it to ye straight, there's a relic here called the Breath of Xibala. I don't know who Xibala is or why the Alliance wants its breath, but there's a hefty sum of gold in it fer me if we deliver.\n\nThat means there's somethin' in it for you, too, if ye get my meanin'.\n\nI started a survey with me equipment but haven't got me results yet. Go on out into the ruins an' give the boxes you see a little kick to hurry things along.", objectives = "" }
WordHunterWoW_QuestEN[49276] = { title = "The Thrill of Exploration", description = "Name's Acadia, Acadia Chistlestone!\n\nI represent the interests of the Explorers' League at this site. Where there's dirt to be turned, we're happy to do the digging!\n\n<Acadia's smile falters.>\n\nThese Dark Iron, though, they're keen on delving deeper and faster than I'm comfortable with. Since you're a strong, capable member of the Alliance, do you think you could ah... lead by example?\n\nGo on, there's a fresh fossil here that could use some attention.", objectives = "" }
WordHunterWoW_QuestEN[49278] = { title = "Spiritual Restoration", description = "Dis is a sacred place to Bwonsamdi, but now it is little more than a ruin. Even de spirits are unable to escape de passage of time and have faded away, leaving only their drained husks behind.\n\nWe will return dem to life.\n\nHere, I have been collecting de souls from my hunt into dis charm. Use it on de drained spirits, and we will bring dis place back to what it once was.", objectives = "" }
WordHunterWoW_QuestEN[49282] = { title = "Morgrum's Extended Survey", description = "I've looked over the readings my little boxes gave an' I think I know where to look next. The Ashes of Xibala are practically mine.\n\nYe'll want to meet me in the middle of the ruins, under that big ol' leerin' skull on the mountainside, to continue my survey.\n\nReadin' these contraptions is hard work, an' I don't think we'll be alone up there.\n\nThink ye can watch me back?", objectives = "" }
WordHunterWoW_QuestEN[49283] = { title = "Who Seeks the Seekers?", description = "Let me tell you, Zandalar is filled to the brim with ancient secrets. It's quite fascinating.\n\nWe heard tales of a region, to the southeast, where ships were losing their way. Some even vanished!\n\nRaku, along with a team of particularly curious Seekers, has been exploring a cove near there for some time. Shipwrecks and mysteries, what isn't to like?\n\nWe should have heard back by now. We tortollans may not be fast, but we are reliable.\n\nWill you check on them, and make sure they are well?", objectives = "" }
WordHunterWoW_QuestEN[49284] = { title = "Perfect Tidings", description = "Your timing is most convenient, {class}.\n\nOur team had a check-in planned for this place, two days past. None have yet returned. \n\nI did not want to be brash and send word to the city too soon. However, I cannot leave this place empty, nor can I abandon young Koba. \n\nTake this scroll. See who, or what, you can find. Bring back those you can.", objectives = "" }
WordHunterWoW_QuestEN[49285] = { title = "Tiny Treasures", description = "My adults are in the field doing some research. So I stay here, patiently waiting, as they told me to do.\n\nThese monsters came and took my special treasures! They took my best friend in the whole world, my slug, Spitzy!\n\nThey took them all. They ran far. I do not move fast...\n\nCould you please get them back, and find my family?", objectives = "" }
WordHunterWoW_QuestEN[49286] = { title = "Caged Wisdom", description = "Oh, hello, friend. \n\nIt seems there is more here than for what we prepared.  \n\nWe sought. We found. We studied... and then we were taken. There are naga here. We did not expect this.\n\nThere is a nasty fellow in this cave. If you could get the key from him, it would help us greatly.\n\nNo need to fret, we'll wait here.", objectives = "" }
WordHunterWoW_QuestEN[49287] = { title = "Lost Chelonians", description = "Tidemistress Nazesh has been channeling on a rock they found in one of the pools above. She has been trying for days. They grow desperate.\n\nThe rest of my team was taken and locked up in cages. They want secrets from us that we do not know.\n\nWhen they realize we tortollan cannot be coerced, I expect the naga will do something most dire.\n\nRelease the Seekers. We will thwart the naga plans together.", objectives = "" }
WordHunterWoW_QuestEN[49288] = { title = "Scrollhunters", description = "When they captured us, they took everything we had - including our wonderful scrolls!\n\nThose naga witches are building storms. They try to hide what they do here, and seek power for their queen. \n\nWe see past their madness, they are driven for a purpose.\n\nRetrieve our work from the Nazeshi Tempest-Wielders, else they may use them for nefarious gains.", objectives = "" }
WordHunterWoW_QuestEN[49289] = { title = "A Special Stone", description = "Tidemistress Nazesh is right up this hill, {name}. \n\nThere is something there. Something Azshara wants very badly.\n\nThe naga must not succeed. If you can get a little piece of that stone, though, bring it back for us.\n\nTake this scroll with you, it will help you in your fight.\n\nIt is time we push her forces, back into the waves for good.", objectives = "" }
WordHunterWoW_QuestEN[49290] = { title = "Aged to Perfection", description = "Greetings, young one. I am Roko. I trade in specialty goods and exotic wares.\n\n<Roko pulls a small wooden cask from beneath his shell.>\n\nThis bourbon is one hundred years old. I know, because I bought it one hundred years ago.\n\nA man in Freehold is prepared to trade me a rare scroll for this, but alas I am barred from entering. It seems this town is not so \"free\" anymore.\n\nIf you can get in, perhaps you could make the trade on my behalf? I would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[49292] = { title = "Algae Shakes", description = "Now that I have properly developed my tonic, it is of utmost importance that we dispense it amongst the ill at once.\n\nPlease, take this tankard and distribute the remedy to the sick. I will try to calm the rest.", objectives = "" }
WordHunterWoW_QuestEN[49293] = { title = "Invasion Onslaught", description = "We must not yield even a single world to the Legion. Continue our Invasion Point offensive and crush the Legion beneath your heel.", objectives = "" }
WordHunterWoW_QuestEN[49295] = { title = "Clear-Cutting", description = "We've managed to hold this hill, but the wicker creatures have moved in to surround us.   \n\nWe're not going to be able to move into the town if we don't get them off our flanks. This is where you come in, {class}.\n\nSee if you can clear out some of their numbers in the lumber fields. That way, when we move in, we only need to worry about one front.", objectives = "" }
WordHunterWoW_QuestEN[49299] = { title = "Enemy Within", description = "I won't sugarcoat it, kid. It's a madhouse here.\n\nThe leadership has fallen, selling their own souls as well as the souls of the workers to some darker forces.\n\nI will not give in.\n\nOverseer Bates surrendered the guard in his hunger for power. Show him that he is a fool.", objectives = "" }
WordHunterWoW_QuestEN[49302] = { title = "The Deadliest Catch", description = "Oi! No time to waste!\n\nSeems Deepwarden had one more thing up his sleeve... and it's the catch of the day!\n\nThis'll be a hunt for the ages, and I won't let ya miss out.\n\nOkri will fly you out to the wall. Get ready!", objectives = "" }
WordHunterWoW_QuestEN[49309] = { title = "Thunder's Fall", description = "Warlord Kao commands de mogu from dis warship. It is time to put an end to dis incursion.\n\nI should be able to hold off any stragglers dat may come to Kao's aid, but I can only maintain dis barrier for so long.\n\nBe careful. Kao was one of de Thunder King's top generals. He will not fall without a fight.", objectives = "" }
WordHunterWoW_QuestEN[49310] = { title = "The Prophet's Ploy", description = "King Rastakhan's life is in grave danger. Zul is far more powerful than he appears.\n\nWe do not have much time. You have to warn de king before Zul can act.\n\nHabutu and Zolani can take you dere. Now go!", objectives = "" }
WordHunterWoW_QuestEN[49314] = { title = "Hunting Zardrax", description = "{name}, maybe you be helpin' me wit' sometin'.\n\nTalanji said dat Shadow Hunter Da'jul and her retainer, Kal'dran, ran off ta hunt down a lich named Zardrax.\n\nThey be goin' off ta a place called Burial Mound. I be worried dey be in over dere heads.\n\nCan ya check ta see if dey be needin' help? We can't be losin' any of our allies in dis place.", objectives = "" }
WordHunterWoW_QuestEN[49327] = { title = "Push Them Back!", description = "The faithless are laying siege to our home. \n\nThis isn't the first time they've attacked, nor will it be the last, but we must protect the temple!\n\nDo whatever you can to disrupt their siege and push them back.", objectives = "" }
WordHunterWoW_QuestEN[49333] = { title = "Building Our Arsenal", description = "Our fight against the faithless is an uphill battle we're bound to lose. We are outnumbered and out armed. \n\nWhat few weapons we have aren't enough to outfit the entire temple. \n\nWith a few more spears and daggers, we might stand a chance fighting them off until our loa can be returned to us.", objectives = "" }
WordHunterWoW_QuestEN[49334] = { title = "A Powerful Prisoner", description = "It appears the Faithless broke through our defenses while I was away. \n\nThey must be after Vorrik's key. It's the only reason they would have taken him alive. \n\nPlease, {name}. You must secure our leader's safe return.", objectives = "" }
WordHunterWoW_QuestEN[49335] = { title = "Skycaller Slaughter", description = "Some among the faithless are gifted with the ability to command the storm. They call themselves skycallers, and they use their magic to summon great spires that turn the earth into sand.\n\nSkycallers are the only ones capable of summoning these spires. If you kill the skycallers, you also kill the sethrak's ability to expand their warcamps.", objectives = "" }
WordHunterWoW_QuestEN[49340] = { title = "The Keepers' Keys", description = "Serrik mentioned you might have uncovered something of significance at Zul'Ahjin?\n\nWe don't have much time, I'm afraid.\n\nWhat is it you have found?", objectives = "" }
WordHunterWoW_QuestEN[49348] = { title = "A Desecrated Temple", description = "Da spirits of da faithful flock ta me temple. Ya see dem out dere, yes? \n\nDey come ta enter da Other Side an' join me realm. However, spirits who've turned their backs upon Bwonsamdi, dey too have come to me temple grounds. Dey praise one called \"G'huun,\" and spread their blood magic desecration across da Necropolis.\n\nDis ends now!\n\nGo out dere and remove da desecrations dat be infesting me temple.", objectives = "" }
WordHunterWoW_QuestEN[49354] = { title = "Remember the Sunwell", description = "The Regent Lord intends to show First Arcanist Thalyssra our Sunwell.\n\nI do not know if he will allow Alleria Windrunner to attend the meeting, but we are invited to join them.", objectives = "" }
WordHunterWoW_QuestEN[49366] = { title = "Aid the Wounded", description = "<This Zandalari appears to be barely holding on.\n\nThere is a broken dart lying on the ground next to him. He appears to have dropped this bottle before he collapsed.\n\nYou grab the vial. Could it be some kind of antidote?>", objectives = "" }
WordHunterWoW_QuestEN[49370] = { title = "Rescue the Chronicler", description = "Just ahead, Chronicler Jabari is being held in a cage, waiting to become a sacrifice.\n\nOne by one, I see dem taken away, I hear de screams. Blood drained to feed blood magic, and what was left... was food for a beast.\n\nHe is de only one left, and I don't have de strength to save him yet.\n\nGet Jabari out of dere, so we can return to Princess Talanji.", objectives = "" }
WordHunterWoW_QuestEN[49376] = { title = "Just One Thing", description = "You are just in time! Chance be high dat my blood was de next to spill.\n\nIt is my fault we stopped here. Our team wanted to head back.\n\nCrawgs are de trouble, you see. De sanguinous birth of dese young be corrupted by cruel training. They are quite impressionable and dey will follow with just a little enticement.\n\nCapture the attention of one of de little squirmy ones nearby. We will see if my theory is correct.", objectives = "" }
WordHunterWoW_QuestEN[49377] = { title = "Off With Her Head", description = "Warmother Nagla is driving her forces with a brutality and strength we did not expect. \n\nBlood trolls desecrate all dey touch, and are preparing to wreak havoc on all dat remain. \n\nAs dey say, \"cut off de head, and de beast will be dead\". \n\nI will have her head as a trophy to show dat our brothers were avenged!", objectives = "" }
WordHunterWoW_QuestEN[49378] = { title = "Earn Their Trust", description = "If de young one can be taught to trust, dere is a chance for dis species.\n\nDey may have been born of bad blood, but is dat what makes dem monsters? If you can build his confidence, a mighty ally he could one day be.\n\nA little care could be de thing, and don't forget food! I think some blood trolls may be extra tasty.", objectives = "" }
WordHunterWoW_QuestEN[49379] = { title = "Crawg Free Zone", description = "Crawgs dat have been battle trained are already set in their ways.\n\nCleansing dem from de camp may be de only way to give de young ones a chance.", objectives = "" }
WordHunterWoW_QuestEN[49380] = { title = "Bad Juju", description = "Look, between you and me, dere is no way we will drag my friend outta here without what got us into dis mess.\n\nWe saw three orbs in dis camp. Dey are filled with de power of blood magic and are used in dirty rituals. \n\nBlood is drained from \"volunteers\" to corrupt de tadpoles of Krag'wa into vicious crawgs.\n\nIf dis is a possible fate for children of loa, we must end it. \n\nTake dis vial and bleed de orbs dry. De chronicler will need to do research.", objectives = "" }
WordHunterWoW_QuestEN[49381] = { title = "Vengeance Be Kind", description = "In the cave, you will find Mala'kili.\n\nShe be a depraved hoarder dat take pleasure in de tormented deaths of slaves and prisoners.\n\nDey be taken, one by one, and thrown to her pet monster. She is takin' what was theirs for herself.\n\nBring vengeance for de fallen bruddas, give dem peace, and all dat remains is for you.", objectives = "" }
WordHunterWoW_QuestEN[49382] = { title = "It Seems You've Made a Friend", description = "Dis young one has bonded with you. \n\nBring him to Krag'wa. \n\nSee if dere is anything to be done to heal him of de corruption.", objectives = "" }
WordHunterWoW_QuestEN[49393] = { title = "The Roughnecks", description = "NEW JOB OPPORTUNITIES!\n\nDo you seek danger? Beasts in great quantities? Perilous adventure?\nDo you also prefer the rugged outdoors to the dainty frilly froo-froo estate life?\n\nWell, you might be cutout to be a ROUGHNECK, suppliers of all gryphon mounts in Kul Tiras.\n\nInquire at the Roughneck Camp in Westwind Weald about this exciting new opportunity.\n\nApplicants must NOT be afraid of heights, feathers, and/or death.", objectives = "" }
WordHunterWoW_QuestEN[49394] = { title = "Hold Still", description = "If you want to be a Roughneck, you're going to have to pass a few... trials. Every one of us has done 'em, so I don't want to hear any whining.\n\nTake these clippers and get me some goat fur. You have to clip 'em while they're alive, because thems the rules. Oh, and cover your bits when you do it, they like to kick.", objectives = "" }
WordHunterWoW_QuestEN[49395] = { title = "The Bears and the Bees", description = "Hey, while you're out, would you grab some honey for me and the boys?\n\nPlenty of hives out in the woods, but I'd be careful if you don't want to dirty your delicate house cat hands. Bears out here tend to get pretty vicious when they smell honey.", objectives = "" }
WordHunterWoW_QuestEN[49398] = { title = "Raise a Glass!", description = "Pleased to meet you. Name's Venrik. I been scrapin' out a living here in Freehold for years.\n\nFlynn used to be a regular back when he... well I shouldn't say too much. A man's past is his own.\n\nI'll help the two of you out, but first I demand that you let me give you a proper Freehold welcome: A drink!", objectives = "" }
WordHunterWoW_QuestEN[49399] = { title = "The Big Job", description = "So the Irontide Raiders are bringing the various outlaw crews together for a big job using weapons provided by the Ashvane Company.\n\nSomething tells me they're not going fishing.\n\nWe should see if members of the smaller crews are carrying any notes or orders. I trust you can handle it?\n\nI need to lay low and catch up with Venrik. If anyone else were to recognize me, the odds of them offering a friendly drink are precisely zero.", objectives = "" }
WordHunterWoW_QuestEN[49400] = { title = "Recruiting Efforts", description = "The captain of the Irontide Raiders, Harlan Sweete, has it in his tiny head that he's in charge of Freehold now. \n\nHe's been forcing the smaller crews to pledge their loyalty, and littering the whole town with his damn recruiting posters.\n\nDo me a favor and take down any of them posters you find. Just don't let them catch ya doin' it, or it's a long walk off a short plank.", objectives = "" }
WordHunterWoW_QuestEN[49401] = { title = "Rodrigo's Roost", description = "We should check in with Cyrus and Taelia before we get in too deep.\n\n<Flynn pens a note on a scrap of parchment and tucks it into a small courier bag.>\n\nThis is all of the evidence we've gathered so far linking the Ashvane Trading Company to the weapons and pirates here in Freehold.\n\nTake it to Rodrigo, on the rooftop just behind this tavern. He raises parrots that make great messengers. Some are even big enough to ride!\n\nRodrigo's a few planks short of a poop deck, but he's trustworthy!", objectives = "" }
WordHunterWoW_QuestEN[49402] = { title = "Flew the Coop", description = "Yes, yes, you can ride the pretties. They like it! They're good pretties. They like helping!\n\nDo you like helping, too? Maybe you can help me!\n\nSome of the loud men came here and threatened me. They don't scare me! But they made the pretties fly away.\n\nIf you see any of my pretties out there, please feed this to them!\n\nIt's my special treat. I know it will make them come home.", objectives = "" }
WordHunterWoW_QuestEN[49403] = { title = "Rodrigo's Revenge", description = "The loud men are mean, but you seem nice!\n\nWant to have fun fun?\n\nThe pretties love my special biscuits, but it makes them full full. Then they have to... go. You know?\n\nLet's prank the mean men! Fly fly on the pretties and make them go.", objectives = "" }
WordHunterWoW_QuestEN[49404] = { title = "Fairwind's \"Friends\"", description = "Someone must have recognized Flynn and ratted him out! A bunch of Irontide thugs dragged him off to the Ring of Booty for a \"special audience\" with Captain Harlan Sweete.\n\nFlynn doesn't like to talk about this, but he used to captain his own crew. With Harlan as his First Mate.\n\nThe two had a falling out after a messy job and Flynn lost all taste for freebooting. Just disappeared one day.\n\nHarlan took the nastiest of the crew and formed the Irontide Raiders.\n\nIn other words; it's personal.", objectives = "" }
WordHunterWoW_QuestEN[49405] = { title = "Defenders of Daelin's Gate", description = "Daelin's Gate has protected the southern channel for decades. If it falls, the pirate fleet can sail straight into Tiragarde Sound!\n\nThe marines at Vigil Hill will need our help. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[49407] = { title = "Trixie Business", description = "Usually this is the part where I hand you the scroll and send you on your way.\n\nSadly, friend, these are unusual times.\n\nHow's a man expected to run an honest business dealing in highly illegal goods when the Irontide Raiders are shaking down good folk like myself?\n\nI'm prepared to offer you a handsome sum - and the scroll for our shelled associate - if you rid me of the damnable woman who collects these tributes.\n\nYou'll surely find her at Harlan's table at the bar, getting drunk on MY gold!", objectives = "" }
WordHunterWoW_QuestEN[49408] = { title = "Pirate Dice", description = "", objectives = "" }
WordHunterWoW_QuestEN[49409] = { title = "Missing Treasure!", description = "Which one o' you scurvy dogs dug up me treasure?!\n\nWas it you, Ned? I know you was in the Dead Man's Tale when I were talkin' about it!\n\nOr maybe it was ol' Nance Barmy, huh? Yer the one what fed me all them drinks in the first place!\n\nOh and don't think I forgot about you, Nub Nub! I ain't trust a hozen as far as I can throw 'em... which I guess is PRETTY FAR, but-- \n\n<Several lines are scratched out here.>\n\nSomeone stole me damn treasure!\n\n<Signed with an X.>", objectives = "" }
WordHunterWoW_QuestEN[49412] = { title = "Helping Henry", description = "The Roughnecks told me to clear the rocks in the forest. I didn't know they meant THIS!\n\nYou look tough, you have to help me! I'll get killed if I get anywhere near that thing. I'm also super allergic to bees...", objectives = "" }
WordHunterWoW_QuestEN[49417] = { title = "Roughneck Riders", description = "Rulf sent word that you're needed for another job.\n\nA rich house cat is willing to pay top dollar for a male aerie alpha and there is only one that fits the bill, Greatfeather. I gotta head back to camp to help train a particularly wild female, so this is going to be a solo job.\n\nFind Greatfeather and hit him with the Tether Shot. From there, you'll have to wing it.", objectives = "" }
WordHunterWoW_QuestEN[49418] = { title = "Big Boss", description = "With a performance like that, it's clear you're one of the top dogs here. Boss Tak will want to see you. He's up north checking on one of our camps in Waning Glacier. Head up that way and give him a hand.\n\nOh, and I don't recommend looking him straight in the eye... or at his feet... or really anywhere near him. Best bet, close your eyes when you're talkin' to him.", objectives = "" }
WordHunterWoW_QuestEN[49419] = { title = "Frozen", description = "Hurp me pwease! Oh, it's woo. I can sill muv my wips a wittle.\n\nFin me sumfin to 'et me owdda 'ere.", objectives = "" }
WordHunterWoW_QuestEN[49421] = { title = "Hunting Zul", description = "Zul is pulling all of his forces back to his stronghold at the Temple of the Prophet.\n\nRastakhan has sent word that he is marshalling an army in the Zocalo with anyone still loyal that can carry a weapon. Looks like the old king had more loyalists than Zul expected.\n\nThat, and he has three of their eldest loa gathered to his side.\n\nGo and lend your strength to their army.", objectives = "" }
WordHunterWoW_QuestEN[49422] = { title = "Heretics", description = "Descend on Zul's fanatics and mogu allies. Hunt them down and slay them all with the fury of a true predator. Show them the true price of their betrayal.", objectives = "" }
WordHunterWoW_QuestEN[49424] = { title = "The Full Prophecy", description = "Dat snake of a prophet, Zul. I never trusted him. Always felt like he was never telling us de whole prophecy.\n\nEnter de Temple of dis \"Prophet\" and see if he recorded any of his visions.\n\nWe must learn of what our prey intends, before our real hunt may begin.", objectives = "" }
WordHunterWoW_QuestEN[49425] = { title = "City of Gold", description = "Rezan and Rastakhan did not wait for us. Dey are marching up de mountain to Atal'Dazar, de City of Gold.\n\nYou, Loti, and I need to catch up quick and give dem some air support. Hop aboard.", objectives = "" }
WordHunterWoW_QuestEN[49426] = { title = "The King's Gambit", description = "Atal'Dazar is the tomb of kings. MY kings. My greatest followers.\n\nI will taste Zul's flesh before this day is done.\n\nCome, {name}, keep up. Our prey has neither the strength nor the numbers to block this entrance. Let us crush this heretic.", objectives = "" }
WordHunterWoW_QuestEN[49427] = { title = "Not Our Purple Elves", description = "Ye know, {name}, these elves might be purple, but they're no' with the Alliance.\n\nLeastwise, they're a lot more aggressive than this ol' Dark Iron is comfortable with.\n\nOn the off chance it'll piss off the Horde, ye mind killin' a few of them?", objectives = "" }
WordHunterWoW_QuestEN[49428] = { title = "Grand Theft Telemancy", description = "I'm not opposed to honest competition, {name}.\n\nBut teleportin' it right out from under our noses leaves me feelin' dirty.\n\nGo teach that thievin' elf what it means t'steal from the Alliance. If they're fightin' dirty, then so will we.", objectives = "" }
WordHunterWoW_QuestEN[49431] = { title = "Warm and Cozy", description = "Heya! Isn't this place a dream? I couldn't be more relaxed. Well, I could be if these annoying cloud jerks would leave me alone. \n\nWhy don't you go punch some in their cloud faces. Oh, and bring back their essences, they help keep my tub warm.", objectives = "" }
WordHunterWoW_QuestEN[49432] = { title = "The Forlorn Soul", description = "Where's my ma'da? You seen her?\n\n\"I'll be right back,\" she said. I'm a good girl, I wait. I wait and wait, I'm not sure how long I've been waiting here for.\n\nIt's cold and lonely here. Hey... could you help me find ma'da? I swear I won't cause you any trouble.", objectives = "" }
WordHunterWoW_QuestEN[49433] = { title = "Wendies", description = "It's a mystery where these boys were taken, but it ain't much of a mystery who did it. Roughnecks believe an eye for an eye and then some.\n\nLet's put down some of those monstrosities.", objectives = "" }
WordHunterWoW_QuestEN[49435] = { title = "Where'd They Go?", description = "My boys are missing. You're going to help me find 'em.\n\nGot it?", objectives = "" }
WordHunterWoW_QuestEN[49437] = { title = "Tattered Note", description = "<The short, hand-written note is scrawled in blood.>\n\nThey captured me soon after I was exiled. I was too weak to be a slave and too starved to be food for the beasts.\n\nThey were going to kill me, but one called Shath'kar intervened. He said it would be amusing to watch me starve to death among his prisoners.\n\nI have not lived a good life. I deserve nothing. But, to any fellow Zandalari who finds this, I have one request...\n\nStick a blade in Shath'kar's belly and twist it until the snake is dead!", objectives = "" }
WordHunterWoW_QuestEN[49439] = { title = "Boss' Revenge", description = "Revenge has never really been my thing, but whatever is in there killed my crew and I am not going to let it stand.\n\nEverybody fights, nobody quits.", objectives = "" }
WordHunterWoW_QuestEN[49440] = { title = "Blood Troll on the Outside", description = "One of our scouts, Jo'chunga, has infiltrated de blood trolls, but we have not heard back from him.\n\nI need your help to find Jo'chunga and see what he has discovered about de blood trolls.\n\nIf you are going to find him, you need to sneak in by looking like one of de blood troll women. Dey are de ones with de most freedom to move around. I have a ritual that can change you.\n\nHelp me set up de ritual to make you look like a blood troll.", objectives = "" }
WordHunterWoW_QuestEN[49443] = { title = "A Lesson in Witch Hunting", description = "While I appreciate the dedication that went into compiling this tome, this thing reads like engineering instructions for a siege engine!\n\nI'll need some time to comb through this information for anything that might be useful to us. I wouldn't mind some assistance, if you have a moment.\n\nFor starters, I could use some more light in here...", objectives = "" }
WordHunterWoW_QuestEN[49445] = { title = "The Prime Exchange", description = "", objectives = "" }
WordHunterWoW_QuestEN[49449] = { title = "Leather - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49450] = { title = "Incident Reports", description = "No wonder our workers are terrified to go into these woods. Generally the bears and spiders stay out of the way of humans... \n\nBut these are no ordinary beasts!\n\nFather would be furious if productivity came to a halt. Please, cull these beasts so that the ridge can be safe once more!", objectives = "" }
WordHunterWoW_QuestEN[49451] = { title = "Time Off Requests", description = "My father is incapable of seeing what's in front of his very nose. He holes himself up in his office, not leaving to go home until late at night...\n\nHere I am, his only son, trapped out here along with all of his workers. Are they in trouble? Yes! But father will never believe them.\n\nIf he won't try to get to the bottom of this attack, I will do it myself!", objectives = "" }
WordHunterWoW_QuestEN[49452] = { title = "Inventory Deficit", description = "My employees say we're under attack. They say our workers are falling to beasts and men made of wood.\n\nI say we're losing precious inventory!\n\nDo you know how many company-issued axes must be getting dropped out there? That's a waste of my hard-earned money!\n\nI'm going to need you to get those back for me.", objectives = "" }
WordHunterWoW_QuestEN[49453] = { title = "Give a Dam", description = "These loggers are destroying the forest, and harming the wildlife!\n\nBeavers need this wood for their dams, but have had to resort to scrounging for scraps.\n\nIt's not safe for them anymore! Please, help me chase them back to the safety of the water.", objectives = "" }
WordHunterWoW_QuestEN[49454] = { title = "Pest Prevention", description = "These woods have never been so densely littered with spider eggs.\n\nIf these are recent... they must also be corrupted! We cannot allow them to hatch into more of these aggressive spiders.\n\nWhile you are in the woods, destroy those eggs. Any more spiders could lead to an uncontainable infestation!", objectives = "" }
WordHunterWoW_QuestEN[49455] = { title = "Leather - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49456] = { title = "Leather - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49457] = { title = "Bones - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49458] = { title = "Bones - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49459] = { title = "Bones - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49460] = { title = "Scales - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49461] = { title = "Scales - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49462] = { title = "Scales - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", objectives = "" }
WordHunterWoW_QuestEN[49464] = { title = "Saurolisk Tails", description = "Among the upper echelons of Kul Tiran society, there is one cuisine that escapes all but the most determined of chefs. Nobles will pay exorbitant amounts to have just a taste of this delicacy, spiced and cooked to one's delight.\n\nI speak, of course, of the saurolisk tail.\n\nI must discover the finest method of cooking this sought after comestible! Boiled? Braised? Poached? Perhaps steamed or blanched is the most appropriate method!\n\nI will, of course, need a few tails to test.", objectives = "" }
WordHunterWoW_QuestEN[49465] = { title = "Maximizing Resources", description = "Let me tell you a thing about my employees.\n\nThey're always blowing things out of proportion! I give them a good job with a steady wage and what do they do? They try to make excuses as to why they can't work!\n\nThey say the trees have come alive. Trees? Walking and fighting? If you're going to lie, at least make it more believable.\n\nIf they want to convince me, I'm going to need cold hard proof.", objectives = "" }
WordHunterWoW_QuestEN[49467] = { title = "Witch of the Woods", description = "A... a witch?!\n\nI uh... I would love to help you, truly I would but... I must report to my father.\n\nWhy don't you go stop the witch yourself? For a brave adventurer like you, a witch should be no problem.\n\nI'm sure my father would reward you greatly!", objectives = "" }
WordHunterWoW_QuestEN[49468] = { title = "Required Webinar", description = "I'm not surprised some of the workers stayed in the woods, even amidst the beasts. While he won't admit it, some of father's workers are extremely dedicated.\n\nAnd now they're trapped by the spiders!\n\nPerhaps they have information about what is going on here. Free them from their webbings and see what they know!", objectives = "" }
WordHunterWoW_QuestEN[49472] = { title = "A Titanic Effort", description = "Illidan may have forced fate's hand, but bringing Argus so near to Azeroth has accelerated the reaction triggered by the Nightwell's collapse.\n\nI believe the Legion's actions on Argus are further destabilizing the powers we've drawn upon unknowingly for many years.\n\nIt is clear that further studies are required.", objectives = "" }
WordHunterWoW_QuestEN[49474] = { title = "The Cursed Shard", description = "<A unnatural metallic shard catches your eye as it shifts from color to color. At your touch, one end of the shard swells in size before melting away. Droplets hit the ground with a hiss and a noxious stench invades your nostrils.\n\nSomeone in Dalaran who works with metals should be able to tell you more.>", objectives = "" }
WordHunterWoW_QuestEN[49477] = { title = "Surprise Backup", description = "<You find a torn Horde missive on the ground...\n\nIt appears that a group of forsaken, led by a man named Chadwick Paxton, were sent here to investigate Nazmir.\n\nYou're unable to discern why they were sent here, but there are coordinates that indicate where they were going.\n\nYou may be able to find the scouts at the coordinates and enlist their aid in fighting the blood trolls.>", objectives = "" }
WordHunterWoW_QuestEN[49479] = { title = "Didn't Stop to Think if They Should", description = "The sethrak seem to believe there's something in Nazmir that can unlock the destructive power of this gem.\n\nWe don't have that, but we have the next best thing. An insane warlock who is willing to experiment with magic.\n\nSpeak with Ingrid and have her begin the process to unlock the true power of this gem.", objectives = "" }
WordHunterWoW_QuestEN[49488] = { title = "Tal'gurub", description = "My prophet is a loyal servant, but he has his own ideas of how things must be.\n\nI am sending him to Tal'gurub to deal with a mess of his own making. One of his pupils, a witch doctor by de name of Vol'jamba, has taken de Gurubashi enclave as his own and has ousted my guards.\n\nMeet Zul at Tal'gurub and ensure dis nuisance is dealt with. Do not let him get... distracted.", objectives = "" }
WordHunterWoW_QuestEN[49489] = { title = "Needs a Little Body", description = "I am here primarily to deal with my wayward student. His followers, however, I will leave to you.\n\nI have seen a possible future dat is... concerning. Rivers running red with poison, dead filling de streets. And dese... \"Jambani\" asserting themselves as de new rulers of Zuldazar. Dis cannot come to pass.\n\nFortunately for you, I know how to avoid dat fate. I think you will find their cauldrons are missing one key ingredient.\n\n<He stares at you.>\n\nSomething to give it a little body, perhaps?", objectives = "" }
WordHunterWoW_QuestEN[49490] = { title = "The Urn of Voices", description = "Vol'jamba does possess de Sight, and so even now he is taking precautions against us.\n\nRegrettably his vision is incomplete. You will help me prepare for his demise and deal with his followers simultaneously. De tool you will use is called de Urn of Voices.\n\nTake it and venture into Tal'gurub. Slay his followers, destroy their golems and masks. Their spirits, once released, will fill de urn.\n\nOh, and try not to die while holding it. De Urn of Voices is not discerning.", objectives = "" }
WordHunterWoW_QuestEN[49491] = { title = "Fuel for the Voodoo", description = "Dere be no time! Dey be draining our spirits... using us... dark voodoo...\n\n<Loa Priestess Izita's spirit grows dim, and her voice is soft and distant.>\n\nDa totems... burn dem...\n\nDen we be free...!", objectives = "" }
WordHunterWoW_QuestEN[49492] = { title = "Arrogance of Vol'jamba", description = "Vol'jamba thinks his Sight has surpassed mine. I warned against such arrogance many years ago, but we see how well he listened.\n\n<Zul chuckles.>\n\nNo doubt he will attempt to deter us as we encroach upon his sanctum. Listen if you like, but remember dat he is desperate to save himself. His truth is distorted by fear.\n\nDestroy his masks and we will walk unharmed through dis passage.", objectives = "" }
WordHunterWoW_QuestEN[49493] = { title = "Zul's Ethical Dilemma", description = "Hm.\n\nDe Gurubashi have earned a reputation for betrayal and weakness. Their activities in Zul'Gurub will be a stain on our records for generations to come.\n\nOn de other hand...\n\nDe Zandalari are above de use of slaves. We are strong, capable. De very existence of mindslaves in dis great city is insulting.\n\nDere is a chant dat will free their minds. Use it near de mindslaves to free dem. \n\nOr you can simply kill dem. It makes no difference to me.", objectives = "" }
WordHunterWoW_QuestEN[49494] = { title = "Zuvembi Brew", description = "Zuvembi brew is arguably a witch doctor's most insidious concoction.\n\nDriven by de cauldron master's strength of mind, Zuvembi brew takes de will of those who breathe its fumes. It makes dem compliant, easily manipulated.\n\nIt is low magic, relying upon ancient cantrips and recipes known only to witch doctors of a certain skill. If we want to eradicate dis brew, we must slay those dat brew it.\n\nFind de Zuvembi brewer lurking here and see dat dis knowledge is erased.", objectives = "" }
WordHunterWoW_QuestEN[49495] = { title = "Enforcing Fate", description = "Vol'jamba is busy consolidating his power. His Sight has shown him dat he will fight, and perhaps even dat he will die, and so he looks to all his tools to save himself.\n\nI will need you to be my hands, as he will come as soon as I show myself. You will undo all de preparations he has made for dis day.\n\nDo as I say and we will both find ourselves enjoying de king's favor.", objectives = "" }
WordHunterWoW_QuestEN[49522] = { title = "Carentan's Payment", description = "Well done, my friend. Well done, indeed.\n\nYou see that dusty crate in the corner of the room? You'll find it contains the ancient scroll and a generous purse of gold, as we agreed.\n\nPlease, take your reward. You've certainly earned it.", objectives = "" }
WordHunterWoW_QuestEN[49523] = { title = "A Bad Deal", description = "<Carentan escaped!\n\nRoko, the tortollan merchant who set up this deal in the first place, will want to know what happened.\n\nWhen you last spoke, Roko said he would be heading to Boralus.>", objectives = "" }
WordHunterWoW_QuestEN[49531] = { title = "The Beauty of Marketing", description = "While us Fizzbrackets may not be goblins, we still know a business opportunity when we see one! The resort staff is getting trained, the place is getting cleaned up, now all we need is some quality marketing!\n\n<Wulferd holds up a familiar looking box.>\n\nBehold! The wondrous Gnomish engineering feat that is the S.E.L.F.I.E. Camera! Now, if only there was a generous {race} willing to capture the radiance of this place.\n\nMake sure you look like you're enjoying yourself out there!", objectives = "" }
WordHunterWoW_QuestEN[49532] = { title = "Warchief's Command: Shadowmoon Valley!", description = "All able-bodied members of the Horde are hereby ordered to report to Blood Guard Gulmok at Shadowmoon Valley in Outland.\n\nThe Burning Legion is attempting to lay siege to Shadowmoon Village, but our elite Kor'kron force is showing them what it means to fight against the Horde.\n\nCrush the Legion.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49533] = { title = "Warchief's Command: Howling Fjord!", description = "All able-bodied members of the Horde are hereby ordered to report to Apothecary Lysander in Howling Fjord.\n\nThe Forsaken have established a stronghold on the eastern shores of Northrend.\n\nNow is the time to strike at the Scourge with our military might and a new plague that is being developed by the Royal Apothecary Society.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49534] = { title = "Warchief's Command: Zul'Drak!", description = "All able-bodied members of the Horde are hereby ordered to report to Crusader Lord Lantinga in Zul'Drak.\n\nThe Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army.\n\nAssist the Argent Crusade and the Ebon Blade in stopping this threat.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49535] = { title = "Warchief's Command: Sholazar Basin!", description = "All able-bodied members of the Horde are hereby ordered to report to Archmage Pentarus in Dalaran over Crystalsong Forest.\n\nHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.\n\nWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49536] = { title = "Warchief's Command: Storm Peaks!", description = "All able-bodied members of the Horde are hereby ordered to report to Rin Duoctane in Dalaran over Crystalsong Forest.\n\nThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.\n\nSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49537] = { title = "Warchief's Command: Icecrown!", description = "All able-bodied members of the Horde are hereby ordered to report to Sky-Reaver Klum in Dalaran over Crystalsong Forest.\n\nThe Warsong Offensive needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.\n\nIt is time to make the Lich King pay for his crimes.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49538] = { title = "Warchief's Command: Jade Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to General Nazgrim in Orgrimmar.\n\nRecent victories in our naval battles against the Alliance strengthens our resolve.\n\nReport to Grommash Hold and assist the Horde's invasion fleet.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49539] = { title = "Warchief's Command: Valley of the Four Winds!", description = "All able-bodied members of the Horde are hereby ordered to report to Chen Stormstout in the Valley of the Four Winds.\n\nThe adventuring spirit of the Stormstouts is something that the Horde can learn from.\n\nTravel with the Stormstouts and discover what secrets Pandaria holds.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49540] = { title = "Warchief's Command: Krasarang Wilds!", description = "All able-bodied members of the Horde are hereby ordered to report to Zhu's Watch in Krasarang Wilds.\n\nThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.\n\nSpeak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", objectives = "" }
WordHunterWoW_QuestEN[49541] = { title = "Warchief's Command: Kun-Lai Summit!", description = "All able-bodied members of the Horde are hereby ordered to assist Lorewalker Cho in Kun-Lai Summit.\n\nSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49542] = { title = "Warchief's Command: Townlong Steppes!", description = "All able-bodied members of the Horde are hereby ordered to report to Taran Zhu in Townlong Steppes.\n\nThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.\n\nAssist them with their assault against the yaungol.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49543] = { title = "Warchief's Command: Dread Wastes!", description = "All able-bodied members of the Horde are hereby ordered to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms.\n\nThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.\n\nYou can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine.\n\nDestiny calls!", objectives = "" }
WordHunterWoW_QuestEN[49545] = { title = "Warchief's Command: Frostfire Ridge!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Drek'Thar in Frostfire Ridge.\n\nThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.\n\nWith Farseer Drek'Thar's aid, we will be able to establish a strategic position in Draenor to fight against our enemies.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49546] = { title = "Warchief's Command: Gorgrond!", description = "All able-bodied members of the Horde are hereby ordered to report to Durotan in Gorgrond.\n\nDurotan is seeking allies to help us navigate the savage landscape of Gorgrond in hopes that we will find ancient powers to help us destroy the Iron Horde.\n\nSpeak with him and see what secrets the lands hold.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49547] = { title = "Warchief's Command: Talador!", description = "All able-bodied members of the Horde are hereby ordered to report to Foreman Grobash in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Grobash is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49548] = { title = "Warchief's Command: Spires of Arak!", description = "All able-bodied members of the Horde are hereby ordered to report to Azik in Spires of Arak.\n\nThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.\n\nWe need to find out what is causing them to leave their homeland, and why their wings have withered.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49549] = { title = "Warchief's Command: Nagrand!", description = "All able-bodied members of the Horde are hereby ordered to report to Stone Guard Brox in Nagrand on Draenor.\n\nThrall is establishing a Horde outpost and needs help to stop the Warsong clan.\n\nSpeak with Bron Skyhorn to fly to Nagrand and meet up with the supply caravan.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[49550] = { title = "Hero's Call: Shadowmoon Valley!", description = "All able-bodied citizens of the Alliance are to report to Wing Commander Nuainn in Shadowmoon Valley on Outland.\n\nThe Burning Legion are laying siege to Wildhammer Stronghold, endagering our people and threatening their lives.\n\nWe need to reinforce the stronghold and stop the Burning Legion's relentless assault!\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49551] = { title = "Hero's Call: Howling Fjord!", description = "All able-bodied citizens of the Alliance are to report to Macalroy in Howling Fjord.\n\nThe port town of Valgarde is located in the heart of the Howling Fjord, and it allows for the Alliance to have an advantageous position to strike at the Scourge.\n\nAssist the soldiers stationed there.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49552] = { title = "Hero's Call: Zul'Drak!", description = "All able-bodied citizens of the Alliance are to report to Crusader Lord Lantinga in Zul'Drak.\n\nThe Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army.\n\nAssist the Argent Crusade and the Ebon Blade in stopping this threat.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49553] = { title = "Hero's Call: Sholazar Basin!", description = "All able-bodied citizens of the Alliance are to report to Archmage Pentarus in Dalaran over Crystalsong Forest.\n\nHemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin, but has gone missing.\n\nWe do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49554] = { title = "Hero's Call: Storm Peaks!", description = "All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest.\n\nThe goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers.\n\nSpeak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49555] = { title = "Hero's Call: Icecrown!", description = "All able-bodied citizens of the Alliance are to report to Officer Van Rossem in Dalaran over Crystalsong Forest.\n\nThe Valiance Expedition needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself.\n\nIt is time to make the Lich King pay for his crimes.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49556] = { title = "Hero's Call: Jade Forest!", description = "All able-bodied citizens of the Alliance are to report to Stormwind Keep in Stormwind.\n\nGrand Admiral Jes-Tereth is assembling a team for a high priority mission.\n\nHead to Stormwind Keep immediately to be briefed.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49557] = { title = "Hero's Call: Valley of the Four Winds!", description = "All able-bodied citizens of the Alliance are to report to Chen Stormstout in the Valley of the Four Winds.\n\nThe adventuring spirit of the Stormstouts is something that the Alliance can learn from.\n\nTravel with the Stormstouts and discover what secrets Pandaria holds.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49558] = { title = "Hero's Call: Krasarang Wilds!", description = "All able-bodied citizens of the Alliance are to report to Zhu's Watch in Krasarang Wilds.\n\nThere have been rumors that the pandaren living in Krasarang Wilds are not their usual self.\n\nSpeak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", objectives = "" }
WordHunterWoW_QuestEN[49559] = { title = "Hero's Call: Kun-Lai Summit!", description = "All able-bodied citizens of the Alliance are to assist Lorewalker Cho in Kun-Lai Summit.\n\nSpeak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49560] = { title = "Hero's Call: Townlong Steppes!", description = "All able-bodied citizens of the Alliance are to report to Taran Zhu in Townlong Steppes.\n\nThe Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so.\n\nAssist them with their assault against the yaungol.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49561] = { title = "Hero's Call: Dread Wastes!", description = "All able-bodied citizens of the Alliance are to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms.\n\nThe Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria.\n\nYou can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49562] = { title = "Hero's Call: Shadowmoon Valley!", description = "All able-bodied citizens of the Alliance are to report to Prophet Velen in Shadowmoon Valley on Draenor.\n\nThe destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them.\n\nWith Prophet Velen's blessing, we will be able to establish a strategic position in Draenor to fight against the enemies of Azeroth.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49564] = { title = "Hero's Call: Gorgrond!", description = "All able-bodied citizens of the Alliance are to report to Yrel in Gorgrond.\n\nYrel and Maraad are requesting for a small expedition to be sent into the wilds of Gorgrond.\n\nWe hope to gain a better understanding of the land in hopes that it will show us how to exploit weaknesses in the Iron Horde.\n\nAssist them with their expedition.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49565] = { title = "Hero's Call: Talador!", description = "All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Eksos is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49566] = { title = "Hero's Call: Spires of Arak!", description = "All able-bodied citizens of the Alliance are to report to Azik in Spires of Arak.\n\nThere have been wingless arakkoa seen fleeing from Spires of Arak. Rumors suggest that they are running from an Iron Horde superweapon.\n\nWe need to find out what is causing them to leave their homeland, and why their wings have withered.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49567] = { title = "Hero's Call: Nagrand!", description = "All able-bodied citizens of the Alliance are to report to Lieutenant Balfor in Nagrand on Draenor.\n\nYrel is recommending that the Alliance establish an outpost in Nagrand to help in our fight against the Warsong clan.\n\nSecure a flight to Nagrand and meet up with Lieutenant Balfor and the supply caravan.\n\nGlory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[49569] = { title = "Down by the Riverside", description = "We have de aid of Krag'wa and de Gob Squad. We must get back to Zul'jan and begin our plan to stop de blood trolls.\n\nWe have one problem. De Gob Squad are unable to move their mech fast enough in de jungle. We must take it by boat.\n\nDe two of us will ride with dem and ensure de blood trolls do not destroy de mech.\n\nI will run ahead and get de boat ready near de riverbank. Meet us dere.", objectives = "" }
WordHunterWoW_QuestEN[49570] = { title = "A Rocky Start", description = "<As you thumb through the book, the pages are unusually thick and embedded on their surface are runic-shaped jewels. Samuel Colton notices you looking and approaches.>\n\nAh, now that's a treasure I've had for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at the thought of something being transcribed in jewels.\n\nCome to think of it, I wonder if Zooey Inksprocket would be able to decipher it. Say, {name}, would you mind taking it over to her and see if she can translate it?", objectives = "" }
WordHunterWoW_QuestEN[49571] = { title = "Digging Through the Past", description = "Let's see, Jane Hudson probably still has her book on ancient runes and carvings. And I believe Tal'ana has a few scrolls he picked up from Ulduar.\n\nOH! And Toopa found what appeared to be some type of codex the last time he ventured out. I remember seeing the runes on it and they bear a striking resemblance to the ones in this book.\n\nIf you could convince them to uh... lend us those items for a bit, I believe I just might be able to create a translation for you. I won't even charge you for it!", objectives = "" }
WordHunterWoW_QuestEN[49572] = { title = "The Shrine of the Sea", description = "This next shrine is right here, in Tiragarde Sound.\n\nAccording to the journal, the earthen mentions creating bluish hued jewels. I wonder if that's anything like the kyanite we have here.\n\nGo and see if the shrine still stands. Hopefully it's still in a usable state.\n\nI'll continue to study the journal for more information.", objectives = "" }
WordHunterWoW_QuestEN[49573] = { title = "The Shrine of the Eventide", description = "There are two more shrines here on Kul Tiras.\n\nI believe this next one resides within Drustvar, near the Bleak Hills Mine, southeast of Corlain.\n\nHere are the notes on that shrine. Should it also need mending, I'm positive your skills with jewels can meet the challenge of repairing it.", objectives = "" }
WordHunterWoW_QuestEN[49574] = { title = "The Shrine of Storms", description = "Yes, I believe there are a few here in Kul Tiras. You should visit them, {name}, investigate them. See if what this book says is true.\n\nThis particular shrine he mentions sounds like it may reside near Brennadam, in Stormsong Valley.\n\nIt should be fairly easy to find. If my calculations are correct, it should be just north of that town.\n\nHere are the notes on that one. And I've marked its location for you on your map. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[49575] = { title = "Tol Dagor: Jewel of the Tides", description = "<An absence you assume to be a mistake, you quickly survey the area for something that might fit there yet you find nothing.\n\nHowever, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", objectives = "" }
WordHunterWoW_QuestEN[49576] = { title = "High Prospects", description = "<Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south.\n\nLooking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead.\n\nPerhaps investigating there will yield some clues as to where to find these jewels.>", objectives = "" }
WordHunterWoW_QuestEN[49577] = { title = "Cracking the Surface", description = "<Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest.\n\nPerhaps you can prospect the earth in that area to find more of those jewels and repair the shrine.>", objectives = "" }
WordHunterWoW_QuestEN[49578] = { title = "REUSE ME", description = "I've been to Zandalar before. Crazy place, full of dinosaurs and other unspeakable beasts. However one of the shrine's locations the journal speaks of sounds like a place they call Vol'dun.\n\nIt's a foreboding desert, full of canyons, with a great pyramid in the center.\n\nIf my calculations are correct though, the shrine ought to be around this area. I'll mark it for you on your map.\n\nAnd let's hope it's still in one piece.", objectives = "" }
WordHunterWoW_QuestEN[49579] = { title = "REUSE ME", description = "This next shrine might be a bit difficult to get to. It resides in Zandalar, the heart of the troll empire.\n\nWell, maybe not the main city itself, but close to it. Actually...\n\n<Samuel checks a map he has laid out.>\n\nAh, it's not too far from (POI). I've heard there's been some strife there between the Horde and Alliance. Perhaps there's a camp there you can work out of.\n\nHere are you notes for the shrine and the location for it should be marked on your map.", objectives = "" }
WordHunterWoW_QuestEN[49580] = { title = "REUSE ME", description = "The last shrine resides in Nazmir, a swamp infested with deadly creatures and home of the blood trolls.\n\nLuckily an ally of mine gave me a rather detailed map of that region and if my calculations are correct...\n\n<Samuel looks quickly back and forth between the journal and his map and finally stops his finger on the map.>\n\nIt should be right there. Take note of its location and here are the notes for that shrine. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[49581] = { title = "Sun-Speckled Dunes", description = "<Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nChecking your notes, it appears that these dunes were located south of your current location.>", objectives = "" }
WordHunterWoW_QuestEN[49582] = { title = "Atal'Dazar: Not All That Glitters...", description = "<You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\".\n\nGiven your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", objectives = "" }
WordHunterWoW_QuestEN[49583] = { title = "Out With the Old", description = "<It's clear though that time has had its way with these gems, some eroded and chipped in places.\n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", objectives = "" }
WordHunterWoW_QuestEN[49584] = { title = "The Missing Chapter", description = "<Samuel puts down the journal and looks back up at you.>\n\nWhile trying to figure out where the shrines reside, I came across an entry that mentioned him exploring an area that sounds very similar to Dustwallow Marsh.\n\nHe mentions hiding something of great importance there.\n\nIt's a long shot, given when this earthen roamed Azeroth, but perhaps if you were to retrace his final steps you may find something.\n\nI'll mark the location on your map.", objectives = "" }
WordHunterWoW_QuestEN[49585] = { title = "A Rocky Start", description = "<As you thumb through the book, you see odd-looking runes carved out of jewels embedded in the stone pages. Seshuli notices you looking and approaches you.>\n\nAh, dat's been a treasure of mine for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at de thought of something being written in jewels.\n\nCome to think of it, I wonder if Grazzul would know what it says. {name}, would you mind taking it over to him and see if he can translate it?", objectives = "" }
WordHunterWoW_QuestEN[49586] = { title = "Digging Through the Past", description = "Let's see, Examiner Alerinda has a book on ancient runes and carvings. I think Koatini has a few scrolls he brought with him from Ulduar.\n\nOH! And Chronicler Shoopa found a codex de last time he ventured out. I remember seeing de runes on it and dey look a lot like de ones in dis book.\n\nMaybe you can convince dem to lend us dose books for a bit, and I think I can create a translation for you.", objectives = "" }
WordHunterWoW_QuestEN[49587] = { title = "The Shrine of Nature", description = "Another shrine resides right here in Zuldazar.\n\nAccording to de journal, de earthen talks about creating green hued jewels dere. I wonder if dat's anything like de viridium we find in de ore we mine.\n\nGo and see if de shrine still stands. Hopefully, we can still make use of it.\n\nI'll continue to study de journal for more information.", objectives = "" }
WordHunterWoW_QuestEN[49588] = { title = "The Shrine of the Sands", description = "Dere are two more shrines here on Zandalar. Dis next one resides within Vol'dun, near Bonetrail Gulch.\n\nHopefully de Faithless haven't defiled de shrine.\n\nHere are de notes on dat location. Should dat shrine also need fixing, I think your skills with jewels will probably be enough to fix it.", objectives = "" }
WordHunterWoW_QuestEN[49589] = { title = "The Shrine of the Dawning", description = "Yea, I believe there are a few here on Zandalar. You should find dem, {name}, investigate dem. See if what dis book says is true.\n\nDis particular shrine sounds like it might be in Nazmir. If my calculations are correct, it should be just south of Torga's Rest.\n\nDat loa was a mighty one. It is truly sad dat it is no longer with us.\n\nHere are de notes on dat one. And I've marked its location for you on your map. Loa be with you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[49590] = { title = "REUSE ME", description = "As you peer from one gem to the next, you realize that the shrine appears to be fine, yet no power radiates from it.\n\nPulling out your jewelcrafting tools, you begin to inspect the central gem and realize that there is in fact a flaw. A small crack near the base of it that permeates through the gem towards the back.\n\nYou reference your notes on the shrine and discover that this gem came from a \"golden sanctuary\".\n\nPerhaps someone back at the Explorer's League Campsite will know what this means.", objectives = "" }
WordHunterWoW_QuestEN[49592] = { title = "REUSE ME", description = "Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places. \n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.", objectives = "" }
WordHunterWoW_QuestEN[49593] = { title = "REUSE ME", description = "I once viisted Kul Tiras. Da humans dere not be too friendly to us Zandalari. However one of da shrines be dere, in Tiragarde Sound.\n\nDat place have da most humans of all dat land. Ya need to be watchin' your back out dere, {name}.\n\nI'll mark da location of it on your map for ya.\n\nAnd let's be hoping dem humans didn't mess wit it.", objectives = "" }
WordHunterWoW_QuestEN[49594] = { title = "REUSE ME", description = "Da next shrine be a in a place dey call Drustvar. From what I be hearin', dat place is full of witches.\n\nDey use deir magics to bring tings ta life. But lookin at da map and where I tink dis shrine be, ya may not be needing to run into any of dem.\n\nIt's pretty close ta da Smuggler's Cove. I'd make ya way dere and den find da shrine. I'll mark ya map for ya where I tink it is.", objectives = "" }
WordHunterWoW_QuestEN[49595] = { title = "REUSE ME", description = "Da last shrine in Kul Tiras be in a green place dey call Stormsong Valley. Da humans dere probably won't be givin' ya too much trouble.\n\nBut da shrine be pretty dead center in da land, so ya probably gonna have ta do some travelin'. I'll mark it on ya map for ya.", objectives = "" }
WordHunterWoW_QuestEN[49596] = { title = "REUSE ME", description = "As you peer at the rock altar in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, someone who had not been there before has shown up. Perhaps he might know the whereabouts of the shrine's missing piece.", objectives = "" }
WordHunterWoW_QuestEN[49597] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[49598] = { title = "REUSE ME", description = "Upon your investigation you discover that the shrine has several locations where jewels appeared to have been located, but no longer exist. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the north.\n\nPerhaps you can prospect the earth in that area to find more of those jewels.", objectives = "" }
WordHunterWoW_QuestEN[49599] = { title = "The Missing Chapter", description = "<Seshuli puts down the journal and looks back up at you.>\n\nWhile trying to figure out where de shrines reside, I came across an entry dat mentioned him exploring an area dat sounds very similar to Dustwallow Marsh.\n\nIt could be a long shot, given when dis earthen roamed Azeroth, but maybe if you retrace his final steps, you may find something.\n\nI'll mark his last location for you on your map.", objectives = "" }
WordHunterWoW_QuestEN[49613] = { title = "Silvermoon City", description = "The nightborne have been isolated from the world for thousands of years. Now that they have reemerged, it is up to us to guide them along the right path.\n\nRegent Lord Theron has extended an invitation to the nightborne to meet with us in Silvermoon.\n\nCome, {name}, let us travel to Silvermoon with Thalyssra.", objectives = "" }
WordHunterWoW_QuestEN[49614] = { title = "The Nightborne", description = "The Warchief will be pleased with our success.\n\nThalyssra and her nightborne will prove strong allies, I am sure.", objectives = "" }
WordHunterWoW_QuestEN[49615] = { title = "Trust of a King", description = "Well, now dat you are settled in, you had best go speak with my father. You can find him up upon de throne, his advisors close at hand, pouring poison in his ear, no doubt.\n\nDe lift behind you can take you to de Golden Throne above us.", objectives = "" }
WordHunterWoW_QuestEN[49661] = { title = "Locally Sourced Eggs", description = "There is nothing in the world greater than food made from the best, freshest ingredients!\n\nMy good friend I am on a hunt. A hunt for the perfect eggs! I have heard tale of eel eggs. A delicate texture, a slight undersea saltiness... such a unique flavor profile! I must have them!\n\nThe eels here lay their eggs on the land before returning to the sea. Please, gather these eggs for me so that I may create only the most elegant of omelets!", objectives = "" }
WordHunterWoW_QuestEN[49662] = { title = "The Missing Key", description = "Korthek has grown spiteful and arrogant over the years, but I realize now that he has grown mad as well.\n\nMythrax will kill all of us if he is released.\n\nFor too long, I've held out hope that I could convince Korthek peacefully to abandon his heresy. I was wrong.\n\nAll of Zandalar is at risk while Korthek and his allies hold even one key to Mythrax's prison.\n\nMeet me outside his fortress in the north. We will confront my old friend \"Emperor\" Korthek and end this together.", objectives = "" }
WordHunterWoW_QuestEN[49663] = { title = "False Prophecies", description = "Now dat dis nuisance is out of de way, I can return my focus to de city. Zuldazar has languished while I was away.\n\nYou should return to Rastakhan. Let de king know dat his will has been carried out and dat dis false prophet is no more.\n\nYou might think to share Vol'jamba's prophecy with him, if you feel it worth his notice. I cannot say it will change anything at all.", objectives = "" }
WordHunterWoW_QuestEN[49664] = { title = "Allies in Anarchy", description = "Even after all these years, I can feel the ancient power of Sethraliss in this place. My loa endures.\n\nOur task ahead is great and I will need a clear, focused mind to accomplish it. Allow me a few moments to meditate here, like I did in ages past.\n\nIn the meantime, you should help the vulpera stir up trouble however you can. They seem to know you, and a large enough disturbance will distract the Faithless from our mission.\n\nMeet me back here when you're done and we'll proceed together.", objectives = "" }
WordHunterWoW_QuestEN[49665] = { title = "Ready to Riot", description = "Do you remember how we met, {name}? You were trapped in a Faithless cage, just like the ones in the crater below.\n\nTogether, we slaughtered Faithless and earned your freedom in blood.\n\nThe vulpera trapped in shackles below can do the same. They just need to be given the chance.\n\nSteal Faithless weapons and give them to the vulpera slaves below. They'll rise up and help you fight the Faithless.\n\nWe're going to start a revolt right under their arrogant noses.", objectives = "" }
WordHunterWoW_QuestEN[49666] = { title = "Make Them Fear Us", description = "I carry this banner into every battle because I want the Faithless to fear it. To fear my people.\n\nIf I die in the battlefield, surrounded by Faithless, I will die happy.\n\nOn that day, I will not need a burial or prayers. But I will need someone to pick up my banner and carry it into the next battle.\n\nIf you are of the same mind, plant these banners into the corpse of every Faithless you slay. Let the survivors know who's coming for them.", objectives = "" }
WordHunterWoW_QuestEN[49667] = { title = "The Little Ones", description = "Just when I thought the Faithless couldn't get any worse, I find out that they're keeping vulpera children trapped down in that crater!\n\nThe other vulpera we rescued told me that a big sethrak, Appraiser Versik, is inspecting them on the central platform to determine what he can sell them for.\n\nSelling vulpera kids! Oooh, those Faithless make me so angry!\n\nPlease, {name}. I'm no fighter. I can't rescue those kids. But if you bring them up here to me, I promise I'll get them out of here safely.", objectives = "" }
WordHunterWoW_QuestEN[49668] = { title = "Light Up the Gulch", description = "Don't mistake my caution for hesitance, {name}. I will defend the vulpera with my dying breath... I'd just prefer to avoid taking that breath today.\n\nWhile Nisha rushes to the front line, I work behind them to ensure our success.\n\nMeet me at the Faithless beast pens if you'd like to help.\n\nOh, and take this torch. You'll be going through their marketplace, where they auction off slaves.\n\nStarting a few well-placed and metaphorically poignant fires along your route will make things easier for all of us.", objectives = "" }
WordHunterWoW_QuestEN[49669] = { title = "Unleash the Beasts", description = "The Faithless are arrogant hoarders, capturing people and beasts that can never be truly tamed. All to fuel their endless lust for war.\n\nI've even seen their slavers dragging blood trolls and other dark monsters from the swamps of Nazmir.\n\nI heard terrible noises coming out of a cave while I was scouting the feeding pits up ahead.\n\nWhatever monsters they are hiding in there, find a way to free them and let them exact revenge on the Faithless.", objectives = "" }
WordHunterWoW_QuestEN[49676] = { title = "Dressed for Battle", description = "Kiro's the leader of my caravan. He's always been far too passive.\n\nI warned him we needed to make a preemptive strike against the sethrak, but he insisted that we keep our heads down and continue to quietly do business.\n\nLook where that got us.\n\nOur caravan was completely unprepared for their attack. \n\nNow I'm ready to fight for what's ours, but I'm not exactly dressed for battle.\n\nHelp me scavenge some suitable equipment here among our enemies. We will use their own tools against them.", objectives = "" }
WordHunterWoW_QuestEN[49677] = { title = "Plans for Attack", description = "Before we were attacked, I had a plan to take the fight to the sethrak. \n\nIt was devised with flawless intel. I know, because I gathered the information myself. \n\nI surveyed their entire compound and created a map based on my findings. \n\nMy plan relies on that map, but it's now in the hands of Fangcaller Sraka, the brute who's leading this assault on my home.\n\nHelp me kill her so I can take back what's mine!", objectives = "" }
WordHunterWoW_QuestEN[49678] = { title = "I Spy a Spire", description = "It is good you have come. Dol'watha be under attack by these snake-men.\n\nSoon as they arrived they started pulling these weird spire-things out de ground. I seen a bunch of snake-mons with feathers in their caps getting zapped by them, but they not be dying.\n\nIf it not be bad for them, that means it's good for them. And that be bad for us.\n\nDestroy those spires. Hopefully whatever boon they be getting will go away and they will be easier to kill.", objectives = "" }
WordHunterWoW_QuestEN[49679] = { title = "The Sethrak Incursion", description = "Dol'watha be a small village. Got a few farms, some beasts, and a decent view of a swamp.\n\nLoa know we not be ready for this...\n\nDe snake-men popped out of de ground by de hundreds. Slaughtered my beasts, my family, my friends. One minute de earth rumbling, de next we be running for our lives.\n\nI heard about snake-men from de deserts of Vol'dun but I never believed I would see them in my life...\n\nHelp us fight back. Kill as many of them as you can. Dol'watha won't be beaten that easily!", objectives = "" }
WordHunterWoW_QuestEN[49680] = { title = "Skycaller Soltok", description = "As if snake-men with swords not be bad enough, they brought a powerful skycaller along.\n\n I hear skycallers can tempt great storms into being. They be to blame for de spires and lightning flying everywhere.\n\nThere be one who wear a bigger feather than most, likely de leader. Calls herself Soltok or something equally hissy.\n\nDon't care. Kill her.", objectives = "" }
WordHunterWoW_QuestEN[49681] = { title = "Lil' Tika", description = "<The tiny armored raptor scratches pitifully at the cage's wooden bars. As you approach, the miniscule reptile wiggles frantically and issues a piercing screech for help!\n\nPerhaps you can open the cage and let it free.>", objectives = "" }
WordHunterWoW_QuestEN[49694] = { title = "Turn to Drust", description = "There are blood scribe masters all over the place who'll teach you what you need to know. The first master I'd recommend seeking out is Kronah.\n\nShe's a bit... eccentric to say the least. One of the few tortollan who've experienced a thing or two.\n\nShe's the one who taught me the blood contract I know how to invoke!\n\nShe likes to hang out at the Smuggler's Cove on the western coast of Drustvar. Oh, and could you say hi for me when you see her?!", objectives = "" }
WordHunterWoW_QuestEN[49698] = { title = "The Lightforged", description = "Do you wish to hear how the Lightforged draenei joined the Alliance? It might be one of my favorite stories.\n\nMost likely since it involves seeing our beautiful world from space!\n\nIt all began when High Exarch Turalyon invited members of the Alliance onto the Vindicaar...", objectives = "" }
WordHunterWoW_QuestEN[49703] = { title = "House Stormsong", description = "I have little information to offer, I'm afraid. I've scarcely left Brennadam as of late.\n\nWhat they said is true. Our militia now enter town only to collect rations rather than guard traders or keep the quilboar at bay.\n\nThey say they are under orders, but those orders would only come from my brothers at the Shrine. We take oaths to serve our people... it simply does not add up.\n\nBrother Addington is nearby at Mariner's Strand. Perhaps he knows more than I.", objectives = "" }
WordHunterWoW_QuestEN[49704] = { title = "Haywire Harvesters", description = "See the golems down there? Farmers use their sharp claws to reap the harvest, but these are cutting timber... \n\nWhy would they need them here when they have so many laborers on hand?\n\nI think the militia is using them to intimidate their own people!\n\nSee if you can get ahold of an intact mainspring from one. I've helped repair a few back in Boralus. I should be able to figure out who is messing with their innards.", objectives = "" }
WordHunterWoW_QuestEN[49705] = { title = "Unnecessary Duress", description = "Lord Stormsong has never taken kindly to dissent, but this is madness. These laborers are being worked to death!\n\nAddington was a good man. We cannot stand for such cruelty.\n\nTake this vial and apply it to the laborers. It contains blessed seawater that will rejuvenate their strength.\n\nAvoid engaging what troops you can. They are merely following orders. More death will only worsen matters.", objectives = "" }
WordHunterWoW_QuestEN[49706] = { title = "Proclamation Investigation", description = "My lord seldom leaves our holdings along the northern coast, and visitors are expressly forbidden. For most, tidesages like myself are their only connection to the house proper.\n\nLord Stormsong usually delivers orders through proclamations posted throughout the valley. None have reached Brennadam, but if there are any posted here we may be able to find some answers.", objectives = "" }
WordHunterWoW_QuestEN[49710] = { title = "An Offering of Eggs", description = "Our work isn't only to capture and tame gryphons, it's also to preserve them.\n\nRescue any eggs remaining in nearby abandoned nests. Set them in one of the new nests we've built for the displaced gryphons. I am sure one of the gryphon females will adopt them.", objectives = "" }
WordHunterWoW_QuestEN[49715] = { title = "Trouble at Greystone Keep", description = "A friend of mine, a fellow military courier, had a job at Greystone Keep. The fort lies just outside of Boralus, so I would've expected him to be back by now.\n\nI have another job lined up, so could you go check out the fort for me? I'm probably just being paranoid.", objectives = "" }
WordHunterWoW_QuestEN[49716] = { title = "A Lesson on Trust", description = "The men in the fort were once under my command, and so, they are now my responsibility. Each of them should have a badge we use for identifying individuals under certain circumstances. I would ask you to bring back a number of these as proof of thinning their ranks.\n\nThese men are no longer soldiers of Boralus, and as such, no longer deserve to carry the Proudmoore anchor.", objectives = "" }
WordHunterWoW_QuestEN[49719] = { title = "Getting Paid", description = "Now that we got our mitts good and bloody, I think it's time we head back to camp.\n\nI'll run ahead, so you can finish up whatever business you got. Just remember to meet Tagart for your pay.", objectives = "" }
WordHunterWoW_QuestEN[49720] = { title = "Free Bird", description = "Skyheart invited me here to teach some of his city boys how to train the local sea hawks. Some of my students went and sided with the mutiny force. Seems these soft marines have forgotten what the consequence is for betraying a Drustvar soldier.\n\nWorse yet, they've locked up quite a few of the younger birds we were training. I've got my hands full with these hawks, so if you could free a few of the young'uns while you're in the fort, I'd appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[49725] = { title = "A Risky Ploy", description = "Things are worse than we thought. These people are about to tear Brennadam apart!\n\nWe'll never get a chance to talk to Brother Pike in this mess.\n\nI have an idea, but if it doesn't work, well... I hope you have your running boots on.\n\nTrust me?", objectives = "" }
WordHunterWoW_QuestEN[49730] = { title = "WANTED: Thundersnout", description = "Thundersnout is the largest of the boars in the valley. She is wreaking havoc on the nearby farms and their crops.\n\nMayor Roz of Brennadam has issued a bounty for proof of her demise.\n\nThundersnout's location is near Briarback kraul, so be on the look out for quilboar!", objectives = "" }
WordHunterWoW_QuestEN[49731] = { title = "Fond Farewells", description = "Dis is where we part ways, {name}.\n\nI'm going to take de name Akunda, and start a new life here. \n\nRakera saved my life, and I'm going to make sure to live a life dat was worth saving. \n\nIf you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", objectives = "" }
WordHunterWoW_QuestEN[49733] = { title = "Patching Up the Rear", description = "Most of my men were injured when we were escaping the fort, those that weren't were injured holding this position.\n\n<Tallis hands you a stack of stained cloth.>\n\nAll of our better supplies are behind those walls, so we've been forced to make do with what we have. Everything that's not being worn on a soldier's person as we speak has been shredded for use as bandages. We don't have the staffing to take care of everyone.\n\nHead out and replace the worst of our injured's bandages.", objectives = "" }
WordHunterWoW_QuestEN[49734] = { title = "Targeting a Turncoat", description = "The instigator of this mutiny is a man named Fernn. He has always shown discontent with House Proudmoore and his position here. But to betray the men he works with? That seems beyond even my expectations of him.\n\nTake him out, and show this mutiny the mistake of crossing truly loyal marines.", objectives = "" }
WordHunterWoW_QuestEN[49735] = { title = "Protect the Nests", description = "Now that Tagart is done with your hazing... I mean... trials, you can start helping us with some of the work around here.\n\nSome of the nearby gryphon nests have been overrun with saurolisk. I fear that the gryphons will make new roosts elsewhere if we don't clear them out.\n\nHead up the road towards the waterfall and take out those saurolisks. Report to Shawn when you're done. He's posted as a lookout there.", objectives = "" }
WordHunterWoW_QuestEN[49736] = { title = "For Kul Tiras!", description = "Listen, I'll be frank with you; we're not at full strength here. Many of our soldiers recently left for Boralus on new orders.\n\nIt's like they knew just when to hit us...\n\nBut we're going to hit back! Every able-bodied man and woman in town has stepped up to mount a defense.\n\nTake this battle standard and remind them what they're fighting for!", objectives = "" }
WordHunterWoW_QuestEN[49737] = { title = "Air Raid", description = "Those pirates have air support! They're torching our farms and splitting our attention away from the front lines. \n\nTake 'em outta the sky!", objectives = "" }
WordHunterWoW_QuestEN[49738] = { title = "Hands Off My Booty!", description = "We are dealing with lawless, no-account thugs. As soon as they gained ground, they started looting! Looting right in the middle of a battle!\n\nWell I, for one, am not giving up our booty that easily.\n\nGet up to the top of Vigil Hill and man the main cannon. Rain hellfire down on those blaggards!\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[49740] = { title = "Cease Fire!", description = "The enemy has turned our forward cannons around on us.\n\nScuttle that equipment to stop the bombardments!", objectives = "" }
WordHunterWoW_QuestEN[49741] = { title = "Righteous Retribution", description = "Cyrus taught me how to deal with thugs, bullies, and scum like pirates.\n\nWhen they hit us, we hit back twice as hard.\n\n<Taelia's hand finds the haft of her hammer and grips it tight.>\n\nIt's time to hit back.", objectives = "" }
WordHunterWoW_QuestEN[49744] = { title = "Bombs, Away", description = "By the sea's foamy beard, what a blast!\n\nThey've brought goblins, and if there's one thing I know about goblins it's that they like to blow things up.\n\nI saw a few of them carrying large bombs, and I presume that they are going to blow up the town. I would like to keep the town, so how about you head out there and steal as many of those explosives as you can find? After that, let's blow up their demolishers and stop this infernal bombardment!", objectives = "" }
WordHunterWoW_QuestEN[49745] = { title = "You Have Their Orders", description = "The Horde is an army, make no mistake. And armies need orders.\n\nSomeone must be giving orders here. They know the plan, and I want to know the plan too.\n\nLook for the people who seem to be in charge and see if you can uncover any intelligence so we know what to do next.", objectives = "" }
WordHunterWoW_QuestEN[49746] = { title = "Dousing the Flames", description = "The Horde have set fire to my town, {class}. I will make them pay for this.\n\nStormsong Valley is the breadbasket of Kul Tiras, and our people need to be fed. The first thing we must do is damage control.\n\nGrab some buckets and help put those fires out!", objectives = "" }
WordHunterWoW_QuestEN[49754] = { title = "Not \"Only Zul\"", description = "Our enemies here either follow de name of Zul, or dey want to use him to take Zandalar.\n\nHe has the ego to allow either. \n\nDey claim only Zul can lead us.\n\nDissuade dem.", objectives = "" }
WordHunterWoW_QuestEN[49755] = { title = "Heavy Artillery", description = "Bad news, friend. They're bringing in serious firepower now.\n\nWe've spotted a tank on the northern hill by the windmill. They can reach the other side of the town from there. We can't let them set it up.\n\nWhat do you say to giving them a taste of their own medicine? If you can take out their commander, you'd have a fancy new tank all to yourself. Imagine the mayhem you could unleash on their invasion!", objectives = "" }
WordHunterWoW_QuestEN[49756] = { title = "Dark Forces", description = "The Old Gods have inflicted one of their faceless ones upon Thunder Bluff. The fiend desecrates my people's city!\n\nWe must fight together to rid this place of such filth.\n\nI believe that destroying this herald will drive our enemies from Mulgore. May our weapons strike true, {name}!", objectives = "" }
WordHunterWoW_QuestEN[49757] = { title = "Cat on a Hot Copper Roof", description = "My parents said we have to go, but I won't leave Scratchy behind!\n\nShe's so gentle and precious and pure and kind and soft and cuddly! She must be so scared up there on the balcony!\n\nPlease help her!", objectives = "" }
WordHunterWoW_QuestEN[49758] = { title = "Send the Signal!", description = "My crew is not on board with de word of Zul. We saw too much of who he really is. \n\nFar out in de harbor, Zul's traitors have joined with de mogu to try to take my ships! If we lose de fleet and de harbor, we lose de city!\n\nWe must let Zuldazar know we stand strong. We take back de ships. We drive de villains out. \n\nYou must light de towers with loa-blessed flame. Dey will always see dat de Bay of Kings belongs to Zandalar!", objectives = "" }
WordHunterWoW_QuestEN[49766] = { title = "Your Next Move", description = "We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.", objectives = "" }
WordHunterWoW_QuestEN[49767] = { title = "Your Next Move", description = "We have some thoughts on the best way to win over the Zandalari.\n\nThe princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father.\n\nGeneral Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here.\n\nWe should also keep working on winning over the King here in Zuldazar. This city is vast and has many secrets.", objectives = "" }
WordHunterWoW_QuestEN[49768] = { title = "Nesingwary's Trek", description = "De greatest hunter from your lands, de dwarf Nesingwary, has come to participate in de Great Hunt.\n\nIf you are enough of a hunter to join him, den travel to de Nesingwary Trek along de northeastern region of Zuldazar.", objectives = "" }
WordHunterWoW_QuestEN[49769] = { title = "Wreckage of the Cataclysm", description = "In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe.\n\nMy cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.", objectives = "" }
WordHunterWoW_QuestEN[49772] = { title = "For the Alliance", description = "The Army of the Light was founded with one purpose: to defeat the Legion. Though we have achieved that goal, a new duty lies before us.\n\nAzeroth is a world beset by enemies. Use your training to battle the darkness and uphold the ideals of the Alliance.\n\nGo to Stormwind. Seek the king's ambassador at the embassy, then set out to spread the Light's justice across the land.\n\nPheta thones gamera, {name}.", objectives = "" }
WordHunterWoW_QuestEN[49773] = { title = "For the Horde", description = "A new age dawns upon Highmountain, {name}.\n\nAfter centuries apart, the bond with our kin from Kalimdor has been reforged. And in the fight to save our land, we found new friends among the people of the Horde.\n\nTo show the strength we bring to our allies, brave tauren like you must heed the call of adventure.\n\nYou have been invited to Orgrimmar. Meet with the ambassador at the warchief's embassy, then begin your journey across Azeroth.\n\nEarthmother be with you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[49774] = { title = "Won't Leaf Him to Die", description = "I may have done some wicked things in my past, but I won't leave dis guard to die.\n\nZulajin has taken a nasty bite outta Zaluto... and has also infected him with some weird voodoo.\n\nBut don't worry, because today is our lucky day. I have a plan to cure him. Dere are sweetleaf bushes nearby!\n\nDe leaves of dis bush are known for their healing properties. You get me some, and I will be able to save dis Zaluto.\n\nIt's de only chance we have!", objectives = "" }
WordHunterWoW_QuestEN[49775] = { title = "Key to the Brig", description = "You can tell a lot about a troll by what they do when they learn who Zul truly is. \n\nThat Garza is a mutinous, foul-tusked, ship stealin' traitor. She is the kind of zealot dat will follow de heretic into the maw of an Old God. \n\nI am more de type to rip out her tusks and beat her with dem. \n\nI'd settle for ya taking her key and getting our wavemaster and crew free!", objectives = "" }
WordHunterWoW_QuestEN[49776] = { title = "No Problem Tar Can't Solve", description = "I'm not going to lie... I did wicked things in my youth and I've been living with de shame ever since.\n\nBut Zaluto is going to die without my healing, and we're all going to die if dat dino isn't taken care of.\n\nDere is a lot of tar in dis area. I need it to cure Zaluto of whatever is infecting him here.\n\nGet me dat tar, and I'll be able to save Zaluto from dis fate.", objectives = "" }
WordHunterWoW_QuestEN[49777] = { title = "On The Run", description = "<The guard captain appears to be fatally wounded.>\n\nWe were... transporting prisoners when de ambush came... a giant devilsaur... tore through everything.\n\nMost of de prisoners escaped in de carnage... dese are hardened criminals. Dey cannot be allowed to roam free!\n\nI swore a blood oath dat I would deliver dem to Vol'dun... I am probably going to die here, but I will not die an oathbreaker!\n\nFind de escaped criminals and exile dem to Vol'dun.", objectives = "" }
WordHunterWoW_QuestEN[49778] = { title = "Don't Go into the Light", description = "Okay, dis is de moment of truth! We will see if my voodoo can cure Zaluto.\n\nI should have been honest with you... dere is a chance dis won't work. Voodoo isn't a science, you know.\n\nI need you to hold Zaluto down, because dis here is going to hurt. A lot.", objectives = "" }
WordHunterWoW_QuestEN[49779] = { title = "Bad To The Bone", description = "I will not leave here without killing Zulajin, or else it will just go after de next caravan dat comes through.\n\nI have a plan, but we must work together to pull it off.\n\nDere are skeletal raptors roaming in de area. I do not know what voodoo brought dem here, but we need dem gone.\n\nWe are going to need as much space as possible for my plan to kill Zulajin.", objectives = "" }
WordHunterWoW_QuestEN[49780] = { title = "Recovering Ancient Fire", description = "Zaluto has a crazy plan to kill Zulajin. Never thought a guard could come up with something so clever.\n\nDere is ancient mojo throughout dis place... who knows what it used to be? But I sense something I can use.\n\nDe statues sinking in de tar pits have de fire mojo still burning in dem. We will need it to kill Zulajin.\n\nTake my fetish and use it to absorb what's left of de fire in dese statues.\n\nJust don't get dat fire too close to de tar!", objectives = "" }
WordHunterWoW_QuestEN[49781] = { title = "Catch Me if You Can", description = "Alright, de time has come for you to face Zulajin yourself!\n\nJin'Tiki's fetish has de power of some ancient fire in it now. You will ride my raptor here to lure Zulajin into de tar pits.\n\nAfter dat... you will use de fetish to light de tar pits on fire! Dat should be enough to kill Zulajin.\n\n...and if not, well, den you will have to improvise. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[49782] = { title = "Heritage of the Lightforged", description = "Your service to the Alliance has been most impressive, {name}. I could not have done better myself. Well, I could... but not by much.\n\nCome, meet with me at the Vindicaar. It is time that we reward your diligence.", objectives = "" }
WordHunterWoW_QuestEN[49783] = { title = "Heritage of Highmountain", description = "Your sojourn through Azeroth has been long, {name}. And through it all, you have brought honor to Highmountain.\n\nNow Thunder Totem calls you home. It is time we thank you for all that you have done for us.", objectives = "" }
WordHunterWoW_QuestEN[49784] = { title = "Heritage of the Nightborne", description = "You are among the first shal'dorei to venture forth and explore the wilds of Azeroth. But now it is time to come home.\n\nReturn to Suramar so that we may thank you for helping our people reclaim a place in this world.", objectives = "" }
WordHunterWoW_QuestEN[49785] = { title = "Destroy the Weapon", description = "I did scout de next island. Rezan's Claw has a mighty weapon on board.\n\nI don't know what it is, but dey are confident in its ability to break de defenses of our home.\n\nGet to de ship. Destroy that weapon before dey can use it on Zuldazar!", objectives = "" }
WordHunterWoW_QuestEN[49787] = { title = "The Ghostlands", description = "Are you familiar with how the Void elves joined the Alliance? \n\nIt began with Alleria Windrunner finding out about a blood elf named Umbric. \n\nHe and his followers were banished from Silvermoon City for researching void magic.\n\nAlleria believed she could convince Umbric and his followers to join the Alliance and prevent the void from corrupting them.\n\nIt all began when she opened up a portal to go into the Ghostlands...", objectives = "" }
WordHunterWoW_QuestEN[49788] = { title = "For the Alliance", description = "Mastering the whispers requires constant focus and discipline. Your dedication inspires all who bear the name ren'dorei--for we have become children of the Void.\n\nYou have learned many lessons here, but the time has come to venture beyond Telogrus Rift.\n\nGo to Stormwind, the heart of the Alliance. There, the king's ambassador will greet you and guide you along your journey.\n\nAzeroth must be defended. I can think of no one better suited to answer that call than you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[49789] = { title = "The Pledge", description = "The ethereals were lying in wait, anticipating someone strong enough in the void to be corrupted by the influence of the Old Gods.\n\nWe arrived in time to save them, and I will help teach them how to resist the whispers.\n\nUmbric is ready to join the Alliance. Let us return to Stormwind and inform King Wrynn.", objectives = "" }
WordHunterWoW_QuestEN[49791] = { title = "Lost, Not Forgotten", description = "I know not what madness has overtaken my people, but we must stop it together.\n\nTake this bell. It calls the souls of the recently deceased to it for later release. We Stormsong do not bury our dead in the earth. The tides claim all.\n\nIf they will not answer to reason, then we must give them eternal peace. Fallen or not, they are Stormsong.", objectives = "" }
WordHunterWoW_QuestEN[49792] = { title = "Bound and Oppressed", description = "We had our orders: ships, and lots of 'em. I led my boys as best I could.\n\nEverything changed when the tidesages showed up. We figured they was just checkin' on our progress, but the hood-wearin' bastards turned on us!\n\nThese anchors bind us here, forcin' us to work to death. No one deserves a fate like that. You gotta free my boys!", objectives = "" }
WordHunterWoW_QuestEN[49793] = { title = "Means to an End", description = "In our haste to journey here I did not think to bring my ritual implements we tidesages use to augment our power.\n\nTo be honest, I had never expected them necessary on what should have been a peaceful sojourn.\n\nAddington does not have his, either. I am sure the militia took him from his home before he had the chance to react.\n\nThat means his implements should still be in the yard somewhere. We must find them before my power is of much real use.", objectives = "" }
WordHunterWoW_QuestEN[49794] = { title = "The Rising Tide", description = "This mainspring wasn't altered by an engineer. These runes on the surface can only have come from a tidesage.\n\nTheir aquatic magic is unmistakable. I'd bet whoever did this is also responsible for Addington's death.\n\nWhoever they are, they're likely still nearby. Keep an eye out... they won't be hard to find.", objectives = "" }
WordHunterWoW_QuestEN[49801] = { title = "Aggressive Mating Strategy", description = "Aggression is good. I agree with Jangalar that Ben'jin needs to be a lot less passive to succeed and I can prove science is the way to do it by making an injection for him.\n\nAlchemy tells us that, for this type of beast, aggression comes from a substance in their bile sacs. The local razorwings are invasive and, as such, have more than enough aggression for our purposes. \n\nHarvest some of their bile sacs and I'll make a treatment that will have our big boy ready to go again in no time.", objectives = "" }
WordHunterWoW_QuestEN[49803] = { title = "Changing of the Guard", description = "I have no doubt that you're a quite capable {class}, mainlander, but we will need some help if we want to make it to Waycrest Manor in one piece.  A small group would be ideal; strong enough to face the coven's threats, but small enough to remain largely unnoticed.\n\n<Reade produces a bundle of letters.>\n\nI have written new orders to some of my finest soldiers to join your Order of Embers. They will report to you and the lady Waycrest. Please deliver these to them, so they can be prepared to move out.", objectives = "" }
WordHunterWoW_QuestEN[49804] = { title = "Sharp Thinking", description = "I have reason to believe that the coven has already infiltrated Arom's Stand. There are many unfamiliar faces here, with the refugees from Corlain, and we know they can use their magic to appear like one of us.\n\nThis needle is fashioned of solid silver. If the witches are indeed vulnerable to silver, then a prick from this may be enough to break their spell. \n\nThe refugees may not be keen on being prodded, but they must understand that this is for the good of the town... and perhaps all of Drustvar.", objectives = "" }
WordHunterWoW_QuestEN[49805] = { title = "Implements of Ill Intent", description = "<It looks like some careless witch made a poor attempt to hide this grimoire from sight. No good could come of leaving the possessions of the coven for a hapless villager to find.\n\nIt would probably be a good idea to destroy any trappings of the coven that you find in Arom's Stand.>", objectives = "" }
WordHunterWoW_QuestEN[49806] = { title = "Hidden Dealings", description = "<Among her possessions, the witch carried a crudely drawn map of Arom's Stand. \n\nA symbol marks what looks like the entrance to a cellar beneath one of the buildings.\n\nIf this location is important to the coven, it might be worth scouting out.>", objectives = "" }
WordHunterWoW_QuestEN[49807] = { title = "A New Order", description = "Before we leave, I have one more task to ask of you.\n\nWhile you were busy recruiting our inquisitors and driving the coven away from Arom's Stand, I took the liberty of placing an order with the local tailor. \n\nUsing some of the sketches within the tome, I had him put together some uniforms reminiscent of those worn by the ancient order.\n\nSince you will be leading our inquisitors, I think it's only fitting that you present them with their new regalia.", objectives = "" }
WordHunterWoW_QuestEN[49810] = { title = "Monstrous Matchmaker", description = "We have a problem, a matter of love, and you've come just in time. \n\nTwo white brutosaurs, de male Ben'jin and de female Maka'fon, are de last of their kind. De rest have passed on. \n\nDese two are not in de mood for love. If you can help my new friend Cala and myself, dis may be de only chance to give dem a future. \n\nPlace my voodoo totem close to each one so dat I can feel what dey feel and learn how we can help.", objectives = "" }
WordHunterWoW_QuestEN[49812] = { title = "Delas in Dalaran", description = "Delas Moonfang needs our help. In-turn, she will aid us to decrypt the Codex of Command.\n\nI implore you to seek her out as soon as possible. She is known to enjoy the memorial dedicated to the fallen, great leader of the Kirin Tor, Antonidas.", objectives = "" }
WordHunterWoW_QuestEN[49814] = { title = "The Scent for a Brutosaur", description = "Mood is everything for love, and Maka'fon is not in de mood. \n\nVoodoo incense, specially formulated for brutosaurs by an expert witch doctor like myself, will surely spark de fire of de mother spirit in her heart. \n\nCertain fragrant rushes work best, and de jungle will provide. \n\nZandalari rushes grow near de waters here. Get a good amount for me and I will make an incense bundle big enough to set de mood.", objectives = "" }
WordHunterWoW_QuestEN[49818] = { title = "Trouble at Fort Daelin", description = "I was sent to Brennadam by my commanding officer to find a tidesage to help us at Fort Daelin to the west. The naga have started another attack on the bastion, and it's larger than any we have seen. \n\nLieutenant Bauer is in the middle of helping out civilians at the village near the fort, and she could use any help possible.", objectives = "" }
WordHunterWoW_QuestEN[49831] = { title = "From the Depths", description = "We must prepare for an attack.\n\nMan the cannons!\n\nDefend the levee at all costs!", objectives = "" }
WordHunterWoW_QuestEN[49832] = { title = "An Illegible Scroll", description = "<Resting within the waterproof container is an illegible scroll of undetermined age and origin. \n\nPerhaps the tortollans along the coast will be able to decipher what is written upon the parchment?>", objectives = "" }
WordHunterWoW_QuestEN[49855] = { title = "Disaster at Mount Hyjal", description = "Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nYou can speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. He is in the tauren district in the Valley of Wisdom in Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[49869] = { title = "A Desperate Defense", description = "The soldiers garrisoned here are doing their best to hold out, but they're struggling. Pirates haven't dared attack this gate in years, and never with such a large force.\n\nIf you're handy in a fight, Lieutenant Tarenfold will want to meet you. \n\nHe's organizing the militia up ahead.", objectives = "" }
WordHunterWoW_QuestEN[49870] = { title = "Size Matters", description = "So the unintended side-effect of Gentle Ben'jin being, shall we say 'fun-sized' is that he is now small enough to get into the cave where the alpha wind serpent is! \n\nThe beast is called Gloomtail and if Ben'jin defeats it, he will feel like this territory is his and will want to fill it with little brutosaurs. So he will seek out a mate. If Maka'fon is receptive, everyone wins! \n\nGo give him another hit of the formula!", objectives = "" }
WordHunterWoW_QuestEN[49871] = { title = "Against the Tide", description = "De mogu are growin' desperate. Ha! Maybe dey hope to get away from here before de fury of de loa rain down on dem!\n\nDe warlord's pet sorcerer set up blockers and dey have taken de tower.\n\nIf you can avoid the sting, de lightning rods can have ya feelin' pretty good. One could even say energized. \n\nGet to Warlord Xiar and relieve him of his life privileges.\n\nThen let our people know we have taken back de Breath of Pa'ku! \n\nDis mojo is empowered to ignite de tower with a mighty blast.", objectives = "" }
WordHunterWoW_QuestEN[49873] = { title = "Sacrificial Writes", description = "<As you peer inside the tome, you find a verse appear, glowing bright red.>\n\n\"For blood to bond, one strikes a deal,\nA sacrifce which will appeal.\nSeek out the lame, and never yield,\nFor in return, you shall be healed.\"\n\n<As you finish reading the verse, you notice that a scroll has appeared in your hand.\n\nWritten across the top it's titled, \"Writ of Sacrifice\". Various runes, unknown to you, appear on the rest of the scroll. Yet, there's no explanation as to what to do with the scroll...>", objectives = "" }
WordHunterWoW_QuestEN[49874] = { title = "By the Book", description = "As you open the book, you stare at a blank page, waiting for something to happen.\n\nInstinctively you flip to the next page only to find it blank as well. Perhaps your trial awaits you further into the book?", objectives = "" }
WordHunterWoW_QuestEN[49875] = { title = "First Impressions", description = "This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste anyway. Takes thousands of years to train the palate.", objectives = "" }
WordHunterWoW_QuestEN[49876] = { title = "Lines In the Sand", description = "This was all I had to offer you, young scribe. But your journey is not yet at an end.\n\nIf you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar.\n\nOnce there, seek out a sethrak by the name of Veriss in an area known as Vol'dun.\n\n<Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.>\n\nPickled crocolisk eggs are my favorite. Would you like some?", objectives = "" }
WordHunterWoW_QuestEN[49877] = { title = "Temple of Sethraliss: Booking on a Favor", description = "When the Faithless came to power, we Devoted fled our sacred temple and took shelter here.\n\nHowever, in the midst of  our exodus, many of us were forced to abandon some of our belongings.\n\nI myself left a tome that is used to learn the Oblivion contract. If you wish to proceed with the trials, you must retrieve that book for me, {name}.\n\nI trust you won't disappoint me.", objectives = "" }
WordHunterWoW_QuestEN[49878] = { title = "Penning In Protection", description = "<As you open the book, you turn each page and see portraits of champions standing alongside a large beast.\n\nEventually you come to a blank portrait, and touch the page. Runes begin to appear in an ancient language, and quickly translate into words you can read.>\n\n\"The creature within, a guardian of men,\nA mixture of blood\nand of bone inked with pen.\nThe blood from the scribe,\nthe bone from the land,\nMilled to perfection,\nand signed by the hand.\"", objectives = "" }
WordHunterWoW_QuestEN[49879] = { title = "Brush With Death", description = "<As you open the book, a sudden chill comes over you. You shake the sensation off as you read the verse.>\n\n\"A fatal bargain, in blood is struck,\nOne inks their pledge,\nwith strokes of luck.\nStay true your lines,\nkeep still your breath,\nLest you stray too far,\nand summon death.\"\n\n<As you finish reading the incantation, a quill appears next to the book.>", objectives = "" }
WordHunterWoW_QuestEN[49880] = { title = "Blood Bonded", description = "Looks like you're all done here, {name}. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, {name}!", objectives = "" }
WordHunterWoW_QuestEN[49881] = { title = "The Final Verse", description = "It appears you are finished here, {name}. Thank you again for getting my book back.\n\nBut between you and I, this was the easy part. Just wait till you meet the grandmaster.\n\nIf you haven't noticed already, you'll need a special quill to invoke those contracts. And he'll be the one who shows you how to craft it.\n\nHis name is Miju and he lives out on an island off the southern coast of Zuldazar. Good luck, {name}!", objectives = "" }
WordHunterWoW_QuestEN[49882] = { title = "A Test of Quills", description = "The recipe you're after, young one, is that of the Sanguine Feather Quill of Lana'thel. I...\n\n<Miju motions to a pile of stuff.>\n\nAm the only other person I know of who has one... err... somewhere. But be warned, this trial may be your undoing!\n\nI shall have to invoke all four contracts against you. You must defeat each of the creatures, and from each one learn the rune needed to carve into your quill.\n\nOnce you've learned all four runes, your trial shall be completed.", objectives = "" }
WordHunterWoW_QuestEN[49884] = { title = "Hope's Blue Light", description = "There is but one step left!\n\nDe second tower means the fleet is ours again!\n\nClimb aboard and we will finish dis thing!", objectives = "" }
WordHunterWoW_QuestEN[49886] = { title = "Follow Your Nose", description = "You there! I could use your help!\n\nThe ground isn't safe. The quilboar have established a network of tunnels below us, allowing them to spring up to ambush people who aren't walking carefully.\n\nLuckily for us, Humphrey here has a nose for the Briarback, and can sniff 'em out even when they're underground. Root a few of them out and let's make the farms a little safer to walk through.\n\nThere's a particularly large clump of them in the northeastern fields. Good hunting!", objectives = "" }
WordHunterWoW_QuestEN[49887] = { title = "Forced Labor", description = "<The laborer struggles to speak through the magic binding him.>\n\nH... help... us...\n\n<He achingly lifts a finger, gesturing towards the nearby anchor.>\n\nPlease...", objectives = "" }
WordHunterWoW_QuestEN[49890] = { title = "Drustfall", description = "I believe I see more carvings at the entrance to that cave over there. Come, we should see what else was left behind.", objectives = "" }
WordHunterWoW_QuestEN[49896] = { title = "To Falconhurst!", description = "Our time here was well spent. The guards in Arom's Stand can handle what few Drust forces remain and I suspect the Drust leader and his magic might have some greater part to play here. \n\nHowever we must continue on the mission to Falconhurst. The path on the far side of these ruins will take us there.\n\nI will ride ahead and meet you outside of town!", objectives = "" }
WordHunterWoW_QuestEN[49897] = { title = "Making Mysteries", description = "Do you know what people love? The unexplained! Problem is, everything here is explainable. \n\nSo I have a plan to create our own phe-gnome-enon. There are stories that talk about some weird chicken-snake hybrids that can turn you to stone. I've already released the chickens, now we just need the snakes.\n\nThe first problem can be solved easily. Just chase down the chickens, and stick one of these robotic tails on them.", objectives = "" }
WordHunterWoW_QuestEN[49898] = { title = "Clear Victory", description = "<The ghostly captain continues to fight as she speaks, once more locked into the heat of battle, unaware the war has been over for centuries.>\n\nWhat are you doing standing around? We've ground them down to their final warriors and those damnable runic constructs, but the war isn't over yet!\n\nColonel Waycrest needs us to hold this line! Kill as many of those Drust as you can and we might see the end of this war, today. Get back out there!", objectives = "" }
WordHunterWoW_QuestEN[49901] = { title = "Atal'Dazar: Yazma the Fallen Priestess", description = "Zul knows dat we cannot let de first king rise from his grave. Dazar would be more than a figure head for Zul's dream troll empire, he would be a force dat could rival de very loa.\n\nBut I cannot just let Zul get away. I and mine will follow Zul, but I want you and yours to enter Atal'Dazar. Yazma is trying to buy time and keep de tombs sealed away. You will need to fight your way through to her and you will need some allies to do so. Slay her.", objectives = "" }
WordHunterWoW_QuestEN[49902] = { title = "To Gloom Hollow", description = "There's only one safe area in Nazmir that this Rokhan and your other Horde friends could be in. Gloom Hollow.\n\nLucky for you, it's also close to Krag'wa's den. We used Gloom Hollow as a last stop on our pilgrimage.\n\nMake your way to Gloom Hollow along the path I've marked on your map, and tell any tortollans along the way to meet us there.\n\nThey'll be interested in seeing the end of this story. We'll make our way there and grab anyone else we find.", objectives = "" }
WordHunterWoW_QuestEN[49905] = { title = "Plot Twist", description = "It is time to end Vol'jamba.\n\nI want to make one thing clear. He can still kill you. Your fate, moreso than mine, hangs on your ability to fight dis former student of mine.\n\nHe will bring masks, and voodoo, and he will do everything within his power to end you. All we have done is taken away his ability to cheat.\n\nGood luck. For your sake, I hope you do not fail.", objectives = "" }
WordHunterWoW_QuestEN[49908] = { title = "Back to Brennadam", description = "The naga are mostly cleared out thanks to your help. They'll think twice before attacking again.\n\nCan you return to Brennadam and tell Squire Augustus III to return to his normal station?", objectives = "" }
WordHunterWoW_QuestEN[49917] = { title = "Kaja'mite? Kaja'must!", description = "I been waitin' to talk to the King for a while now, but he not be seein' me! And this pompous lackey not be listenin' either.\n\nWe got a problem brewin' in the Village of the Vines, just outside de city. With all the Horde landin' in the Harbor, some goblins got wind of our old kaja'mite quarry. They split outta here like the teeth of Deathwing himself behind 'em.\n\nBut that quarry be dangerous. Wicked dangerous. Think you can go to de village an' talk some sense into them goblins?", objectives = "" }
WordHunterWoW_QuestEN[49919] = { title = "Kaja'mite Ore Bust", description = "Kaja'mite! Just saying the name gives my big beautiful ears a buzz. \n\nThese Zandalari were sitting on a huge deposit of it all these years. And they abandoned it just because of a few talking gorillas. By goblin law it's ours for the taking!\n\nLet's see how concentrated a deposit we're talking about. Get a good peek at those vents that are steaming out kaja'mite vapors.\n\nGo into the gorge and plant my scanners on those steam vents. They'll do the rest.", objectives = "" }
WordHunterWoW_QuestEN[49920] = { title = "Gorilla Warfare", description = "Your timing is most fortuitous, stranger. I thank you for your assistance.\n\nThings are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. \n\nMy brethren are those who do not wish to fight. Neither the Zandalari trolls nor each other. But for our passivity we have been persecuted.\n\nPlease free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", objectives = "" }
WordHunterWoW_QuestEN[49922] = { title = "King Da'ka", description = "These Zandalari won't go near Gorilla Gorge. All because they're afraid!\n\nIt's just a few talking gorillas. And one 'big mon' in particular as the Zandalari call him. \n\nAll we need to do is take out King Da'ka and the villagers will probably throw us a parade! Or at least let us mine that kaja'mite.\n\nThink you can handle one big gorilla, chum?", objectives = "" }
WordHunterWoW_QuestEN[49926] = { title = "The Road to Corlain", description = "Lord and Lady Waycrest lay trapped in Waycrest Manor. Before we can reach them, however, we must brave through the city of Corlain... which is firmly in the grasp of the Heartsbane.\n\nOur first course of action should be to set up a forward outpost. Our scouts have found that the tower at Watchman's Rise is only lightly guarded. I recommend we take the tower from them.\n\nThis is now your command, Inquisitor. Say the word, and we ride.", objectives = "" }
WordHunterWoW_QuestEN[49928] = { title = "Heritage of the Void", description = "Throughout your journeys across Azeroth, you have achieved mastery over the forces that constantly seek to control you.\n\nYou have become a formidable weapon of the Alliance, {name}. Return to the void rift so that we may honor your accomplishment.", objectives = "" }
WordHunterWoW_QuestEN[49931] = { title = "The Titan's Wrath", description = "", objectives = "" }
WordHunterWoW_QuestEN[49932] = { title = "Slumber No More", description = "There's something you should look into. You've got the time anyway, those goblins aren't ready yet.\n\nThere's a statue nearby. Only, it's not a statue to the trained tortollan eye. It's a deactivated titan keeper!\n\nNoises have been coming from that thing ever since you helped Krag'wa. It must be trying to reactivate itself.\n\nI bet that titan-looking amulet of yours could help restart it. We'd be unstoppable against the blood trolls with a titan keeper's help.\n\nGo see if you can restart this titan!", objectives = "" }
WordHunterWoW_QuestEN[49933] = { title = "For the Horde", description = "After ages standing alone, we are once again poised to become part of something greater. Our alliance with the Horde affords us a fresh start, a unique chance that must not be squandered.\n\nGo to Orgrimmar. From there, you will set out on a journey across Azeroth. Fight to defend this land, and claim a place for the shal'dorei within it.\n\nShow the world who we are, {class}. Bring honor to the Horde, for in so doing, you will bring honor to Suramar.", objectives = "" }
WordHunterWoW_QuestEN[49935] = { title = "How to Repair a Titan Keeper", description = "Major system repair possible within nearby structure. Preliminary goal: repair auxiliary systems.\n\nScans detect three fallen titan keepers. Recover cores. Titan Keeper Hezrel able to retrieve data from cores.\n\nTitan Keeper Hezrel goal: reboot auxiliary systems, reach nearby structure, restore all primary systems, seal corruption.\n\nResult: corruption contained. Titan Keeper Hezrel able to aid against blood trolls.\n\nBlood troll definition not found in databanks.", objectives = "" }
WordHunterWoW_QuestEN[49937] = { title = "Recovering Remnants", description = "Scan of area indicates roaming spirits clad in armor plating. Purpose: defense of structure, animated by corruption.\n\nDetecting remnants of titan plating within spirits' armor. Request: recover remnants.\n\nTitan Keeper Hezrel capable of breaking down titan plating to reforge into weapon against forces drawn by corruption.", objectives = "" }
WordHunterWoW_QuestEN[49938] = { title = "Corrupted Earth", description = "Unacceptable levels of corruption detected nearby. Scan indicates vegetation affected by corruption. \n\nAll corruption must be eradicated. Request: destroy any vegetation affected by corruption.", objectives = "" }
WordHunterWoW_QuestEN[49939] = { title = "So Long, Sister", description = "We have given the defenders some breathing room, but these creatures continue to lay siege to the barricade!\n\nThe witch behind the attack fled from the field when we defeated her forces. I saw her go into the mansion on the hill. I will help keep the defenses going here.\n\nYou must go into the mansion and slay the witch!", objectives = "" }
WordHunterWoW_QuestEN[49940] = { title = "Sandscar Breach", description = "I heard some mutterings about sand and snakes.\n\nThe plea comes from a tiny village on the very fringes of Zuldazar- hardly more than a few farms. Dol-something I think it was called. Don't know what they be calling it now. Go see what the fuss is about.\n\nBladeguard Sonji was sent ahead some time ago. She should be able to get you up to speed on that... situation.", objectives = "" }
WordHunterWoW_QuestEN[49941] = { title = "Bone Procession", description = "Undead entities influenced by corruption surround nearby structure. Impossible to approach. Plan required.\n\nCalculating.\n\nPlan achieved. Large creatures designated reanimated monstrosities focal gathering point of corruption.\n\nTake titan weapon forged from plating recovered. Use it to weaken monstrosities and collect bones.\n\nWill run process to destroy bones, prevent creation of further monstrosities.", objectives = "" }
WordHunterWoW_QuestEN[49943] = { title = "Drawing Blood", description = "Hey, {name}! I have something exciting to tell you about, but I need you to keep it secret. Just between us scribes.\n\n<Grazzul gives you a nod and pulls out a large tome.>\n\nDis is de Bloodbound Ledger. Signing your name in it let's you learn how to craft \"blood contracts\" which are rather dangerous, but worth de risk.\n\nI only know one of dem and it is quite de rush when I use it because it... well, you'll see.\n\nSo what do you say? Interested?", objectives = "" }
WordHunterWoW_QuestEN[49944] = { title = "Turn to Drust", description = "Dere are blood scribe masters all over de place who'll teach you what you need to know. De first master I'd recommend seeking out is Kronah.\n\nShe's a bit... eccentric to say de least. One of de few tortollan who've experienced a thing or two.\n\nShe's de one who taught me de blood contract I know how to invoke!\n\nShe prefers to hang out at de Smuggler's Cove on de western coast of Drustvar.", objectives = "" }
WordHunterWoW_QuestEN[49945] = { title = "First Impressions", description = "This was all I had to offer you, young scribe. But your journey is not yet at the end.\n\nGo to your trainer and and inform them of your success here.\n\n<Kronah grabs an odd-looking jar.>\n\nI don't suppose you'd like to take some pickled crocolisk eggs with you for the road, would you?\n\n<As she unlocks the lid, the foulest odor you've ever smelled permeates the air and you reel back in disgust.>\n\nFine, be that way. It's an acquired taste any ways. Takes thousands of years to train the palette.", objectives = "" }
WordHunterWoW_QuestEN[49946] = { title = "Lines In the Sand", description = "This was all I had to offer you, young scribe. But your journey is not yet at an end.\n\nIf you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar.\n\nOnce there, seek out a sethrak by the name of Veriss in an area known as Vol'dun.\n\n<Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.>\n\nPickled crocolisk eggs are my favorite. Would you like some?", objectives = "" }
WordHunterWoW_QuestEN[49947] = { title = "Blood Bonded", description = "Looks like you're all done here, {name}. Thanks again for getting my book back, you can understand how that might appear for a master such as myself to lose something like that.\n\nBut between you and me, this was the easy part. Just wait till you meet the grandmaster.\n\nI'll let your current trainer fill you in on that part. Good luck, {name}!", objectives = "" }
WordHunterWoW_QuestEN[49948] = { title = "The Final Verse", description = "Now dat you be done learnin' all da contracts, you be needin' one more ting ta learn.\n\nDere be a special quill ya need to make in order to craft da contracts. And dere be one last trial ya must complete in order ta be worthy ta learn da design for da quill.\n\nMiju be da mastah in charge of da design. Pass his trial, and he'll be teachin' ya what'cha need ta know.", objectives = "" }
WordHunterWoW_QuestEN[49949] = { title = "Unwelcome Undead", description = "Corruption reanimating dead creatures nearby. Morphing into monstrosities. Must be stopped.\n\nCannot kill all, but can reduce numbers. Reduced numbers equates to less corruption outside of containment.\n\nDestroy undead in surrounding area. Keeper Hezrel's systems will continue rebooting while you do so.\n\nReboot goal: recover data regarding nature of corruption.", objectives = "" }
WordHunterWoW_QuestEN[49950] = { title = "Blood Purification", description = "<You see a strange blood orb that emanates whispers of suffering and destruction.\n\nThese must be the source of energy for whatever corruption Hezrel is hunting. They appear easy enough to destroy.\n\nYou can see more of these orbs around the temple grounds. Perhaps destroying them will help to weaken the corruption in the area.>", objectives = "" }
WordHunterWoW_QuestEN[49952] = { title = "The Essence of G'huun", description = "Analysis of blood-infused bones complete. Will be able to create synthetic essence similar to G'huun.\n\nWill take a moment to apply essence, allow you to walk past undead without combat.\n\nMust hurry. More forces of G'huun are around temple. Must get inside to reactivate containment protocols.", objectives = "" }
WordHunterWoW_QuestEN[49955] = { title = "Not Fit for This Plane", description = "System restoration in progress. Data recovered. Source of corruption is from an Old God entity.\n\nMultiple entities detected nearby, blocking goal of analyzing and containing corruption in Nazmir.\n\nEntities appear to be from the Void. Drawn here from Old God corruption.\n\nRequest to destroy Void entities. Void presence inhibiting repair of systems.", objectives = "" }
WordHunterWoW_QuestEN[49956] = { title = "Void is Prohibited", description = "Scans indicate errors in reality surrounding nearby structure. Portals directly to the Void.\n\nCurrent theory, corruption has Old God as source. Void attracted to Old God corruption.\n\nPortals must be sealed to contain entities lured here by Old God corruption.\n\nTake this device. Titan Keeper Hezrel has forged it thanks to help in powering up systems.\n\nUse device to seal Void portals, prevent more void entities from entering area.", objectives = "" }
WordHunterWoW_QuestEN[49957] = { title = "Protocol Recovery", description = "System repairs progressing. One key component needed: containment protocol. \n\nContainment protocol will fully reboot defensive systems. Allow Titan Keeper Hezrel to properly maintain containment.\n\nScans indicate large creature within temple has absorbed slab containing containment protocol. Creature exists between this plane and Void.\n\nRequest: destruction of creature and retrieval of protocol.", objectives = "" }
WordHunterWoW_QuestEN[49960] = { title = "Sic 'Em!", description = "Humphrey's a good tracker, to be sure. He's also the orneriest, angriest, most dogged dog if he sets his eyes on a quilboar. This will certainly be useful.\n\nBelow our very noses, the foreman organizes and directs the tunnelers to cause the most mayhem and destruction. If you can put an end to him, it should make things a lot easier for us to move around the farmlands.\n\nHumphrey looks a bit hungry, wouldn't you say? Why don't you bring him with you to take care of business?", objectives = "" }
WordHunterWoW_QuestEN[49965] = { title = "The Warpack", description = "Zul began a coup, but he did not secure de pyramid for himself. Nor has he done anything to rally more to his banner outside of those who were already conspiring with him.\n\nDis concerns me more than if he had carved his face into Dazar'alor itself.\n\nWe must learn what he is up to. Join de disciples of Gonk and ride ahead to de Temple of the Prophet. Look to Wardruid Loti for further orders when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[49969] = { title = "Awaken a God", description = "You see the sinking ruins to the east? They were, not long ago, a temple to the shark loa, Gral.\n\nThe naga tore down his temple and are stealing his secrets. If it is for something good, I'll be a rock's uncle.\n\nIt would be wise to let Gral know what's going on here. I do not think he would approve.\n\nGral was quite powerful, and when it came to his knowledge of the sea, none could compare. It never hurts to have a fellow like that on your side.\n\nSome fresh, bloody naga meat may just lure him out.", objectives = "" }
WordHunterWoW_QuestEN[49973] = { title = "Thalyssra's Estate", description = "Would you like to hear how the nightborne came to join the Horde?\n\nWe earned their trust when we aided them in liberating Suramar from the tyranny of Grand Magistrix Elisande and the Burning Legion.\n\nLor'themar Theron later asked them to join him in Quel'Thalas. Lady Liadrin made the journey to extend the invitation to First Arcanist Thalyssra...", objectives = "" }
WordHunterWoW_QuestEN[49975] = { title = "Rest in the Depths", description = "This passage flows through the Shrine of the Storm out into the open sea. We will release the souls of the fallen here.\n\nLegends say that as our spirits pass through the Shrine, they aid in the great blessing rituals that all Kul Tiran ships undergo. \n\nIn that way, we Stormsong never stop serving our people.", objectives = "" }
WordHunterWoW_QuestEN[49980] = { title = "Containment Procedure", description = "Scans indicate structure has become inoperable. No possibility for repair.\n\nTitan Keeper Hezrel's database fully restored. Believe solution may be within data.\n\nRequire time to scan data, find solution to contain Old God corruption.\n\nStand by while Titan Keeper Hezrel scans databanks for solution.", objectives = "" }
WordHunterWoW_QuestEN[49985] = { title = "Return to Gloom Hollow", description = "Old God G'huun behind destruction of this seal. Commanding blood trolls to destroy final one within Zuldazar.\n\nTitan Keeper Hezrel must aid in destruction of blood trolls. Cannot allow Zuldazar seal to be destroyed and G'huun to be freed.\n\nMust leave interior of Atul'nazman. Meet Titan Keeper Hezrel outside of temple, will help return to Gloom Hollow.\n\nWhen task is complete, Titan Keeper Herzrel must establish contact with other keeper within G'huun containment chamber.", objectives = "" }
WordHunterWoW_QuestEN[49991] = { title = "Featherfeet's Fun Falling's Fun Fee!", description = "Welcome to Zuldazar, my fine {race} friend!\n\nI've explored every inch of this wonderful city with my own two feet. And let me tell you, they're tired!\n\nThat's why I've decided to provide a service to my powerful friends in the Horde: Featherfeet's Fun Falling!\n\nNow, I know what you're thinking. You nomrally associate falling with screams, pain, and an untimely death.\n\nBUT NOT WITH FEATHERFEET!\n\nFor a small one-time fee, I'll make sure you always float down this ziggurat shrouded in safety and fun.", objectives = "" }
WordHunterWoW_QuestEN[49995] = { title = "Fabricated Fabrications", description = "There was somethin' off with the ship we were building in the yard. I never saw the blueprints, but I've built enough ships in my day to know it wasn't business as usual.\n\nThey've kept all the pages under tight guard in the Brineworks up the road lately. Full on militia.\n\nIf you can get your hands on enough of them pages, we oughta be able to figure out what Lord Stormsong and his boys are schemin'.", objectives = "" }
WordHunterWoW_QuestEN[49996] = { title = "Rearmament", description = "The people of this valley have true hearts, {name}. They're eager to take back control of their home.\n\nWe have to help them.\n\nThe Brineworks up the road from here supplies most of House Stormsong's weapons. Our movement here could make great use of them.\n\nIf you can collect enough to go around, I'll go over some basic training with our friends here.", objectives = "" }
WordHunterWoW_QuestEN[49997] = { title = "Storm's Judgment", description = "When I opened my mind to the currents during the ritual, I felt the presence of a member of Lord Stormsong's innermost circle.\n\nWavespeaker Reid. If anyone can locate the missing fleet, it is him.\n\nI will not stand by while my brothers move against our own people. Oaths be damned.\n\nWe must force Reid to see reason.", objectives = "" }
WordHunterWoW_QuestEN[49998] = { title = "Voices Below", description = "The others forged ahead to Port Fogtide. I doubt they will receive a warm welcome. \n\nWe are to meet them there. However, there is something I must do first.\n\nDespite Reid's retreat I still feel a terrible darkness nearby; I wish to listen to the tides for answers. I would appreciate your joining me in case more danger strays into our path.", objectives = "" }
WordHunterWoW_QuestEN[50001] = { title = "Breaking Hag", description = "The town is overrun! \n\nThe guards have fallen back and what is worse, some of the villagers have been twisted by the witches' magic. They are little more than wretched beasts blindly following orders. \n\nWe must release these poor souls and slay the monsters that twisted them!\n\nSee what you can do to cut down the numbers of monsters in town!", objectives = "" }
WordHunterWoW_QuestEN[50002] = { title = "A Very Precious Cargo", description = "We weren't the only ship in our convoy to get caught up in this mess. Our flagship ran aground to the east. It was holding a very precious cargo and I need you to bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[50003] = { title = "The First Watch", description = "As you can see, the coven has conscripted my own guardsmen into their service. Though I am loath to battle my own, these men are too corrupted by the coven's magic to be saved.\n\nFor them, death is the only mercy we can give.\n\nThe Inquisitors and I can handle the regiment stationed outside. We will need you to find and take out their leader.\n\nYour Inquisitors await your command, {class}. Are you ready to take the tower?", objectives = "" }
WordHunterWoW_QuestEN[50005] = { title = "Hold My Hand", description = "Take me to my daddy this instant!\n\nWaaaait! You have to hold my hand...", objectives = "" }
WordHunterWoW_QuestEN[50026] = { title = "Save Our Shipmates", description = "Oh, thank the stars! Our ship ran aground and our men are in desperate need of help.\n\nFind Henry Hardwick down the hill at the shipwreck. He stayed behind to try and help the others.", objectives = "" }
WordHunterWoW_QuestEN[50036] = { title = "A Weapon of Old", description = "I've been studying the parchment Lady Lucille sent with you and have translated some of the older language. \n\nThey called it \"Liquid Fire\" and it was used to \"burn away the Drust\". Using this as a basis I believe we can adapt it to our needs. This is a complex recipe, but it just so happens I have everything we need to make this potent alchemical weapon!\n\nI will need your assistance in creating this. Would you be so kind as to help?", objectives = "" }
WordHunterWoW_QuestEN[50041] = { title = "A Pocketful of Shells", description = "You see the problem? No you don't.\n\nProblem isn't all these dang quilboar. Quilboar I can shoot all day. Been shootin' em all my life, since my pappy gave me my first gun. \n\nProblem is these pigs are tough. Tougher'n they've been before. Can't kill em like I used to, see? My new modified bullets just get stuck in them and they refuse to die!\n\nHere, take my knife. Go out there and kill some of the quilboar and get my ammo back. Then I can shoot the rest! I won't stop 'till there's none left to shoot!", objectives = "" }
WordHunterWoW_QuestEN[50043] = { title = "Archaeological Efficiency", description = "Miss Tae'shara and I share a passion for uncovering hidden secrets and a deep, abiding respect for this ancient land.\n\nThat said! If we were to continue at the pace to which she is accustomed, the Alliance would overtake us before we could make a single discovery. \n\nIt is time to expedite our survey.\n\nThe ruins hide many fossils. Take a beacon and use it to summon one of my sweepers. It will clear away the topsoil and allow you to collect samples.\n\nGather what you can- we can assemble them later.", objectives = "" }
WordHunterWoW_QuestEN[50044] = { title = "Archaeological Efficiency", description = "Suppose I owe the lass her bones if I'm tae be monopolizin' yer time. And I will be.\n\nGo on out into the ruins an' use this here stone to call one of my rumbly elemental friends. They'll blast away any dirt 'tween you an' the fossils.\n\nWe could go about this the ol' fashion way, but do you really want to spend all day digging? Course ye don't.\n\nAcadia will see that a little efficiency gets everyone what they want.", objectives = "" }
WordHunterWoW_QuestEN[50046] = { title = "It's a Sabotage", description = "The Horde has wasted no time in shamelessly extracting this mysterious ore from the great wound.\n\nLuckily for us, goblin engineering is not nearly as sophisticated as what we create in Gnomeregan! All it takes is a little bit of old fashioned dynamite to completely disable a goblin shredder.\n\nWhat unsophisticated machinery!\n\nTake these dynamite bundles and plant them on the inactive shredders around the mining camp.\n\nIt'll take those greedy goblins weeks to get back up and running again!", objectives = "" }
WordHunterWoW_QuestEN[50047] = { title = "Free Samples", description = "The crown has ordered SI:7 to infiltrate the goblin mining operation and collect any information we can find on this mysterious new substance.\n\nMy agents have infiltrated the camp, but the clock is ticking and we need to get our hands on some extracted ore samples fast.\n\nIn other words, I need someone who can take the direct approach. Someone who can handle a fight against overwhelming odds and come out alive.\n\nTake the ore samples to Khargus Stonemantle for analysis when you return.", objectives = "" }
WordHunterWoW_QuestEN[50048] = { title = "The Seething Shore", description = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits.\n\nIt is vital that we secure the island before the Horde learns of its existence.\n\nMaster Mathias Shaw is personally leading the expedition force and has requested that you report for duty. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[50049] = { title = "The Speaker's Perspective", description = "Sargeras has left a scar upon our world, {name}. A scar that will not soon heal...\n\nIt appears that the scars between the Alliance and Horde have yet to heal as well.\n\nToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.\n\nI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.\n\nThe letter contains information that may prove valuable to him.", objectives = "" }
WordHunterWoW_QuestEN[50052] = { title = "No Spies Allowed", description = "Hey {name}, I'm glad you're here.\n\nI'm in way over my head! Killer bugs, a strange substance... that GIANT sword sticking outta the ground... I don't have a good feelin' about this place!\n\nTo make matters worse, I've been gettin' reports of Alliance spies snoopin' around the camp!\n\nLook kid, the Dark Lady has plans for this mysterious ore and I ain't going to be the one to dissapoint her, know what I mean?\n\nGet over to the mining camp and take out those SI:7 spies before they ruin the whole operation!", objectives = "" }
WordHunterWoW_QuestEN[50053] = { title = "Lazy Prospectors!", description = "I've been around long enough to know you can never trust a goblin with an orc's work.\n\nGallywix and his cartel may be serving the warchief, but we need to keep a close eye on them if we're going to get anything done!\n\nI've already noticed many of the workers loafing about and sleeping on the job. The Horde does not tolerate laziness!\n\nGet out there and put those lazy prospectors in their place!", objectives = "" }
WordHunterWoW_QuestEN[50054] = { title = "The Seething Shore", description = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits.\n\nIt is vital that we secure the island before the Alliance learns of its existence.\n\nNathanos Blightcaller is personally leading the expedition force and has requested that you report for duty. Go with honor!", objectives = "" }
WordHunterWoW_QuestEN[50055] = { title = "The Speaker's Perspective", description = "Sargeras has left a scar upon our world, {name}. A scar that will not soon heal...\n\nIt appears that the scars between the Alliance and Horde have yet to heal as well.\n\nToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.\n\nI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.\n\nThe letter contains information that may prove valuable to him.", objectives = "" }
WordHunterWoW_QuestEN[50058] = { title = "The Witch's Pet", description = "I've seen her! The witch!\n\nEvery once in a while she comes down to the cave, checking on her pet. I've never seen a spider so large!\n\nShe spreads her spell, cursing all of the animals in these woods to follow her command and attack us.\n\nThe broodmother laid all these eggs, and they're hatching into more possessed beasts!\n\nTake her out, and perhaps the infestation will stop.", objectives = "" }
WordHunterWoW_QuestEN[50059] = { title = "Can't Hear A Thing", description = "These snake wenches show up and everyone loses their minds! All my men are head over heels for these things. Personally, I don't see it. I mean, I sort of get the appeal, but the wings for arms and snake tails are a big turn off.\n\nThere's a big one in a cave to the east. She's got a whole heap of suitors. I need them back to work. Go give her a wallop and get everyone back here.", objectives = "" }
WordHunterWoW_QuestEN[50063] = { title = "Fighting With Fire", description = "Excellent! Now that we have these lovely Liquid Fire flasks prepared we have one last thing to do:\n\nTest them out!\n\nThere are some of those large abominations lurking about in the woods above my home. I think they would make excellent test subjects for our little alchemical experiment, wouldn't you say?", objectives = "" }
WordHunterWoW_QuestEN[50064] = { title = "Don't Go in the Basement", description = "We checked everywhere... well, <gulps> everywhere except the basement.\n\nB-b-but, dad told me never to go down there.\n\nHe said it's dark, scary, and dangerous to go alone... I could be eaten by a brue!\n\nI don't even know what that is, but I don't wanna be eaten! \n\n{name}, do you think you could go down first?", objectives = "" }
WordHunterWoW_QuestEN[50065] = { title = "A Reason to Stay", description = "<You find a pocketwatch on the ground. It is dirty, but still works. It was taken care of well.\n\nPerhaps there are other objects that Goldfield wasn't able to grab before he had to hole up in his house. He might appreciate it if you brought them to him.>", objectives = "" }
WordHunterWoW_QuestEN[50069] = { title = "Goldfield's War", description = "I'm not leaving. I'm never leaving.\n\nThose quilboar, they killed them. I gave her the watch, told her to hurry. Grab our boy and get to the house while I got the gun...\n\n<Goldfield is choking back tears.>\n\nI won't leave. Our family has our roots here. They would want me to stay, don't you understand? This is our farm. My boy, he wanted to join the militia. I made him a sword...\n\n<Goldfield takes a deep breath.>\n\nNow you know. Help me retake my farm. Grab a gun and let's kill every last one.", objectives = "" }
WordHunterWoW_QuestEN[50070] = { title = "Detective Mildenhall", description = "Hmm... okay, okay, let's think.\n\nIf you were my dad and you accidentally set loose a bunch of honey monsters all over the place, what would you do?\n\nWell, okay, you would probably beat all of them up. But he probably ran away.\n\nIf he left in a hurry, maybe he left something for us to find.", objectives = "" }
WordHunterWoW_QuestEN[50071] = { title = "For the Light!", description = "The Lightforged Draenei will be happy to join the Alliance.\n\nOur cause is now yours, {name}.\n\nLet us return to Stormwind. Captain Fareeya will speak with our people.", objectives = "" }
WordHunterWoW_QuestEN[50074] = { title = "Brutal Boost", description = "The Aggression Formula is ready and I need you to inject Ben'jin with it. \n\nLet's show the world, and the witch doctor, that well researched, dramatically overpowered, double-blind, peer-reviewed, super goblin science is the right way to do, uh, pretty much anything!", objectives = "" }
WordHunterWoW_QuestEN[50076] = { title = "Rally the Warriors", description = "We have learned so much and came so far thanks to you and de Horde, but all of it will amount to nothing if de blood trolls defeat us here.  \n\nWe've all worked hard since we first set foot within dis accursed swamp, without a chance to even get any sleep or have a decent meal. Dey are some of de finest soldiers I've ever encountered, but even dey have their limits.  \n\nLet us remind dem what we are fighting for!", objectives = "" }
WordHunterWoW_QuestEN[50078] = { title = "Undying Totems", description = "De blood trolls are putting up quite de fight. Dey are raising de very dead to go against us!\n\nTheir necromancers are raising de dead with de help of totems fueled with blood magic. Destroying dem should take de pressure off our troops.", objectives = "" }
WordHunterWoW_QuestEN[50079] = { title = "Boom goes the Bomb", description = "Just look at 'em... those blood trolls are holed up pretty good down there in that fortress of theirs. Multiple defensive lines, lots of equipment, they got everything.\n\nThey're completely unprepared for us! I almost feel sorry for 'em!\n\nLet's start off by showing 'em what we think of their cute attempts at making barricades. Here, take these smoke grenades and put a signal right on top of them. We'll see how well they hold up to high explosives!", objectives = "" }
WordHunterWoW_QuestEN[50081] = { title = "The Road of Pain", description = "My people continue to be captured and hauled into de blood trolls' village for de slaughter, to be used as fuel for their dark rituals. \n\nJust ahead, I can see some of de captives who fell along de path. I hear their cries as de blood trolls perform their vile rituals upon dem.\n\nWe cannot leave my people to die in de swamp, {name}!\n\nTake dese bandages and save any Zandalari you encounter down dere.", objectives = "" }
WordHunterWoW_QuestEN[50082] = { title = "Target of Opportunity", description = "It seems our actions here have not gone unnoticed, {name}. I feel a dark presence ahead.\n\nAteena is near! \n\nDis is our chance! If we strike now, we can deal a huge blow to de blood trolls!\n\nWe must move!", objectives = "" }
WordHunterWoW_QuestEN[50083] = { title = "The Crawg Ma'da", description = "No matter what we do, as long as dem blood trolls have their village here, dey gonna be a threat.\n\nWe gonna put an end to dat threat!\n\nAmaka be da strongest blood troll I ever seen, and she be right across da way there. She be feedin' da bodies of da Zandalari ta her pet crawgs, makin' dem big, fat, and deadly. It be time for revenge, and we be doin' it wit' da help of her own pets.\n\nGo kill a crawg and cut its poison gland out of its belly. With it, ya can weaken Amaka and put an end to her.", objectives = "" }
WordHunterWoW_QuestEN[50084] = { title = "Back On Your Feet, Soldier", description = "I figured any soldiers we be coming across might be wantin' some revenge, so I brought along some extra weapons just in case.\n\nSee up ahead? Dem cages be full of trolls awaitin' der turn ta die. We gonna swoop in der and be da answers to der prayers!\n\nGo and arm as many of dem as ya can, revenge gonna be sweet!", objectives = "" }
WordHunterWoW_QuestEN[50085] = { title = "A Message of Blood and Fire", description = "Look at what I be findin' here. Dis one had a magic wand in his hand.\n\n<Rokhan shuts his eyes for a moment.>\n\nMmmmm... it be warm. Mojo of fire be within. Perfect!\n\nTake dis ting an' give 'em a taste of their own firepower.\n\nBurn da whole village down!", objectives = "" }
WordHunterWoW_QuestEN[50087] = { title = "Ateena's Fall", description = "You have proven to be a much greater ally dan I could have ever hoped. Thanks to you and your Horde, we have come dis far. Now, there is only one thing dat remains. \n\nWe must confront de leader of de blood trolls and put an end to their dark plot once and for all.\n\nWithout Ateena's mojo to protect it, we can finally destroy dat monstrosity of theirs before it can be unleashed upon Zuldazar. \n\nYou know what must be done. \n\nFirst, I must prepare myself. Go. I will join you when de battle has begun.", objectives = "" }
WordHunterWoW_QuestEN[50088] = { title = "Golden Fields Forever", description = "I can take care of the rest. That ettin would have given me trouble if I was by myself, so you have my thanks.\n\nI would ask you for one more favor.\n\nMy wife, she loved the carnations that grow by the water's edge. If you could gather some, there's a nice spot under a tree by the river. We loved to go there when the sun set after our days in the fields.\n\nOur boy would run around, catching bugs, making reed whistles...", objectives = "" }
WordHunterWoW_QuestEN[50090] = { title = "Building Defenses", description = "We'll be able to push those monsters back now, but my defenders won't stand a chance unless we build a forward barricade for protection.\n\nThere should be plenty of lumber to build a barricade near the entrance to town.", objectives = "" }
WordHunterWoW_QuestEN[50092] = { title = "Curiously Strong", description = "I imagine the fires spread while I was down here, yes? First order of business then; making sure the town doesn't burn down! Help solve that problem and I shall be free to assist you in... whatever it is?\n\nLet's see... Yes! Here! Take these. They proved to be bit too... intense for most people, but you seem like a stout sort.\n\nJust be sure you're facing the fires when you use them, and I'm certain those fires will be out in no time!", objectives = "" }
WordHunterWoW_QuestEN[50110] = { title = "Bearers of Bad News", description = "We must report this attack to Lord Admiral Katherine Proudmoore and prove to her that Lady Ashvane is behind it.\n\nIt won't be easy... Lady Ashvane and Katherine Proudmoore have been close friends for years.\n\nQuickly, let us make for Boralus!", objectives = "" }
WordHunterWoW_QuestEN[50111] = { title = "Totems, Totems, Totems!", description = "<This totem pulses with energy, releasing it into the nearby idols and thorns.\n\nIt looks rather fragile... It would be a shame if something happened to it.>", objectives = "" }
WordHunterWoW_QuestEN[50112] = { title = "Casting the First Stone", description = "Hey dere {name}, gimme a hand with dis, would ya?\n\n<Kumali motions you over to her.>\n\nI got dis recipe dat I've been trying to remember de rest of, but I'm having de hardest time coming up with de right ingredients.\n\nYa see, my partner ran off with de other half of de recipe on account of a disagreement we had. But dis stone, it's a treasure like no other.\n\nGrab some vials and start mixing dese ingredients together. Let's see if dey are de right ones.", objectives = "" }
WordHunterWoW_QuestEN[50113] = { title = "Ocular Extracts", description = "So dere's a creature in dese lands whose eyes are perfect for alchemical recipes.\n\nDey might just be de thing we need to finish dis project. Although, I don't remember seeing dem on de full recipe list de last time I saw it, ya see... But my memory isn't quite what it used to be.\n\nGah! I'm rambling too much. Get me some eyes, will ya, {name}?", objectives = "" }
WordHunterWoW_QuestEN[50114] = { title = "Hammering Out Information", description = "I guess you noticed it requires a special anvil to make it. And I suppose you want to know where to find a Khaz'gorian Smithing Anvil?\n\nWell, I don't know where you can find one, not to mention I never said you'd be able to actually craft the dang thing.\n\nNow if you wouldn't mind, I have more of these recipes to sell.", objectives = "" }
WordHunterWoW_QuestEN[50115] = { title = "Changing the Scenery", description = "Or maybe de problem is dat we don't need regular reagents. Maybe we need something dat only comes from being transmuted.\n\nAnything's worth a shot at dis point. Here is a recipe my old partner left behind.\n\nHe used to go out to de Slough and change de shrubs into bubbles, ya see.\n\nWhy, you might ask? 'Cause he loved transmuting everything. Part of de reason we never saw eye to eye.\n\nAnyways, bring me back some of dose bubbles and we'll see if we can use dem to make dis stone.", objectives = "" }
WordHunterWoW_QuestEN[50116] = { title = "A Possible Solution", description = "None of dese things are working. I can't believe I'm saying dis, but I think you're gonna have to find Zukashi.\n\nMaybe you could convince him to give up de other half of de recipe. He's pretty full of himself, but he isn't unreasonable.\n\nLast time I heard, he's staying in Nazmir near Gloom Hollow. Maybe it's best to tell him dis isn't about me.", objectives = "" }
WordHunterWoW_QuestEN[50117] = { title = "A Deathly Draught", description = "De first thing I'd like you to do for me is to gather some deathshroom.\n\nDon't worry if you're not skilled at herbalism, they're very easy to pick. Dey typically grow where death lingers in the air.\n\nI'd try to de Frogmarsh to de southeast. De trolls dere have been making sacrifices of de creature dat inhabit de area.", objectives = "" }
WordHunterWoW_QuestEN[50118] = { title = "A Stone's Throw", description = "Now dis ingredient you might have some fun getting, little mixah. I'm gonna give you dese stones. They're able to turn things into other things.\n\nDose blood trolls, de ones giving de rest of us a bad name? Dey drink de weirdest things and it taints their bodies.\n\nI need their blood to finish my work here, but without de taint. Dese stones will turn dem into weaker creatures. Although, sometimes de stones turn dem into other things...\n\nBe careful with dem.", objectives = "" }
WordHunterWoW_QuestEN[50119] = { title = "Chemically Compounded", description = "Now dat I have everything I need, I can finish dis project. My latest transmuation will be my finest yet!\n\nBut dis is not de place to test it. It could draw too much attention.\n\nIf you want to see it for yourself, little mixah, meet me to de north. Dere is a cave dere dat should be a safe spot for testing dis out.", objectives = "" }
WordHunterWoW_QuestEN[50120] = { title = "A Recipe for Success", description = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for.\n\nAn odd signature completes the recipe, signed, \"Silas Darkmoon\".\n\nKumali should be very pleased to see this once again.", objectives = "" }
WordHunterWoW_QuestEN[50121] = { title = "Casting the First Stone", description = "Would you mind helping me out with something, {name}?\n\n<Elric motions you over to him.>\n\nYou see, I have this recipe that, well, I only have half of currently. I've been trying to remember the other half but just can't seem to recall it.\n\nMy EX-partner tore the recipe and ran off with the other half over a disagreement we were having. But the stone it makes is invaluable.\n\nHow about you grab some vials and start mixing the ingredients on this list. Perhaps together we can figure this out.", objectives = "" }
WordHunterWoW_QuestEN[50122] = { title = "Ocular Extracts", description = "My next idea involves a creature whose eyes are useful for certain alchemical recipes. At least for potions they are.\n\nHopefully they're just what we need for this and there aren't any further... miscalculations. Although, I don't entirely recall seeing them on the recipe's ingredient list... but my memory isn't exactly as good as it used to be.\n\nOh, you caught me rambling. How about you get those eyes and I'll start making the preparations for them.", objectives = "" }
WordHunterWoW_QuestEN[50123] = { title = "A Recipe For the Ages", description = "Yo, {name}, over here! You've look like you've been hammering away for a while. I can smell the flux on ya!\n\n<Grix gives you a wide grin.>\n\nListen, I've got a recipe for the most amazing blacksmith hammer you've ever laid your eyes on. And I'd be willing to let it go for a bit of ore.\n\nRevlis ore to be exact. It's a little rare, but you can find plenty of it over in Gol Koval in Drustvar. The elementals there are practically made of it.\n\nBring me back a haul of it, and the recipe's yours!", objectives = "" }
WordHunterWoW_QuestEN[50124] = { title = "Changing the Scenery", description = "The stone this recipe becomes is a transmutation stone. What if the missing reagents to make it come from something that's gone through the transmutation process?\n\nI'm willing to try anything at this point. Here's an old recipe my ex-partner devised.\n\nHe used to go out to Stormsong Valley, just south of the Highland Flats and change the shrubs there into bubbles.\n\nBring back some of those bubbles and we'll see if they're what we've been missing.", objectives = "" }
WordHunterWoW_QuestEN[50125] = { title = "A Possible Solution", description = "Nothing appears to be working. I can't believe I'm proposing this but I actually think we need to contact Quintin.\n\nWell, you should, as I doubt he'll speak to me. Perhaps you could convince him to part with the other half of the recipe?\n\nLast time I heard, he was staying in Drustvar near Arom's Stand. There's a lot of alchemists in those parts, but he shouldn't be too hard to find.\n\nBest not to tell him I sent you. He may not be as forthcoming with the recipe.", objectives = "" }
WordHunterWoW_QuestEN[50126] = { title = "A Deathly Draught", description = "The first thing I'd like you to do for me is to gather some deathshroom.\n\nDon't worry if you're not skilled at herbalism, they're very easy to pick. They typically grow where death lingers in the air.\n\nI'd try to the Crimson Forest to the south. The creatures that have overrun it seem to be covered in deathly magics.", objectives = "" }
WordHunterWoW_QuestEN[50127] = { title = "A Stone's Throw", description = "You may enjoy getting this next reagent for me. I have some special stones that have transmutative qualities, especially on living things. It's not too unlike the one you're trying to make.\n\nThe witches that plague these lands are imbued with magic. As is their blood.\n\nI need their blood to finish my latest project, but in an altered form. These stones should turn them into weaker creatures. Although, sometimes the opposite occurs...\n\nI'd recommend handling them with care.", objectives = "" }
WordHunterWoW_QuestEN[50128] = { title = "Chemically Compounded", description = "That appears to be everything. This latest transmutation will be my finest yet. And your prize waits at its completion, apprentice.\n\nBut I don't believe this is an appropriate place to test it out. It may draw too much attention.\n\nThere's a cave not terribly far from here which would prove to be a more suitable setting for such a test.\n\nMeet me there when you're ready to witness why transmutation is the only branch of alchemy worth learning.", objectives = "" }
WordHunterWoW_QuestEN[50129] = { title = "A Recipe for Success", description = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for.\n\nAn odd signature completes the recipe, signed, \"Silas Darkmoon\".\n\nElric should be very pleased to see this once again.", objectives = "" }
WordHunterWoW_QuestEN[50130] = { title = "A Friendly Gesture", description = "Life in the marsh has not been easy, {name}. We want to live in harmony with those that call it home, but our enemies out here threaten our existence.\n\nWork with us. Help the people of Sporeggar thrive.", objectives = "" }
WordHunterWoW_QuestEN[50131] = { title = "An Outside Perspective", description = "Thank you for everything you have done for my people, but they are still scared of outsiders.\n\nFight the bog lords and rescue the spore sacs in the Spawning Glen. The future of my people is at stake!", objectives = "" }
WordHunterWoW_QuestEN[50134] = { title = "Gadgets and Gizmos Aplenty", description = "The militia may have given up on us, but we haven't given up on me!\n\nI'm a bit of a tinker, and I find that my harvest golems are better than any hired help I've ever had. They just need regular maintenance to keep running.\n\nOf course the Briarback are now taking over my fields, and my farmhands have gone into disrepair.\n\nIf you head out into the fields, can you grab the inner mechanisms from any of them that you find? That will stop them from exploding as well as help me plan my revenge.", objectives = "" }
WordHunterWoW_QuestEN[50135] = { title = "Stop Vining!", description = "You may have noticed that the fields are a little... unstable right now.\n\nThe Briarback have been busy, growing those large bramble vines and boring tunnels underneath the farm. The vines have always been an important part of their borders, and they're expanding!\n\nGo down into the lower area and see if you can find who or what is making those vines grow. There's no way that they're growing like that naturally. If we can stop the vines we can retake this area!", objectives = "" }
WordHunterWoW_QuestEN[50136] = { title = "Farming Stimulator", description = "The plants have gone amok since you defeated their masters! Don't worry though, I've got a plan.\n\nI've been busy fixing up one of the farmhands that didn't go completely haywire. It should have enough juice for one more trip through the fields.\n\nWe've got some serious technology in these harvesters. Their tools should be more than enough to take care of some small plants and even a couple quilboar.\n\nWhat do you say? You up for some farming the Stormsong way? Hop on in and get to work!", objectives = "" }
WordHunterWoW_QuestEN[50138] = { title = "The Battle of Bloodfire Ravine", description = "It is time to strike out and end de blood troll threat once and for all!\n\nWe travel back to Bloodfire Ravine, and dis time it is de blood trolls who will be sent running.\n\nMount up, and together we will show dem we are a force to be reckoned with!", objectives = "" }
WordHunterWoW_QuestEN[50139] = { title = "The Missing Link", description = "<Though burned, portions of the note in the architect's hand remain legible.>\n\nThey are... everywhere... disguised...\n\nEncrypted... blueprints...\n\nCipher...\n\nPontus... watching me...\n\n<The cipher must be needed to read the ship blueprints. It seems Pontus is the likely holder.>", objectives = "" }
WordHunterWoW_QuestEN[50149] = { title = "A Weather Eye", description = "It would be wise to get a lay of the land before we put together a plan of action. \n\nInquisitor Notley is an expert falconer, and a reliable scout. He utilizes an ancient relic to see through the eyes of his falcon, allowing him to survey great distances. \n\nUnfortunately, Notley was injured during the fighting. Nothing serious, but it's left him unable to concentrate enough to control his falcon.\n\nPerhaps you could help?", objectives = "" }
WordHunterWoW_QuestEN[50150] = { title = "Setting the Mood", description = "De voodoo love incense and romantic meal are ready, {name}. Take dem and place dem at de feet of Maka'fon. \n\nQuickly, if you could. Dat smell is... overwhelmingly, horribly, disgusting. \n\nCould you move any faster? \n\nAway. \n\nFrom us.\n\nFor de sake of de brutosaurs, of course.", objectives = "" }
WordHunterWoW_QuestEN[50151] = { title = "A Steady Ballast", description = "The Armory presents us a ripe opportunity, {class}... one I suggest we take.\n\nIf this battle were to draw out, we have little means to repair our arms and armor. A blacksmith is invaluable to any war effort, and Ballaster is one of our best.\n\nThe Armory is but a short ride from here. I suggest you get to Ballaster before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[50152] = { title = "Digging for Scraps", description = "Well met, {class}.\n\nI hope you don't mind that I took the liberty to scout ahead and assess the situation at the armory.\n\nThe good news is that there still seems to be some salvageable arms left in the armory. The bad news, of course, is that the coven is after them as well.\n\nAdditional weapons could be a great boon to our cause. I recommend we take all we can carry.", objectives = "" }
WordHunterWoW_QuestEN[50154] = { title = "They Say It's a Delicacy", description = "A romantic meal is de way to set up an evening for love. Dis is true for us, so why not for Maka'fon? Bring her something rare and pleasing to her palate. \n\nDiemetrodons near de water eat hard seed pods and partially digest them. With a little voodoo, something magical can happen to de pods. It may be disgusting to you and I, but de brutosaurs consider it a rare delicacy. Such is life. \n\nDere are plenty of diemetradons, so some must die dat de brutosaurs might live. Such is de purpose of death.", objectives = "" }
WordHunterWoW_QuestEN[50157] = { title = "There's Gold in Them There Fields", description = "We've still got some folks missing, and I could use your help finding them.\n\nWhile Brennadam is now secure, I worry for some of our farms closer to the quilboar kraul. We relied on the militia in the past to keep the quilboar back, but now that they've retreated to the east I worry that our outlying farms are in danger.\n\nGoldfield's farm is almost directly south of us, up the hill by the falls. While it's not surprising that he hasn't left, I would feel better if you checked in.", objectives = "" }
WordHunterWoW_QuestEN[50158] = { title = "Checking Out the Collapse", description = "If you've got a minute, there's a farmer out there who hasn't made it back yet.\n\nName's Burton and he's out by a farm right next to Briarback Kraul. If the quilboar were to strike out, his farm is one of the first in their way.\n\nI haven't heard anything from Burton. He mostly relied on his mechanical farmers to help him, so we don't know the situation out there.\n\nHead to the west and keep an eye out for him, would you?", objectives = "" }
WordHunterWoW_QuestEN[50161] = { title = "Recovering Raimond", description = "The map we found earlier had some red markings, near the flower field. \n\nDo you think you could go up there and look for dad?\n\nI'm going to stay here and check out the rest of this stuff. \n\nI'd go with you... but, I'm sort of allergic to bees.\n\nOh, and take his boot. Just in case!", objectives = "" }
WordHunterWoW_QuestEN[50162] = { title = "Sticky Situation", description = "The scientific breakthroughs I've made, marvelous, absolutely marvelous... I'm so close to perfecting the formula!\n\nThe way the honey grows and crystallizes, simply beautiful. Well, as you can see, that's also part of my current predicament.\n\nPerhaps you can lend me a hand? Just fetch some royal jelly from the hives outside.\n\nOh, don't worry about the bees, they are sweet, gentle things. \n\nThey don't sting... much.", objectives = "" }
WordHunterWoW_QuestEN[50165] = { title = "The Bee Team", description = "We need to put things in order, and the next item on the list is these blasted wendigos terrorizing the farm. \n\nIf we can cull their numbers, it should be enough to drive them off!\n\nI've synthesized a superb solution that might be just what we need to solvent this sticky situation!\n\nToss these bottles at your foes and our friendly little apoideas should come to help.\n\nWhatever you do, please don't spill any on yourself...", objectives = "" }
WordHunterWoW_QuestEN[50168] = { title = "Royal Succession", description = "I know, I know, okay... the farm is overrun by living honey and the bees have grown to massive proportions.\n\nI'll admit, things didn't quite go according to plan, but, extraordinary advancements in science do not come without some risk!\n\nI've been up here attempting to reduce aggression in the hive, an unfortunate side effect of my miscalculation, but I need another favor...\n\nYou're going to have to kill the Hive Mother and retrieve her stinger for me.", objectives = "" }
WordHunterWoW_QuestEN[50172] = { title = "Into the Crimsonwood", description = "Master Ashton has been taken into the forest. He isn't the only one. Mayor Royston's headcount came up short.\n\nIt seems our next steps are clear. We must go into the woods and save Master Ashton.\n\nMarten and I will sneak into the forest and meet you near some ruins further in.", objectives = "" }
WordHunterWoW_QuestEN[50173] = { title = "Precious Metals", description = "{class}, I have another objective we should consider. \n\nThe Bleak Hills Mine is not too far from our location. Though the miners there principally extract iron, they do on occasion find silver among the veins.\n\nWe do not know the current state of the mine, but it's unlikely that the coven has passed it over. However, it would be worth braving whatever dangers lie there to recover some silver to use against them.", objectives = "" }
WordHunterWoW_QuestEN[50174] = { title = "All Wrapped Up", description = "While I was able to get out of the mine, some of my friends weren't so lucky.  I saw those spiders wrap them up in their webs... probably to save them for a snack.\n\nIt was terrible, but all I could do was run.\n\nWill you help them?", objectives = "" }
WordHunterWoW_QuestEN[50175] = { title = "An Eight-Legged Curse", description = "Some terrible old hag unleashed a swarm of these horrible spiders in the mine!  I was barely able to make it out alive, but they've got me surrounded!\n\nYou can't leave me here! Please kill those things!", objectives = "" }
WordHunterWoW_QuestEN[50177] = { title = "Hold The Barricade!", description = "{name} they're rallying for a heavy assault!\n\nWe'll need to defend these barricades from attack! Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[50226] = { title = "The Source of Power", description = "Although the silithid disappeared for a time immediately following the destruction of Silithus, they have recently returned from beneath the ground.\n\nThese new silithid seem stronger than before!\n\nMy hypothesis is that the silithid are feeding on some kind of power source beneath the blade of Sargeras.\n\nI've been tasked with studying the effects that this mysterious power is having on the silithid hives.\n\nBring me as many intact silithid brains as you can carry and I'll begin the research!", objectives = "" }
WordHunterWoW_QuestEN[50227] = { title = "Larvae By The Dozen", description = "How did the silithid survive the blade of Sargeras? I'm perplexed!\n\nI've never encountered a species that can adapt to changes in the environment as quickly as the silithid can.\n\nThe larvae, or broodlings as they are often called, can evolve into a variety of silithid creature types based on the needs of the hive.\n\nIs it the hive mind that signals the evolutionary development of the larvae, or is some environmental factor at play?\n\nScience must find the answer!", objectives = "" }
WordHunterWoW_QuestEN[50228] = { title = "The Twilight Survivor", description = "Silithus used to be overrun with members of the Twilight's Hammer.\n\nThe cult was presumed to be exterminated, but it has always survived in the shadows. Their numbers have dwindled, but the cult remains no less fanatical than at their peak.\n\nMost of the cultists here were destroyed by Sargeras in the attack, but a few still remain. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.\n\nWe cannot let Michiel rally the remaining survivors to action. He must be stopped!", objectives = "" }
WordHunterWoW_QuestEN[50229] = { title = "A Wee Bit O' Cloth", description = "{name}, is that you I hear rustlin' about out there? It's me, Angus Stormbrew!\n\nThere are cultists everywhere, so ye best keep yer voice down. Lean in close and cover yer nose while we talk!\n\nThis is the only outhouse in all o' Silithus! Trust me I spent hours lookin' all through the night. I decided to sneak in for a wee drop-off before the cultists woke up, but I've got a uhh problem...\n\nThere's no cloth to... you know...\n\nSee if ye can find me a wee bit o' cloth and sneak it in through the door!", objectives = "" }
WordHunterWoW_QuestEN[50230] = { title = "The Source of Power", description = "The silithid are all riled up and stronger than ever!\n\nMy guess is that they are feeding off of some kind of power beneath the ground. Probably near the blade of Sargeras!\n\nI've been ordered to study the effects that this mysterious power is having on the sillithid.\n\nBring me as many intact silithid brains as you can carry and I'll begin the research!", objectives = "" }
WordHunterWoW_QuestEN[50231] = { title = "Larvae By The Dozen", description = "How did the silithid survive the blade of Sargeras?!\n\nI've never encountered a species that can adapt to changes in the environment as quickly as the silithid!\n\nThere's gotta be a way to tame these suckers! Harness their evolutionary biology for our profit!\n\nWe gotta start training 'em young! Forget about the old crusty adults, we need babies!\n\nSteal me as many of the silithid larvae as you can carry, and I'll find a way to train 'em!", objectives = "" }
WordHunterWoW_QuestEN[50232] = { title = "The Twilight Survivor", description = "This land was once overrun with members of the Twilight's Hammer.\n\nThe cult was presumed to be exterminated, but darkness always survives in the shadows.\n\nMost of the cultists were destroyed by Sargeras in the attack, but a few yet live. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.\n\nWe cannot let this fanatic rally the remaining survivors to action! Bring me his head!", objectives = "" }
WordHunterWoW_QuestEN[50235] = { title = "No Safe Haven", description = "I brought Rastakhan to Zeb'ahari to hide him, {name}. I did not dream Zul's followers would find us so soon.\n\nDe people of Zeb'ahari are being hunted by those who answer to de prophet. I have brought dis upon dem by keeping de king in their village.\n\nHelp me save dem, {name}. Gather those who can still walk and send dem to me.\n\nI can do nothing for those who died, but we can still rescue de living.", objectives = "" }
WordHunterWoW_QuestEN[50238] = { title = "Bramblethorn", description = "I was playing with Lord and Lady Sharptooth when Papa made me come with him. I dropped poor Lord Sharptooth and one of those big mean monsters grabbed him! \n\nPapa said he'd try to get him back but he's been gone a long time. I think he got busy. Mama and all the adults are busy doing stuff for Mayor Royston.\n\nLady Sharptooth and I are really sad. Can you beat up that mean monster and save my dino?", objectives = "" }
WordHunterWoW_QuestEN[50239] = { title = "A Choice of Allies", description = "I was chosen to act as an ambassador to our new allies due to my experience with the pandaren joining the Alliance.\n\nI've made some notes about some potential allies that may be willing to join the Alliance.\n\nLearn more about them, then speak with me.", objectives = "" }
WordHunterWoW_QuestEN[50240] = { title = "A Slip of the Tongue", description = "<As you approach, the blind Zandalari motions at you impatiently.>\n\nIt sounds like ya be headed somewhere in a hurry, little weed!\n\nSit down and share a tale with an old troll before ya head out on ya next adventa.\n\nI went on many adventas with my pterrordax when I was young. Explored dis whole valley!\n\nMy pterrordax died many years ago, but...\n\n<Blind Tra'wala smiles mischievously.>\n\nSometimes at night, I steal da guards' snacks to trick dese old pterrordaxes into lettin' me ride again. Ha!", objectives = "" }
WordHunterWoW_QuestEN[50242] = { title = "A Choice of Allies", description = "As ambassador, it is my duty to bolster the Horde's ranks and strengthen our numbers in the face of danger.\n\nYour adventures have led you to many different people who can aid the Horde if we can convince them to join our cause.\n\nI've kept a record of the most promising potential allies. The choice of which to approach first is yours.", objectives = "" }
WordHunterWoW_QuestEN[50247] = { title = "The Mail Must Flow", description = "Due to all of the recent shenanigans, I'm running short on mailementals to sort letters.\n\nIt's a simple job, really - just toss the letter into the proper portal, where it will be whisked away to the far corners of Azeroth and beyond.\n\nI like to make a little game out of it. How many can you sort in one minute?", objectives = "" }
WordHunterWoW_QuestEN[50249] = { title = "A Boralus Triple Threat", description = "If Tallis honestly thinks that offing a few random soldiers is going to force us to give up Southwatch, he's in for a surprise. The reason why we haven't chased out the sorry troops in this camp is simply because we have more pressing plans.\n\nFernn has his lieutenants facing the Watch's cannons straight at Boralus as we speak. Those three are the real driving force of the attack.\n\n<The marine gives you a concerned look as he realizes what he said.>", objectives = "" }
WordHunterWoW_QuestEN[50250] = { title = "Posthaste", description = "", objectives = "" }
WordHunterWoW_QuestEN[50251] = { title = "Spell Bound", description = "<The villager is held captive by a binding rune. Destroying the rune should free the villager.>", objectives = "" }
WordHunterWoW_QuestEN[50252] = { title = "Mating Season Halftime", description = "Cala and I have both failed. Voodoo and science did not work. I am at a loss.\n\nI hope dat you can help us find a better path forward. De brutosaurs deserve a chance! \n\nPlease spend a little time with both of us. Perhaps you can find de way dat we cannot.", objectives = "" }
WordHunterWoW_QuestEN[50253] = { title = "An Improvised Arsenal", description = "I don't know much about blacksmithing, but I'm pretty sure this won't be enough silver to outfit all of the Inquisitors.  We will need to find another way to use this.\n\nLet us hope that Ballaster can come up with something... creative.", objectives = "" }
WordHunterWoW_QuestEN[50264] = { title = "Free the Farmhands", description = "We were running around trying to get the farm under control, but the bees, oh my goodness, the bees!\n\nThe giant monstrosities came out of nowhere and started dousing everyone in honey.\n\nI came up here to find Raimond, but before I knew it, I was covered too. \n\nThen, the strangest thing happened, the honey started growing around me!\n\nPlease, the other farmhands are still in trouble, you've got to help them!", objectives = "" }
WordHunterWoW_QuestEN[50265] = { title = "Saving Master Ashton", description = "I believe I see Master Ashton in a cage. He must be freed!\n\nThose witches with the long masks appear to be in charge. I bet they would have the means to open his cage.\n\nI will remain here to protect Apprentice Webb and keep the area secure.", objectives = "" }
WordHunterWoW_QuestEN[50266] = { title = "Bittersweet", description = "Hey!\n\nI need to get out of here and get back to Falconhurst! My husband and I were looking for my daughter's favorite toy when I was taken. Please, I need to get out of here! I need to know my family is safe. \n\nThey took my gear. It's all around camp. Get me out of here then bring back my gear, please!", objectives = "" }
WordHunterWoW_QuestEN[50268] = { title = "Give it a Little Juice", description = "Well, I admit that I feel a little better about this. If Witch Doctor Jangalar's voodoo can make Ben'jin react correctly, as the science says he should, then what do we have to lose? \n\nBless my formula or hex it or whatever they call it with Jangalar's voodoo cauldron.", objectives = "" }
WordHunterWoW_QuestEN[50270] = { title = "Deep In the Core", description = "Look, you're gonna have to travel to some place called Deepholm and find an earthen down there.\n\nThe guy who sold the recipe to me said he got it from an earthen called...Ormhun! Ormhun something.\n\nI don't know too much about that place, but maybe you can ask the locals or something where he lives.\n\nNow if you don't mind, I have more recipes to sell.", objectives = "" }
WordHunterWoW_QuestEN[50271] = { title = "Smash and Grab", description = "Most of the materials we'll need can be found right down here in the Deepholm.\n\nWe just need ta be discreet about it. If old Therazane catches wind of what we're up to, she might try ta put a stop ta it.\n\nBut let's not worry 'bout that. The first thing you'll need is diaminium. There are pillars that grow in the Alabaster Shelf rich with 'em.\n\nJust use yer old blacksmithin' hammer and smash those pillars ta bits. Don't worry about breaking the diaminium. We'll meld it all back tagether.", objectives = "" }
WordHunterWoW_QuestEN[50272] = { title = "An Ear to the Ground", description = "The next reagent ya need comes from the bellies of worms that burrow through this realm.\n\nWhile ya can find plenty o' worms all over, there's a certain type you'll need ta find. They're rarely seen above ground, but there are ways of coaxing 'em out.\n\nNamely making enough racket to piss 'em off! Ha ha! When ya see 'em rumblin' around beneath ya, use this thumper to draw 'em out.\n\nDeliver a killin' blow and get that metal from their wee bellies!", objectives = "" }
WordHunterWoW_QuestEN[50273] = { title = "Atal'Dazar: Locking Horns", description = "We've got tha metal for tha base and tha body, but there's one last part...\n\nTha horn of tha anvil was ta be made of ukrite. But that metal's been gone for ages.\n\nThere is another metal tha's very close ta it in terms of its durability. A type of gold tha trolls mined in abundance. And I know where ye can find it.\n\nTha trolls control an area called Atal'Dazar, a great city made o' tha stuff. If ye can find something horn-shaped in there, that'll save us tha trouble of shaping it from scratch.", objectives = "" }
WordHunterWoW_QuestEN[50274] = { title = "Titanic Forging", description = "Are ya ready, lad?\n\nYou'll be doing the hammerin' while I take care of the last reagent we'll need.", objectives = "" }
WordHunterWoW_QuestEN[50275] = { title = "Anvil's Away", description = "Take your anvil, and never speak of its methods of creation to anyone.\n\nShould I find out otherwise, you may find your next visit to my realm an unpleasant one.", objectives = "" }
WordHunterWoW_QuestEN[50276] = { title = "A Recipe For the Ages", description = "Say, ya look like you been swingin' da hammah around quite a bit, brudda. I can smell da flux on ya!\n\n<Zak'aal gives you a wide grin.>\n\nListen, I've got a recipe for da most amazin' blacksmit hammah ya ever be layin' ya eyes on. And I'd be willing ta let it go for a bit of ore.\n\nRevlis ore ta be exact. It be a little rare, but ya can find some of it over at Atal'Gral. Da naga dere use it ta make deir weapons.\n\nBring me back a haul of it, and da recipe be yours!", objectives = "" }
WordHunterWoW_QuestEN[50277] = { title = "Hammering Out Information", description = "Let me guess. You be lookin' at da recipe and noticed it require a Khaz'gorian Anvil ta make it. So now you be wantin' ta know where ta find a Khaz'gorian Smithing Anvil?\n\nLook, brudda, I never said anyting about bein' able ta craft da hamma. Now if ya don't mind, I have more of dese recipes ta be sellin'.", objectives = "" }
WordHunterWoW_QuestEN[50278] = { title = "Deep In the Core", description = "Look, ya gonna have ta travel ta Deepholm and convince dem ta be givin' up deir secrets. Dat's where da last anvil was made, or so I be hearin'.\n\nAnd I only be knowin' of one earten down dere who might be willin' ta work wit ya. His name be Ormhun Stonehamma'.\n\nHe be kind of an outcast, but not too hard ta find.", objectives = "" }
WordHunterWoW_QuestEN[50279] = { title = "Anvil's Away", description = "Take your anvil, and never speak of its methods of creation to anyone.\n\nShould I find out otherwise, you may find your next visit to my realm an unpleasant one.", objectives = "" }
WordHunterWoW_QuestEN[50288] = { title = "Therazane's Choice", description = "<You explain that you meant no disrespect to Therazane or to steal their secrets.>\n\nInteresting...\n\nI have a wonderful idea on how to solve this issue. Would you like to hear it?", objectives = "" }
WordHunterWoW_QuestEN[50297] = { title = "The Head of Her Enemy", description = "You have done a wonderful thing, {name}. With de destruction of Gloomtail, Maka'fon is no longer bothered by de presence of de razorwings. It seems dat Gloomtail destroyed her eggs some time ago. \n\nTake Gloomtail's head to Maka'fon as proof dat he is gone. When she finds de scent of Ben'jin on it, she will once again seek a worthy mate. \n\nWhen Ben'jin senses dat, he will approach and nature will take over.", objectives = "" }
WordHunterWoW_QuestEN[50303] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "" }
WordHunterWoW_QuestEN[50305] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the ren'dorei is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "" }
WordHunterWoW_QuestEN[50306] = { title = "Odds and Ends", description = "Master Ashton's going to probably need something bracing once we get him free. I know of a quick potion guaranteed to get anyone to snap out of it, but I'm going to need a few things first.\n\nThose wicker dogs down there have some organic parts I can use and the witches are carrying bags of reagents. They'll almost certainly have what I need.\n\nBring those to me and I'll handle the rest once we get Master Ashton back.", objectives = "" }
WordHunterWoW_QuestEN[50313] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like the devout sort. We have a lovely cathedral that will no doubt be of interest! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the Lightforged is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "" }
WordHunterWoW_QuestEN[50316] = { title = "Disturbance Detected: Ulduar", description = "You're late. Don't you remember the last time we had to deal with the tampering that allowed Yogg-Saron to escape from his prison underneath Ulduar? You were late then too. You should really try to be more punctual.\n\nWell, get going! Old gods! Keepers! Titan stuff! Get this one checked off your list so we can move on. We've got times and places to be.\n\n<Vormu gestures impatiently for you to leave.>", objectives = "" }
WordHunterWoW_QuestEN[50318] = { title = "A Timely Summons from Northrend", description = "The blazing wanes in the shadow of a celestial mass, striking fear in to the seers. Seek out the sage Vormu in Dalaran, and lend her your aid.\n\nNo, not this Dalaran, the other one. Yes I know, it's terribly confusing.", objectives = "" }
WordHunterWoW_QuestEN[50319] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "" }
WordHunterWoW_QuestEN[50321] = { title = "Mojo Mischief", description = "De soldiers you rescued spoke of de raids on Zandalar. Blood troll raiders, frothing at de mouth and possessing supernatural strength, overwhelmed de defenders. \n\nDey say dat their strength came from flasks of mojo dat de raiders drink before going into combat. We cannot allow de blood trolls to continue to possess them.\n\nGo down into de camp and destroy any of their flasks you may find.", objectives = "" }
WordHunterWoW_QuestEN[50325] = { title = "Stopping the Grand Rite", description = "The witches of the Crimsonwood are planning a Grand Rite, a powerful ritual. They intend to rip open reality and bring their dark master through!\n\nI suspect they may be in communion with Gorak Tul. We cannot allow their ritual to succeed.\n\nI need you to be the tip of the spear while I protect Master Ashton and Marten. Cause havoc and disrupt their rituals!", objectives = "" }
WordHunterWoW_QuestEN[50326] = { title = "Ain't No Place Like Home", description = "Let me tell you, this is a big place, this Arathi Highlands, and I've no doubt at some point you are going to need to quick step it back to our lovely new base.\n\nHow about I help you out with that?", objectives = "" }
WordHunterWoW_QuestEN[50327] = { title = "A Little 'Pick Me Up'", description = "Now to mix this up. \n\n<Marten begins to combine the components in a mug>\n\nI'm using some rather strong grog as a base, a drop of chilli extract and a handful of hearthbloom... There!\n\n<Marten hands you a mug>\n\nIt will taste worse than it smells, but it will bring Master Ashton to his senses. Please give this mug to him.", objectives = "" }
